/* ---- Accessibility: icon-only buttons get a screen-reader name from their tooltip (title), ---- */
/* including buttons that are drawn later by render functions. */
(function(){
  function label(root){
    try{
      (root.querySelectorAll ? root.querySelectorAll('button[title]:not([aria-label]), [onclick][title]:not([aria-label])') : []).forEach(el=>{
        const t=el.getAttribute('title'); if(t) el.setAttribute('aria-label', t);
      });
    }catch(e){}
  }
  label(document);
  try{
    let pending=false;
    new MutationObserver(()=>{ if(pending) return; pending=true; setTimeout(()=>{ pending=false; label(document); }, 200); })
      .observe(document.body, {childList:true, subtree:true});
  }catch(e){}
})();

/* ===== js/12-organize.js ===== */
/* ============ গুছানো (v49): Home-এ সতর্কতা এক জায়গায় + "আরও" ভাঁজ, Settings ৫ গ্রুপে ============ */
const ORG_KEY='tr_orgState';
function orgGet(){ return lsGet(ORG_KEY,{}) || {}; }
function orgSet(patch){ lsSet(ORG_KEY,Object.assign(orgGet(),patch)); }

/* ---------- Home: তিনটা সতর্কতা বক্স → একটা স্ট্যাক (প্রথমটা দেখায়, বাকিগুলো "আরও N টি") ---------- */
let orgAlertsOpen=false;
function orgAlertSync(){
  const stack=document.getElementById('alertStack'); if(!stack) return;
  const cards=['backupNagBox','dueReminderBox','absenceRiskBox'].flatMap(id=>[...(document.getElementById(id)||{children:[]}).children]);
  const live=cards.filter(c=>(c.textContent||'').trim());
  live.forEach((c,i)=>c.classList.toggle('as-hide', !orgAlertsOpen && i>0));
  let chip=document.getElementById('alertMore');
  if(live.length<2){ if(chip) chip.remove(); return; }
  if(!chip){ chip=document.createElement('button'); chip.type='button'; chip.id='alertMore'; chip.className='as-more'; chip.onclick=()=>{ orgAlertsOpen=!orgAlertsOpen; orgAlertSync(); }; stack.appendChild(chip); }
  chip.setAttribute('aria-expanded',String(orgAlertsOpen));
  chip.textContent=orgAlertsOpen?'ভাঁজ করো ▴':`আরও ${enNum(live.length-1)}টি সতর্কতা ▾`;
}
/* ---------- Home: ডেকোরেটিভ আর্ক + বুস্টার "আরও" অংশে ---------- */
function orgMoreApply(){
  const open=!!orgGet().homeMore, box=document.getElementById('homeMore'), btn=document.getElementById('homeMoreBtn'); if(!box||!btn) return;
  box.hidden=!open; btn.setAttribute('aria-expanded',String(open)); btn.querySelector('.hm-ch').textContent=open?'▴':'▾';
  if(open){ try{ renderAll(); }catch(e){} }   // draws the arc + booster now that they are visible
}
function orgToggleMore(){ orgSet({homeMore:!orgGet().homeMore}); orgMoreApply(); }
function orgSetupHome(){
  const home=document.getElementById('pageHome'); if(!home || document.getElementById('alertStack')) return;
  const first=document.getElementById('backupNagBox'), hero=home.querySelector('.hero'), focus=document.getElementById('focusCard');
  if(first){
    const stack=document.createElement('div'); stack.id='alertStack'; stack.className='alert-stack'; first.parentNode.insertBefore(stack,first);
    ['backupNagBox','dueReminderBox','absenceRiskBox'].forEach(id=>{ const b=document.getElementById(id); if(b){ stack.appendChild(b); new MutationObserver(orgAlertSync).observe(b,{childList:true}); } });
    orgAlertSync();
  }
  if(hero && focus){
    const btn=document.createElement('button'); btn.type='button'; btn.id='homeMoreBtn'; btn.className='home-more-btn'; btn.onclick=orgToggleMore;
    btn.innerHTML='<span>'+ico('spark')+' আরও দেখো <small>দিনের আর্ক · আজকের বুস্টার</small></span><b class="hm-ch">▾</b>';
    const box=document.createElement('div'); box.id='homeMore'; box.hidden=true;
    hero.parentNode.insertBefore(btn,hero); hero.parentNode.insertBefore(box,hero); box.appendChild(hero); box.appendChild(focus);
    orgMoreApply();
  }
}

/* ---------- Settings: ১৪টা সেকশন → ৫টা গ্রুপ (ভাঁজ করা), খোলা/বন্ধ মনে রাখে ---------- */
const ORG_GROUPS=[
  {id:'backup', ic:'cloud', t:'ব্যাকআপ', s:'ব্যাকআপ নেওয়া ও হেলথ-চেক', keys:['💾','🩺']},
  {id:'safety', ic:'shield', t:'নিরাপত্তা', s:'ডেটা সুরক্ষা ও আর্থিক গোপনীয়তা', keys:['🛡️','🙈']},
  {id:'notif',  ic:'bell', t:'নোটিফিকেশন', s:'নোটিফিকেশন ও রিমাইন্ডার নোট', keys:['🔔','📝']},
  {id:'look',   ic:'palette', t:'চেহারা', s:'থিম ও সংখ্যার ধরন', keys:['🎨','🔢']},
  {id:'data',   ic:'layers', t:'ডেটা ও রিপোর্ট', s:'ক্যালেন্ডার, লেট ফি, রিভিউ, এক্সপোর্ট, সেশন', keys:null},
];
function orgGroupify(){
  const body=document.getElementById('settingsBody'); if(!body) return;
  const secs=[...body.children].filter(e=>e.classList.contains('settings-section')); if(!secs.length) return;
  obs.disconnect();
  const open=orgGet().setOpen||{}, pick=new Map(ORG_GROUPS.map(g=>[g.id,[]]));
  secs.forEach(s=>{ const t=(s.textContent||'').trim(); const g=ORG_GROUPS.find(x=>x.keys&&x.keys.some(k=>t.startsWith(k)))||ORG_GROUPS[ORG_GROUPS.length-1]; pick.get(g.id).push(s); });
  const anchor=secs[0];
  ORG_GROUPS.forEach(g=>{ const items=pick.get(g.id); if(!items.length) return;
    const wrap=document.createElement('div'); wrap.className='set-group'+(open[g.id]?' open':''); wrap.dataset.g=g.id;
    wrap.innerHTML=`<button type="button" class="sg-head" aria-expanded="${!!open[g.id]}" onclick="orgToggleGroup('${g.id}')"><span class="sg-ic">${ico(g.ic)}</span><span class="sg-tx"><b>${g.t}</b><small>${g.s}</small></span><i class="sg-ch">▾</i></button><div class="sg-body"></div>`;
    const inner=wrap.querySelector('.sg-body'); items.forEach(s=>inner.appendChild(s));
    body.insertBefore(wrap,anchor.parentNode===body?anchor:null);
  });
  obs.observe(body,{childList:true});
}
function orgToggleGroup(id){
  const open=Object.assign({},orgGet().setOpen||{}); open[id]=!open[id]; orgSet({setOpen:open});
  const w=document.querySelector(`.set-group[data-g="${id}"]`); if(w){ w.classList.toggle('open',!!open[id]); w.querySelector('.sg-head').setAttribute('aria-expanded',String(!!open[id])); }
}
const obs=new MutationObserver(()=>{ const b=document.getElementById('settingsBody'); if(b && [...b.children].some(e=>e.classList.contains('settings-section'))) orgGroupify(); });
(function init(){
  orgSetupHome();
  const b=document.getElementById('settingsBody'); if(b){ obs.observe(b,{childList:true}); orgGroupify(); }
})();

/* ---------- "সব ইংরেজি" মোডে হাতে-লেখা বাংলা সংখ্যাও (০-৯ → 0-9) বদলে দেয়, পরে আসা লেখাতেও ---------- */
(function numEnDom(){
  if(_numMode!=='en') return;
  document.body.classList.add('num-en');
  const MAP={'০':'0','১':'1','২':'2','৩':'3','৪':'4','৫':'5','৬':'6','৭':'7','৮':'8','৯':'9'}, conv=t=>t.replace(/[০-৯]/g,c=>MAP[c]), HAS=/[০-৯]/, SKIP=/^(SCRIPT|STYLE|TEXTAREA)$/, ATTRS=['placeholder','title','aria-label'];
  function fixAttrs(el){ ATTRS.forEach(a=>{ const v=el.getAttribute(a); if(v&&HAS.test(v)) el.setAttribute(a,conv(v)); }); }
  function fix(root){
    if(root.nodeType===3){ if(HAS.test(root.nodeValue)) root.nodeValue=conv(root.nodeValue); return; }
    if(root.nodeType!==1 || SKIP.test(root.tagName)) return;
    fixAttrs(root);
    const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT|NodeFilter.SHOW_ELEMENT,{acceptNode:n=>(n.nodeType===1&&SKIP.test(n.tagName))?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT});
    let n; while((n=w.nextNode())){ if(n.nodeType===3){ if(HAS.test(n.nodeValue)) n.nodeValue=conv(n.nodeValue); } else fixAttrs(n); }
  }
  const queue=new Set(); let sched=false;
  const flush=()=>{ sched=false; const q=[...queue]; queue.clear(); q.forEach(n=>{ if(n.isConnected) fix(n); }); };
  new MutationObserver(ms=>{ ms.forEach(m=>{ if(m.type==='characterData') queue.add(m.target); else m.addedNodes.forEach(n=>queue.add(n)); }); if(!sched){ sched=true; requestAnimationFrame(flush); } })
    .observe(document.body,{childList:true,subtree:true,characterData:true});
  fix(document.body); document.title=conv(document.title);
})();

/* ---------- ট্যাপে হালকা টিক (ভাইব্রেশন) ---------- */
document.addEventListener('pointerdown',e=>{ if(e.target.closest&&e.target.closest('.nav-btn,.pct-chip,.kq button,.sg-head,.tm-sheet button,.home-more-btn,.as-more')) haptic('tick'); },{passive:true});

/* ---------- শিডিউল: "লিখে বলো" বক্সে উদাহরণ ও আইকনের মানে — দরকার হলে খোলে ---------- */
function orgCmdApply(){
  const st=orgGet(), ex=document.getElementById('cmdExamples'), lg=document.querySelector('.icon-legend');
  if(ex) ex.hidden=!st.cmdEx; if(lg) lg.hidden=!st.cmdLg;
  document.querySelectorAll('#cmdToggles button').forEach(b=>{ const on=!!st[b.dataset.k==='ex'?'cmdEx':'cmdLg']; b.classList.toggle('on',on); b.setAttribute('aria-expanded',String(on)); b.querySelector('i').textContent=on?'▴':'▾'; });
}
function orgCmdToggle(k){ const key=k==='ex'?'cmdEx':'cmdLg'; orgSet({[key]:!orgGet()[key]}); orgCmdApply(); }
(function setupSchedule(){
  const wrap=document.querySelector('.cmd-wrap'), ex=document.getElementById('cmdExamples'), lg=document.querySelector('.icon-legend');
  if(!wrap||!ex||!lg||document.getElementById('cmdToggles')) return;
  const row=document.createElement('div'); row.id='cmdToggles'; row.className='cmd-toggles';
  row.innerHTML='<button type="button" data-k="ex" onclick="orgCmdToggle(\'ex\')">উদাহরণ <i>▾</i></button><button type="button" data-k="lg" onclick="orgCmdToggle(\'lg\')">আইকনের মানে <i>▾</i></button>';
  ex.parentNode.insertBefore(row,ex);
  wrap.insertBefore(lg,document.getElementById('cmdResult'));
  orgCmdApply();
})();

/* ---------- রিপোর্ট: প্রতিটা অংশ ভাঁজ করা যায়; তথ্য না থাকা অংশ নিজে থেকে ভাঁজ থাকে ---------- */
function orgReportsGroup(){
  const body=document.getElementById('reportsBody'); if(!body) return;
  const st=(orgGet().rpOpen)||{};
  [...body.querySelectorAll(':scope > .settings-section-title')].forEach(t=>{
    const row=t.nextElementSibling; if(!row||!row.classList.contains('settings-row')) return;
    const txt=row.innerText||'', empty=!row.querySelector('input,canvas,.kh-bar') && (!!row.querySelector('.ins-empty') || (/এখনো|নেই/.test(txt) && txt.length<140));
    const key=t.textContent.replace(/[০-৯0-9()]/g,'').trim(), open=key in st ? !!st[key] : !empty;
    const sec=document.createElement('div'); sec.className='rp-sec'+(open?' open':'')+(empty?' empty':''); sec.dataset.k=key;
    sec.innerHTML=`<button type="button" class="rp-head" aria-expanded="${open}" onclick="orgReportToggle(this)"><span>${t.innerHTML}</span><i>▾</i></button><div class="rp-body"></div>`;
    t.parentNode.insertBefore(sec,t); sec.querySelector('.rp-body').appendChild(row); t.remove();
  });
}
function orgReportToggle(btn){
  const sec=btn.closest('.rp-sec'), open=!sec.classList.contains('open'); sec.classList.toggle('open',open); btn.setAttribute('aria-expanded',String(open));
  const st=Object.assign({},orgGet().rpOpen||{}); st[sec.dataset.k]=open; orgSet({rpOpen:st});
}
(function wrapInsights(){ if(typeof renderInsights!=='function') return; const orig=renderInsights; renderInsights=function(){ orig.apply(this,arguments); try{ orgReportsGroup(); }catch(e){} }; })();
try{ orgReportsGroup(); }catch(e){}

/* ===== js/13-khata-plus.js ===== */
/* ============ খাতা প্লাস (TallyKhata ভিডিও থেকে): নোট ও করণীয় চেকলিস্ট + গ্রাহক তালিকার ফিল্টার/সাজানো ============ */

/* ---------- নোট ও করণীয় (TallyKhata-র "ব্যবসার নোট"-এর মতো): যোগ · এডিট · টিক দিলে কাটা দাগ · মোছা ---------- */
const KH_NOTES_KEY='tr_khataNotes';
function getKhNotes(){ const v=lsGet(KH_NOTES_KEY,[]); return Array.isArray(v)?v:[]; }
function setKhNotes(a){ lsSet(KH_NOTES_KEY,a); }
/* pure (unit-tested): বাকি কাজ আগে (তারিখ ধরে, তারিখ নেই এমন নতুনগুলো শেষে), শেষ হওয়াগুলো নিচে */
function khNotesSorted(list){
  const arr=Array.isArray(list)?list:[];
  const pend=arr.filter(n=>!n.done).sort((a,b)=>{ const x=a.due||'9999-99-99', y=b.due||'9999-99-99'; return x<y?-1:(x>y?1:((b.at||0)-(a.at||0))); });
  const done=arr.filter(n=>n.done).sort((a,b)=>(b.doneAt||0)-(a.doneAt||0));
  return pend.concat(done);
}
function khNotesPending(){ return getKhNotes().filter(n=>!n.done).length; }
let khNoteEditId=null;
function khNotesBody(){
  const list=khNotesSorted(getKhNotes()), T=dateKeyStr(todayDateOnly()), pend=list.filter(n=>!n.done).length, done=list.length-pend;
  const row=n=>{
    const ed=khNoteEditId===n.id, late=!n.done&&n.due&&n.due<T, soon=!n.done&&n.due===T;
    const badge=n.due?`<small class="kn-due${late?' late':(soon?' soon':'')}">${late?'⏰ মেয়াদ পেরিয়েছে · ':(soon?'আজ · ':'')}${enDateLabel(new Date(n.due+'T00:00:00'))}</small>`:'';
    return `<div class="kn-row${n.done?' done':''}"><button type="button" class="kn-chk" aria-label="${n.done?'আবার বাকি করো':'শেষ হয়েছে'}" onclick="khNoteToggle('${n.id}')">${n.done?'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5.5 12.5l4.2 4.2 8.8-9.2"/></svg>':''}</button>`
      +(ed?`<div class="kn-txt"><input class="kh-in kn-edit" id="kn_edit" value="${escapeHtml(n.text)}" maxlength="200" onkeydown="if(event.key==='Enter'){event.preventDefault();khNoteEditSave('${n.id}');}else if(event.key==='Escape'){khNoteEditCancel();}"><div class="kn-edit-btns"><button type="button" class="pct-chip" onclick="khNoteEditCancel()">বাতিল</button><button type="button" class="pct-chip active" onclick="khNoteEditSave('${n.id}')">সেভ</button></div></div>`
        :`<div class="kn-txt" onclick="khNoteEditStart('${n.id}')">${escapeHtml(n.text)}${badge}</div><button type="button" class="kh-edit" aria-label="এডিট" onclick="khNoteEditStart('${n.id}')">${ico('edit')}</button><button type="button" class="prog-del-chapter" aria-label="মুছে ফেলো" onclick="khNoteDel('${n.id}')">✕</button>`)
      +`</div>`;
  };
  return `<div class="kn-add"><input class="kh-in" id="kn_text" placeholder="নতুন নোট বা করণীয় লেখো…" autocomplete="off" maxlength="200" onkeydown="if(event.key==='Enter'){event.preventDefault();khNoteAdd();}">
      <div class="kn-add2"><input class="kh-in" id="kn_due" type="date" aria-label="কবের মধ্যে (ঐচ্ছিক)"><button type="button" class="kh-fab" onclick="khNoteAdd()">＋ যোগ করো</button></div></div>
    ${list.length?`<div class="kn-count"><span>${enNum(pend)} টি বাকি · ${enNum(done)} টি শেষ</span>${done?`<button type="button" onclick="khNotesClearDone()">শেষগুলো মুছো</button>`:''}</div><div class="kn-list">${list.map(row).join('')}</div>`
      :emptyState({icon:'note',title:'কোনো নোট নেই',body:'টাকা-পয়সার কাজ মনে রাখতে এখানে লিখে রাখো — যেমন "রাকিবের কাছ থেকে শুক্রবার টাকা নেব"। কাজ শেষ হলে টিক দিলেই কাটা দাগ পড়বে।'})}`;
}
function khNotesRefresh(){ const b=document.getElementById('khNotesBox'); const body=document.getElementById('khataModalBody'); if(!body) return; if(b||body.querySelector('.kn-add')) body.innerHTML='<div id="khNotesBox">'+khNotesBody()+'</div>'; try{ renderKhataTab(); }catch(e){} }
function khNotesPage(){ khNoteEditId=null; showKhataModal('📝 নোট ও করণীয়','<div id="khNotesBox">'+khNotesBody()+'</div>'); }
function khNoteAdd(){
  const t=document.getElementById('kn_text'), d=document.getElementById('kn_due'); const text=((t&&t.value)||'').trim();
  if(!text){ showWarningToast('আগে কিছু লেখো।'); if(t) t.focus(); return; }
  const list=getKhNotes(); list.push({id:Date.now()+'_'+Math.random().toString(36).slice(2,6), text:text.slice(0,200), done:false, due:(d&&d.value)||'', at:Date.now()}); setKhNotes(list);
  khNotesRefresh(); try{ navigator.vibrate&&navigator.vibrate(8); }catch(e){}
}
function khNoteToggle(id){
  const list=getKhNotes(), n=list.find(x=>x.id===id); if(!n) return; n.done=!n.done; n.doneAt=n.done?Date.now():0; setKhNotes(list);
  try{ navigator.vibrate&&navigator.vibrate(10); }catch(e){} khNotesRefresh();
}
function khNoteEditStart(id){ khNoteEditId=id; khNotesRefresh(); setTimeout(()=>{ const i=document.getElementById('kn_edit'); if(i){ i.focus(); try{ i.setSelectionRange(i.value.length,i.value.length); }catch(e){} } },30); }
function khNoteEditCancel(){ khNoteEditId=null; khNotesRefresh(); }
function khNoteEditSave(id){
  const i=document.getElementById('kn_edit'), text=((i&&i.value)||'').trim(); if(!text){ showWarningToast('লেখা খালি রাখা যাবে না।'); return; }
  const list=getKhNotes(), n=list.find(x=>x.id===id); if(n){ n.text=text.slice(0,200); setKhNotes(list); }
  khNoteEditId=null; khNotesRefresh(); showSuccessToast('নোট আপডেট হয়েছে');
}
function khNoteDel(id){
  const before=JSON.stringify(getKhNotes()); setKhNotes(getKhNotes().filter(n=>n.id!==id)); khNotesRefresh();
  showUndoToast('নোট মুছে ফেলা হয়েছে',()=>{ setKhNotes(JSON.parse(before)); khNotesRefresh(); });
}
function khNotesClearDone(){
  const before=JSON.stringify(getKhNotes()); setKhNotes(getKhNotes().filter(n=>!n.done)); khNotesRefresh();
  showUndoToast('শেষ হওয়া নোটগুলো মুছে ফেলা হয়েছে',()=>{ setKhNotes(JSON.parse(before)); khNotesRefresh(); });
}

/* ---------- ফিল্টার ও সাজানো (গ্রাহক তালিকা): কাস্টমার/সাপ্লায়ার · পরিমাণ · সর্বশেষ লেনদেন ---------- */
let khFiltState={cust:true, supp:true, sort:'default'}, khFiltDraft='default';
function khFiltOpts(){ return {kinds:{customer:khFiltState.cust, supplier:khFiltState.supp}, sort:khFiltState.sort}; }
function khFiltActive(){ return !khFiltState.cust || !khFiltState.supp || khFiltState.sort!=='default'; }
function khFilterModal(){
  const s=khFiltState; khFiltDraft=s.sort;
  const opt=(v,l)=>`<button type="button" class="kf-opt${khFiltDraft===v?' on':''}" data-v="${v}" onclick="khFiltPick('${v}')"><i></i>${l}</button>`;
  showKhataModal('ফিল্টার', `<div class="kf-sec">কাদের দেখাবে</div>
    <label class="kf-chk"><input type="checkbox" id="kf_c" ${s.cust?'checked':''}><span>কাস্টমার</span></label>
    <label class="kf-chk"><input type="checkbox" id="kf_s" ${s.supp?'checked':''}><span>সাপ্লায়ার</span></label>
    <div class="kf-sec">দেবো / পাবো পরিমাণ</div><div class="kf-grid">${opt('amt_asc','কম → বেশি')}${opt('amt_desc','বেশি → কম')}</div>
    <div class="kf-sec">সর্বশেষ লেনদেন</div><div class="kf-grid">${opt('last_new','নতুন → পুরাতন')}${opt('last_old','পুরাতন → নতুন')}</div>
    <button class="kh-fab" style="margin-top:18px;" onclick="khFiltApply()">নিশ্চিত</button>
    <button type="button" class="settings-btn" onclick="khFiltReset()">সব ফিল্টার সরাও</button>`);
}
function khFiltPick(v){ khFiltDraft=(khFiltDraft===v)?'default':v; document.querySelectorAll('.kf-opt').forEach(b=>b.classList.toggle('on',b.dataset.v===khFiltDraft)); }
function khFiltApply(){
  const c=document.getElementById('kf_c').checked, s=document.getElementById('kf_s').checked;
  if(!c && !s){ showWarningToast('কাস্টমার বা সাপ্লায়ার — অন্তত একটা বেছে নাও।'); return; }
  khFiltState={cust:c, supp:s, sort:khFiltDraft}; closeKhataModal(); renderKhataTab();
}
function khFiltReset(stay){ khFiltState={cust:true, supp:true, sort:'default'}; khFiltDraft='default'; if(!stay) closeKhataModal(); renderKhataTab(); }

/* ===== js/14-autobackup.js ===== */
/* ============ স্বয়ংক্রিয় অনলাইন ব্যাকআপ ============ */
/* নেট থাকলে ডেটা বদলালেই নিজে থেকে ব্যাকআপ যায় — অনুমতি লাগে না। নেট না থাকলে অপেক্ষায় থাকে, নেট এলেই পাঠায়। */
/* ফোনেই AES-GCM দিয়ে এনক্রিপ্ট হয়ে যায়; সার্ভারে শুধু অর্থহীন লেখা থাকে। খোলার চাবি = ফোনের রিকভারি কোড। */
const AB_KEY='tr_abKey', AB_HASH='tr_abHash', AB_AT='tr_abAt', AB_ERR='tr_abErr', AB_ON='tr_abOn', AB_URL='/.netlify/functions/backup';
const AB_ALPHA='ABCDEFGHJKMNPQRSTUVWXYZ23456789';        // no 0/O/1/I/L — easy to read out and type
function abNorm(k){ return String(k||'').toUpperCase().replace(/[^A-Z0-9]/g,''); }
function abFmt(k){ return abNorm(k).replace(/(.{4})(?=.)/g,'$1-'); }
function abEnabled(){ return lsGet(AB_ON,true)!==false; }
function abGetKey(){
  let k=abNorm(lsGet(AB_KEY,''));
  if(k.length!==20){ const out=[]; while(out.length<20){ const b=crypto.getRandomValues(new Uint8Array(32)); for(const x of b){ if(x<248 && out.length<20) out.push(AB_ALPHA[x%31]); } } k=out.join(''); lsSet(AB_KEY,k); }
  return k;
}
async function abSha(str){ return new Uint8Array(await crypto.subtle.digest('SHA-256', new TextEncoder().encode(str))); }
async function abIdOf(key){ return [...(await abSha('tr-id:'+abNorm(key)))].map(x=>x.toString(16).padStart(2,'0')).join('').slice(0,40); }
async function abAesKey(key){ return crypto.subtle.importKey('raw', await abSha('tr-enc:'+abNorm(key)), 'AES-GCM', false, ['encrypt','decrypt']); }
async function abStream(bytes, TransformCtor, kind){ const s=new Blob([bytes]).stream().pipeThrough(new TransformCtor(kind)); return new Uint8Array(await new Response(s).arrayBuffer()); }
async function abPack(text, key){
  let bytes=new TextEncoder().encode(text), z=0;
  if(typeof CompressionStream!=='undefined'){ try{ bytes=await abStream(bytes, CompressionStream, 'gzip'); z=1; }catch(e){ bytes=new TextEncoder().encode(text); } }
  const iv=crypto.getRandomValues(new Uint8Array(12)), ct=await crypto.subtle.encrypt({name:'AES-GCM', iv}, await abAesKey(key), bytes);
  return {v:1, z, iv:b64FromBytes(iv), data:b64FromBytes(ct)};
}
async function abUnpack(blob, key){
  let bytes=new Uint8Array(await crypto.subtle.decrypt({name:'AES-GCM', iv:bytesFromB64(blob.iv)}, await abAesKey(key), bytesFromB64(blob.data)));
  if(blob.z) bytes=await abStream(bytes, DecompressionStream, 'gzip');
  return JSON.parse(new TextDecoder().decode(bytes));
}
function abHashOf(s){ let h=0x811c9dc5; for(let i=0;i<s.length;i++){ h^=s.charCodeAt(i); h=Math.imul(h,0x01000193)>>>0; } return h.toString(16)+':'+s.length; }
let abBusy=false;
async function abRun(o){
  o=o||{};
  if(abBusy) return false;
  if(!o.force && !abEnabled()) return false;
  if(!(window.crypto && crypto.subtle)) return false;
  if(!navigator.onLine){ if(o.manual) showWarningToast('এখন ইন্টারনেট নেই — নেট এলে নিজে থেকেই ব্যাকআপ হয়ে যাবে।'); abRefreshCard(); return false; }
  const data=collectBackupData(); if(!Object.keys(data).length){ if(o.manual) showWarningToast('ব্যাকআপ নেওয়ার মতো কোনো তথ্য এখনো নেই।'); return false; }
  const dataStr=JSON.stringify(data), h=abHashOf(dataStr);
  if(!o.force && h===lsGet(AB_HASH,'')) return false;                       // nothing changed since the last good upload
  abBusy=true; abRefreshCard();
  try{
    const key=abGetKey(), id=await abIdOf(key), blob=await abPack(JSON.stringify({app:'tuition-routine', v:1, exportedAt:new Date().toISOString(), data}), key);
    const ctrl=new AbortController(), to=setTimeout(()=>ctrl.abort(), 25000);
    let res; try{ res=await fetch(AB_URL,{method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({action:'put', id, blob}), signal:ctrl.signal}); } finally { clearTimeout(to); }
    if(!res.ok) throw new Error(res.status===413?'তথ্য অনেক বড়':(res.status===404?'সার্ভারে ব্যাকআপ ফাংশন পাওয়া যায়নি':'সার্ভার '+res.status));
    const now=new Date().toISOString(); lsSet(AB_HASH,h); lsSet(AB_AT,now); lsSet(AB_ERR,''); lsSet('tr_lastBackupAt',now);
    try{ renderBackupNag(); }catch(e){}
    if(o.manual) showSuccessToast('অনলাইন ব্যাকআপ হয়ে গেছে ✅');
    return true;
  }catch(e){
    const msg=(e&&e.name==='AbortError')?'নেট খুব ধীর':String((e&&e.message)||e); lsSet(AB_ERR,msg);
    if(o.manual) showWarningToast('ব্যাকআপ হয়নি: '+msg);
    return false;
  }finally{ abBusy=false; abRefreshCard(); }
}
async function abRestoreFlow(){
  const mine=lsGet(AB_KEY,'');
  const inp=prompt('অনলাইন ব্যাকআপের রিকভারি কোড লেখো (এই ফোনের কোডটাই বসানো আছে; নতুন ফোনে পুরনো ফোনের কোড দাও):', mine?abFmt(mine):'');
  if(inp===null) return;
  const key=abNorm(inp); if(key.length!==20){ showWarningToast('কোডটা ২০ অক্ষরের হবে — আবার দেখো।'); return; }
  if(!navigator.onLine){ showWarningToast('ইন্টারনেট ছাড়া অনলাইন ব্যাকআপ আনা যাবে না।'); return; }
  try{
    const res=await fetch(AB_URL,{method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({action:'get', id:await abIdOf(key)})});
    if(res.status===404){ showWarningToast('এই কোডে কোনো ব্যাকআপ পাওয়া যায়নি।'); return; }
    if(!res.ok) throw new Error('server');
    const rec=await res.json(); let payload;
    try{ payload=await abUnpack(rec.blob, key); }catch(e){ showWarningToast('কোড ভুল, অথবা ব্যাকআপটা নষ্ট।'); return; }
    if(!validateBackupPayload(payload)){ showWarningToast('ব্যাকআপের ভেতরের তথ্য ঠিক নেই।'); return; }
    payload._abKey=key; if(!payload.exportedAt) payload.exportedAt=rec.savedAt;
    showImportPreview(payload);
  }catch(e){ showWarningToast('অনলাইন ব্যাকআপ আনা যায়নি — নেট দেখে আবার চেষ্টা করো।'); }
}
function abToggle(){ lsSet(AB_ON, !abEnabled()); abRefreshCard(); if(abEnabled()) abRun(); }
function abShowCode(){ const k=abFmt(abGetKey()); const el=document.getElementById('abCode'); if(!el) return; el.style.display='block'; el.innerHTML=`<div style="font-size:11.5px;color:var(--muted);margin-bottom:6px;">রিকভারি কোড — কোথাও লিখে বা কপি করে রাখো:</div><div style="font-family:'JetBrains Mono',monospace;font-size:16px;font-weight:700;letter-spacing:1px;text-align:center;padding:10px;border-radius:var(--r-md);background:var(--ov006);color:var(--gold);user-select:all;">${k}</div><button class="settings-btn" onclick="abCopyCode()">📋 কোড কপি করো</button>`; }
function abCopyCode(){ const k=abFmt(abGetKey()); try{ navigator.clipboard.writeText(k).then(()=>showSuccessToast('কোড কপি হয়েছে'),()=>showWarningToast('কপি হয়নি — কোডটা নিজে লিখে রাখো।')); }catch(e){ showWarningToast('কপি হয়নি — কোডটা নিজে লিখে রাখো।'); } }
function abStatusHtml(){
  if(!abEnabled()) return '<div class="backup-status backup-status-warn">⏸ স্বয়ংক্রিয় ব্যাকআপ বন্ধ আছে</div>';
  const at=lsGet(AB_AT,null), err=lsGet(AB_ERR,''), changed=abHashOf(JSON.stringify(collectBackupData()))!==lsGet(AB_HASH,'');
  const when=at?(()=>{ const d=new Date(at), days=Math.floor((Date.now()-d.getTime())/86400000), hm=toBn(String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0')); return (days<=0?'আজ':days===1?'গতকাল':toBn(days)+' দিন আগে')+', '+hm; })():'';
  if(abBusy) return '<div class="backup-status">⏳ ব্যাকআপ হচ্ছে…</div>';
  if(!navigator.onLine) return `<div class="backup-status${changed?' backup-status-warn':''}">📴 অফলাইন — ${changed?'নতুন বদল জমে আছে, নেট এলেই নিজে থেকে ব্যাকআপ হবে':'সবই ব্যাকআপ করা আছে'}${when?` (সর্বশেষ: ${when})`:''}</div>`;
  if(err && changed) return `<div class="backup-status backup-status-warn">⚠️ সর্বশেষ চেষ্টা ব্যর্থ (${escapeHtml(err)}) — আবার চেষ্টা করবে</div>`;
  return `<div class="backup-status">${at?`☁️ সর্বশেষ অনলাইন ব্যাকআপ: ${when}${changed?' · নতুন বদল পাঠানো হবে':''}`:'☁️ চালু আছে — এখনো প্রথম ব্যাকআপ যায়নি'}</div>`;
}
function abCardHtml(){
  return `<div id="abCard" class="ab-card">${abCardInner()}</div>`;
}
function abCardInner(){
  return `<div style="font-size:12.5px;font-weight:700;color:var(--paper);margin-bottom:4px;">☁️ স্বয়ংক্রিয় অনলাইন ব্যাকআপ</div>
    <div style="font-size:11.5px;color:var(--muted);line-height:1.6;margin-bottom:8px;">নেট থাকলে ডেটা বদলালেই নিজে থেকে ব্যাকআপ হয়ে যায় — কিছু চাপতে হয় না। নেট না থাকলে অ্যাপ অফলাইনেই চলে, নেট এলে জমে থাকা বদল পাঠিয়ে দেয়। ডেটা ফোনেই এনক্রিপ্ট হয়ে যায়, রিকভারি কোড ছাড়া কেউ পড়তে পারে না।</div>
    ${abStatusHtml()}
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:8px;"><button class="settings-btn" style="margin:0;" onclick="abRun({force:true,manual:true})">☁️ এখনই ব্যাকআপ</button><button class="settings-btn" style="margin:0;" onclick="abToggle()">${abEnabled()?'⏸ বন্ধ করো':'▶️ চালু করো'}</button></div>
    <button class="settings-btn" onclick="abRestoreFlow()">📥 অনলাইন ব্যাকআপ থেকে ফিরিয়ে আনো</button>
    <button class="settings-btn" onclick="abShowCode()">🔑 রিকভারি কোড দেখো (নতুন ফোনে লাগবে)</button>
    <div id="abCode" style="display:none;margin-top:8px;"></div>`;
}
function abRefreshCard(){ const c=document.getElementById('abCard'); if(!c) return; const code=document.getElementById('abCode'), open=code&&code.style.display==='block'; c.innerHTML=abCardInner(); if(open) abShowCode(); }
window.addEventListener('online', ()=>{ abRefreshCard(); setTimeout(()=>abRun(),1500); });     // নেট ফিরলেই জমে থাকা বদল পাঠাও
window.addEventListener('offline', abRefreshCard);
document.addEventListener('visibilitychange', ()=>{ if(!document.hidden) setTimeout(()=>abRun(),1500); });
setInterval(()=>abRun(), 120000);
setTimeout(()=>abRun(), 6000);

/* ===== js/15-radar.js ===== */
/* ============ 💎 আয়ের রাডার — তোমার টিউশনের আসল ঘণ্টা-প্রতি আয় ============ */
/* ফি ÷ আসলে কত সময় লাগে (ক্লাস + যাওয়া-আসা, গ্রুপে সময় ভাগ হয়)। কে লাভজনক, ফি কোথায় কম, ফাঁকা স্লটে কত আয় বাড়ার সুযোগ, */
/* আর লক্ষ্যে পৌঁছাতে কী লাগবে — সব তোমার নিজের শিডিউল ও ফি থেকে, ফোনেই হিসাব হয়। */

/* pure (unit-tested). slots:[{num,start,end}], cellOf(slot,day)->"নাম, নাম", feeOf(name)->monthly fee.
   o:{travel: minutes added to every busy slot, weeks: weeks per month (4.33), goal: target monthly income, days:[...]} */
function radarCompute(slots, cellOf, feeOf, o){
  o=o||{};
  const travel=Math.max(0,Number(o.travel)||0), W=o.weeks||4.33, days=o.days||['Sat','Sun','Mon','Tue','Wed','Thu','Fri'], goal=Math.max(0,Number(o.goal)||0);
  const st={}, free=[], grid=[]; let busyMin=0, busyLen=0, busyN=0;
  slots.forEach(sl=>{
    const row=[], len=Math.max(0,sl.end-sl.start), used=days.some(d=>String(cellOf(sl,d)||'').split(',').some(x=>x.trim()));   // a period you never teach in is not "free time you could sell"
    days.forEach(d=>{
      const names=[...new Set(String(cellOf(sl,d)||'').split(',').map(s=>s.trim()).filter(Boolean))];
      row.push(names.length);
      if(!names.length){ if(used) free.push({num:sl.num, day:d, len}); return; }
      busyN++; busyMin+=len+travel; busyLen+=len;
      names.forEach(n=>{ const s=st[n]||(st[n]={name:n, sessions:0, min:0}); s.sessions++; s.min+=(len+travel)/names.length; });   // a group shares one slot, so each child carries only a share of the teacher's time
    });
    grid.push(row);
  });
  const busyHrs=busyMin/60*W;
  const rows=Object.values(st).map(s=>{ const fee=Math.max(0,Number(feeOf(s.name))||0), hrs=s.min/60*W; return {name:s.name, fee, sessions:s.sessions, hours:hrs, rate:(fee>0&&hrs>0)?fee/hrs:0}; });
  const paid=rows.filter(r=>r.fee>0), income=paid.reduce((t,r)=>t+r.fee,0), avg=busyHrs>0?income/busyHrs:0;
  rows.forEach(r=>{ r.pct=avg>0&&r.rate>0?r.rate/avg:0; r.tag=r.fee<=0?'nofee':(r.pct<0.7?'low':(r.pct>=1.3?'high':'ok'));
    r.raiseTo=(r.tag==='low')?Math.ceil(avg*r.hours/50)*50:0; r.raiseBy=r.raiseTo?r.raiseTo-r.fee:0; r.dropLoses=r.fee; r.dropFrees=r.hours; });
  rows.sort((a,b)=>(b.rate-a.rate)||a.name.localeCompare(b.name));
  const avgLen=busyN?busyLen/busyN:0, perSlot=avg>0?Math.round(avg*(avgLen+travel)/60*W):0;      // income from filling one more weekly slot with one paying student
  const res={rows, income, busyHrs, avg, weeklyHrs:busyHrs/W, free, grid, perSlot, noFee:rows.filter(r=>r.tag==='nofee').map(r=>r.name), goal:null};
  if(goal>0){ const gap=goal-income; res.goal={target:goal, gap:Math.max(0,gap), met:gap<=0, needSlots:(gap>0&&perSlot>0)?Math.ceil(gap/perSlot):0, freeSlots:free.length, raisePct:(gap>0&&income>0)?Math.ceil(gap/income*100):0}; res.goal.feasible=res.goal.met||(perSlot>0&&res.goal.needSlots<=free.length); }
  return res;
}
const RD_TRAVEL_KEY='tr_radarTravel', RD_GOAL_KEY='tr_radarGoal';
function radarTravel(){ const v=Number(lsGet(RD_TRAVEL_KEY,15)); return isFinite(v)?Math.max(0,Math.min(120,v)):15; }
function radarGoal(){ const v=Number(lsGet(RD_GOAL_KEY,0)); return isFinite(v)&&v>0?v:0; }
function radarData(){
  return radarCompute(SCHEDULE, getCellText, n=>getStudentPayment(n).monthlyFee, {travel:radarTravel(), goal:radarGoal(), days:DAYS});
}
function radarCardHtml(){
  if(isFinanceHidden()) return `<div class="rd-card rd-locked"><div class="rd-card-t">💎 আয়ের রাডার</div><div class="rd-card-s">🙈 আর্থিক হিসাব লুকানো আছে — "দেখাও" চেপে আনলক করলে তোমার আসল ঘণ্টা-প্রতি আয় দেখা যাবে।</div></div>`;
  const d=radarData();
  if(!(d.avg>0)) return `<div class="rd-card" onclick="radarOpen()"><div class="rd-card-t">💎 আয়ের রাডার</div><div class="rd-card-s">শিক্ষার্থীদের মাসিক ফি দিলে এখানে তোমার আসল ঘণ্টা-প্রতি আয়, কে লাভজনক আর কোথায় সুযোগ — সব দেখাবে।</div></div>`;
  const low=d.rows.filter(r=>r.tag==='low').length;
  return `<div class="rd-card" onclick="radarOpen()"><div class="rd-card-t">💎 আয়ের রাডার</div>
    <div class="rd-card-n">${bnTaka(d.avg)}<small> / ঘণ্টা</small></div>
    <div class="rd-card-s">সপ্তাহে ~${toBn(Math.round(d.weeklyHrs))} ঘণ্টা (যাওয়া-আসাসহ) · ${low?`${toBn(low)} জনের ফি গড়ের চেয়ে অনেক কম`:'কারো ফি গড়ের চেয়ে উল্লেখযোগ্য কম নয়'} · ${toBn(d.free.length)} টি ফাঁকা স্লট</div>
    <div class="rd-card-go">পুরো রাডার দেখো ›</div></div>`;
}
function radarOpen(){
  if(isFinanceHidden()){ showWarningToast('আগে আর্থিক হিসাব আনলক করো (রিপোর্ট ট্যাবের উপরে "দেখাও")।'); return; }
  showKhataModal('💎 আয়ের রাডার', radarBody());
}
function radarRefresh(){ const b=document.getElementById('khataModalBody'); if(b && b.querySelector('#rdBox')){ const y=b.scrollTop; b.innerHTML=radarBody(); b.scrollTop=y; } }
function radarTravelStep(n){ lsSet(RD_TRAVEL_KEY, Math.max(0,Math.min(120,radarTravel()+n))); radarRefresh(); }
function radarSetGoal(v){ const n=Math.round(parseFloat(String(bnDigitsToLatin(String(v||''))).replace(/[^0-9.]/g,''))||0); lsSet(RD_GOAL_KEY, n>0?n:0); radarRefresh(); }
function radarBody(){
  const d=radarData(), T=radarTravel(), max=Math.max(1,...d.rows.map(r=>r.rate)), dayNames=DAYS.map(x=>DAY_BN[x]);
  if(!(d.avg>0)) return `<div id="rdBox">${emptyState({icon:'chart',title:'এখনো হিসাব করার মতো ফি নেই',body:'শিক্ষার্থী প্রোফাইলে মাসিক ফি দিলে রাডার চালু হবে।'})}</div>`;
  const best=d.rows.find(r=>r.tag!=='nofee'), lows=d.rows.filter(r=>r.tag==='low').sort((a,b)=>b.raiseBy-a.raiseBy);
  const tips=[];
  if(lows[0]) tips.push(`<div class="rd-tip"><b>📈 ফি বাড়ানোর সুযোগ</b>${lows.slice(0,3).map(r=>`<div>${escapeHtml(r.name)}: এখন ${bnTaka(r.fee)} → গড়ের কাছে আনতে ≈ ${bnTaka(r.raiseTo)} <em>(+${bnTaka(r.raiseBy)})</em></div>`).join('')}</div>`);
  const groups=d.rows.filter(r=>r.tag==='high'); if(groups[0]) tips.push(`<div class="rd-tip"><b>🌟 সবচেয়ে লাভজনক</b><div>${groups.slice(0,3).map(r=>`${escapeHtml(r.name)} (${bnTaka(r.rate)}/ঘণ্টা)`).join(', ')} — একসঙ্গে পড়ানোয় সময় ভাগ হয়, তাই ঘণ্টা-প্রতি আয় বেশি।</div></div>`);
  if(d.free.length&&d.perSlot>0) tips.push(`<div class="rd-tip"><b>🕳️ ফাঁকা সময়ের দাম</b><div>সপ্তাহে ${toBn(d.free.length)} টি স্লট ফাঁকা। প্রতিটা স্লটে একজন ছাত্র পেলে মাসে গড়ে ≈ ${bnTaka(d.perSlot)} বাড়ে।</div></div>`);
  if(d.noFee.length) tips.push(`<div class="rd-tip rd-warn"><b>⚠️ ফি দেওয়া নেই</b><div>${d.noFee.map(escapeHtml).join(', ')} — এদের সময় হিসাবে ধরা হয়েছে, কিন্তু আয় ধরা হয়নি।</div></div>`);
  const g=d.goal;
  const goalHtml=`<div class="rd-sec">🎯 মাসিক আয়ের লক্ষ্য</div><div class="rd-goal"><input class="kh-in" inputmode="numeric" id="rd_goal" placeholder="লক্ষ্য কত টাকা? (যেমন ২৫০০০)" value="${radarGoal()||''}" onchange="radarSetGoal(this.value)">
    ${g?(g.met?`<div class="rd-goal-r ok">✅ লক্ষ্য ছাড়িয়ে গেছ — এখন মাসে ${bnTaka(d.income)}।</div>`
      :`<div class="rd-goal-r">আর লাগবে <b>${bnTaka(g.gap)}</b>।<br>${g.needSlots?`🔹 ${toBn(g.needSlots)} টি ফাঁকা স্লটে নতুন ছাত্র নিলে হবে (ফাঁকা আছে ${toBn(g.freeSlots)} টি) ${g.feasible?'✅':'— ফাঁকা স্লট কম পড়বে, ফিও বাড়াতে হবে'}`:''}<br>🔹 অথবা সবার ফি গড়ে প্রায় ${toBn(g.raisePct)}% বাড়ালে।</div>`):`<div class="rd-goal-r muted">লক্ষ্য দিলে বলে দেব কয়টা নতুন ছাত্র বা কত ফি বাড়ালে পৌঁছানো যাবে।</div>`}</div>`;
  const map=`<div class="rd-map"><div class="rd-mh"></div>${dayNames.map(x=>`<div class="rd-mh">${x}</div>`).join('')}${SCHEDULE.map((sl,i)=>`<div class="rd-ml">${PERIOD_ICON[sl.period]||''}${toBn(sl.num)}</div>${d.grid[i].map(n=>`<div class="rd-mc${n?' on':''}" title="${n} জন">${n?toBn(n):''}</div>`).join('')}`).join('')}</div>`;
  return `<div id="rdBox"><div class="rd-hero"><small>তোমার আসল ঘণ্টা-প্রতি আয়</small><b>${bnTaka(d.avg)}</b>
      <span>মাসে ${bnTaka(d.income)} ÷ ~${toBn(Math.round(d.busyHrs))} ঘণ্টা (ক্লাস + যাওয়া-আসা)</span>
      <div class="rd-trv"><span>যাওয়া-আসা প্রতি ক্লাসে</span><button type="button" onclick="radarTravelStep(-5)" aria-label="কমাও">−</button><b>${toBn(T)} মিনিট</b><button type="button" onclick="radarTravelStep(5)" aria-label="বাড়াও">+</button></div></div>
    ${tips.join('')}
    <div class="rd-sec">👥 কার কত — ঘণ্টা-প্রতি আয়</div>
    ${d.rows.map(r=>`<div class="rd-row ${r.tag}"><div class="rd-rn"><span>${escapeHtml(r.name)}</span><b>${r.rate?bnTaka(r.rate)+'/ঘণ্টা':'—'}</b></div><div class="rd-bar"><i style="width:${r.rate?Math.max(4,Math.round(r.rate/max*100)):0}%"></i></div><div class="rd-rs">ফি ${bnTaka(r.fee)} · সপ্তাহে ${toBn(r.sessions)} ক্লাস · মাসে ~${toBn(r.hours.toFixed(1))} ঘণ্টা${r.tag==='low'?' · <em>গড়ের চেয়ে কম</em>':''}${r.tag==='high'?' · <em class="g">গড়ের চেয়ে বেশি</em>':''}</div></div>`).join('')}
    ${goalHtml}
    <div class="rd-sec">🗓️ সপ্তাহের ম্যাপ — কোন স্লটে কয়জন</div>${map}
    <div class="rd-foot">হিসাব তোমার সাপ্তাহিক শিডিউল আর ফি থেকে, ১ মাস = ৪.৩৩ সপ্তাহ ধরে। ছুটি-মেকআপ ধরা হয়নি, তাই এটা মোটামুটি ছবি — নিখুঁত হিসাব নয়।</div></div>`;
}

/* ===== js/16-smart.js ===== */
/* ============ ✨ স্মার্ট সহকারী: ১) সিলেবাস পূর্বাভাস  ২) ছাত্র হারানোর আগাম সতর্কতা  ৩) ক্লাস শেষে ভয়েস রিপোর্ট ============ */

/* ======================= ১) 🧭 সিলেবাস পূর্বাভাস ======================= */
/* ইনপুট: অধ্যায়ের % + ডেডলাইন + শিডিউলের বাকি ক্লাস + এখন পর্যন্ত গড় গতি। আউটপুট: ডেডলাইনের আগে শেষ হবে কি না। */
/* pure (unit-tested): chapters:[{pct,targetDate}], sessions: আজের পরের নির্ধারিত ক্লাসের তারিখ (sorted), pace:{pace: অধ্যায়/ক্লাস}|null */
function sfForecast(o){
  const today=o.today, ch=(o.chapters||[]).filter(c=>c.targetDate), pace=(o.pace&&o.pace.pace>0)?o.pace.pace:0, S=o.sessions||[];
  const targets=[...new Set(ch.map(c=>c.targetDate))].sort(), items=[];
  targets.forEach(T=>{
    const need=ch.filter(c=>c.targetDate<=T).reduce((t,c)=>t+Math.max(0,100-(Number(c.pct)||0))/100,0);
    if(need<=0.0001) return;                                       // এই ডেডলাইন পর্যন্ত কাজ আগেই শেষ
    const overdue=T<today, left=overdue?0:S.filter(d=>d<=T).length, cap=pace*left;
    const status=overdue?'overdue':(!pace?'unknown':(cap>=need?'ok':(cap>=need*0.75?'risk':'behind')));
    const extra=pace>0?Math.ceil(Math.max(0,need-cap)/pace-1e-9):0;
    const projected=pace>0?(S[Math.ceil(need/pace-1e-9)-1]||''):'';
    items.push({T, need, left, status, extra, projected, speedUp:(pace>0&&cap>0)?need/cap:0, perClass:left>0?need/left:0});
  });
  const rank={overdue:4,behind:3,risk:2,unknown:1,ok:0};
  return {items, hasTargets:targets.length>0, status:items.length?items.reduce((w,i)=>rank[i.status]>rank[w]?i.status:w,'ok'):'done'};
}
/* pure: গতি = লগ থেকে (কমপক্ষে ৭ দিনের ব্যবধান), না হলে এ পর্যন্ত শেষ করা অংশ ÷ উপস্থিত ক্লাস */
function sfPaceFrom(log, classesIn, doneUnits, presentCount){
  const l=(log||[]).slice().sort((a,b)=>a.d<b.d?-1:1);
  if(l.length>=2){
    const a=l[0], b=l[l.length-1], days=Math.round((new Date(b.d+'T00:00:00')-new Date(a.d+'T00:00:00'))/86400000), n=classesIn(a.d,b.d);
    if(days>=7 && n>=2 && b.u-a.u>0) return {pace:(b.u-a.u)/n, src:'log'};
  }
  if(presentCount>=6 && doneUnits>0.1) return {pace:doneUnits/presentCount, src:'life'};
  return null;
}
function sfLogSnapshot(name){
  const d=getProgressData()[name]; if(!d) return;
  let u=0; Object.keys(d).forEach(s=>(d[s]||[]).forEach(c=>{ u+=(Number(c.pct)||0)/100; }));
  const all=lsGet('tr_progLog',{}), arr=all[name]||[], T=dateKeyStr(todayDateOnly());
  if(arr.length&&arr[arr.length-1].d===T) arr[arr.length-1].u=u; else arr.push({d:T,u});
  all[name]=arr.slice(-90); lsSet('tr_progLog',all);
}
function sfSnapAll(){ try{ Object.keys(getProgressData()).forEach(sfLogSnapshot); }catch(e){} }
function sfSessionDates(name, days){
  const out=[], base=todayDateOnly();
  for(let i=1;i<=days;i++){ const d=new Date(base); d.setDate(base.getDate()+i); const dow=DAYS[(d.getDay()+1)%7];
    if(SCHEDULE.some(s=>getCellText(s,dow).split(',').map(x=>x.trim()).includes(name))) out.push(dateKeyStr(d)); }
  return out;
}
function sfAll(){
  const prog=getProgressData(), ix=smIndex(), logs=lsGet('tr_progLog',{}), T=dateKeyStr(todayDateOnly()), res=[];
  Object.keys(prog).forEach(name=>{
    const chapters=[]; Object.keys(prog[name]||{}).forEach(s=>(prog[name][s]||[]).forEach(c=>chapters.push({subject:s, chapter:c.chapter, pct:c.pct, targetDate:c.targetDate||''})));
    if(!chapters.length) return;
    const present=(ix.att[name]||[]).filter(x=>x[1]==='present'||x[1]==='late').map(x=>x[0]);
    const classesIn=(a,b)=>present.filter(d=>d>=a&&d<=b).length;
    const done=chapters.reduce((t,c)=>t+(Number(c.pct)||0)/100,0);
    const pace=sfPaceFrom(logs[name], classesIn, done, present.length);
    const f=sfForecast({today:T, chapters, sessions:sfSessionDates(name,400), pace});
    res.push(Object.assign({name, pace, done, chapters}, f));
  });
  return res;
}
const SF_RANK={overdue:4,behind:3,risk:2,unknown:1,ok:0,done:-1};
const SF_CHIP={overdue:['🔴','ডেডলাইন পেরিয়েছে'],behind:['🔴','পিছিয়ে'],risk:['🟡','ঝুঁকিতে'],unknown:['⚪','গতি জানা নেই'],ok:['🟢','ঠিক পথে'],done:['✅','সব শেষ']};
function sfDateBn(ds){ return bnDateLabel(new Date(ds+'T00:00:00')); }
function sfItemText(it){
  const need=toBn(it.need.toFixed(1)), head=`<b>${sfDateBn(it.T)}</b>-এর মধ্যে বাকি ${need} অধ্যায়`;
  if(it.status==='overdue') return `${head} — ডেডলাইন পেরিয়ে গেছে।`;
  if(it.status==='unknown') return `${head}, ক্লাস আছে ${toBn(it.left)} টি → প্রতি ক্লাসে ${toBn(it.perClass.toFixed(2))} অধ্যায় করতে হবে।`;
  if(it.status==='ok') return `${head}, ক্লাস আছে ${toBn(it.left)} টি → এই গতিতে হয়ে যাবে ✅`;
  if(it.extra>Math.max(it.left,8)) return `${head}, ক্লাস আছে ${toBn(it.left)} টি → <b>এই গতিতে হবে না</b>, গতি অনেক কম। ডেডলাইন সরাও বা অধ্যায় কমাও — নয়তো প্রতি ক্লাসে অন্তত ${toBn(it.perClass.toFixed(2))} অধ্যায় করতে হবে।`;
  return `${head}, ক্লাস আছে ${toBn(it.left)} টি → এই গতিতে <b>${toBn(it.extra)} টি ক্লাস কম পড়বে</b>। ${it.projected?`শেষ হবে প্রায় ${sfDateBn(it.projected)}-তে।`:''} সমাধান: ডেডলাইনের আগে ${toBn(it.extra)} টি বাড়তি ক্লাস, অথবা গতি ${toBn(it.speedUp.toFixed(1))} গুণ বাড়াও।`;
}
function sfBody(){
  const all=sfAll(); sfSnapAll();
  const withT=all.filter(s=>s.hasTargets).sort((a,b)=>(SF_RANK[b.status]-SF_RANK[a.status])||a.name.localeCompare(b.name)), noT=all.filter(s=>!s.hasTargets);
  if(!all.length) return `<div id="sfBox">${emptyState({icon:'chart',title:'কোনো অধ্যায় যোগ করা নেই',body:'শিক্ষার্থীর প্রোফাইলে বিষয় ও অধ্যায় দাও, সঙ্গে ডেডলাইন — তাহলে এখানে পরীক্ষার আগে সিলেবাস শেষ হবে কি না বলে দেব।'})}</div>`;
  const cnt=k=>withT.filter(s=>s.status===k||(k==='behind'&&s.status==='overdue')).length;
  return `<div id="sfBox"><div class="sm-sum"><div><b>${toBn(cnt('behind'))}</b><span>পিছিয়ে</span></div><div><b>${toBn(cnt('risk'))}</b><span>ঝুঁকিতে</span></div><div><b>${toBn(cnt('ok'))}</b><span>ঠিক পথে</span></div></div>
    ${withT.map(s=>{ const c=SF_CHIP[s.status]||SF_CHIP.ok;
      return `<div class="sm-card ${s.status}"><div class="sm-card-h"><span>${escapeHtml(s.name)}</span><em>${c[0]} ${c[1]}</em></div>
        ${s.items.slice(0,3).map(it=>`<div class="sm-line">${sfItemText(it)}</div>`).join('')||'<div class="sm-line">সব ডেডলাইনের কাজ শেষ 🎉</div>'}
        <div class="sm-meta">${s.pace?`গতি ≈ ${toBn(s.pace.pace.toFixed(2))} অধ্যায়/ক্লাস (${s.pace.src==='log'?'আগের সপ্তাহগুলোর অগ্রগতি থেকে':'এ পর্যন্ত শেষ করা ÷ উপস্থিত ক্লাস, আনুমানিক'})`:'গতি বের করার মতো যথেষ্ট তথ্য নেই — কয়েক সপ্তাহ অধ্যায়ের % আপডেট করলে নির্ভুল হবে'}</div></div>`; }).join('')}
    ${noT.length?`<div class="sm-hint">⏳ ডেডলাইন দেওয়া নেই: ${noT.map(s=>escapeHtml(s.name)).join(', ')} — অধ্যায়ে "লক্ষ্য তারিখ" দিলে এদের পূর্বাভাসও পাবে।</div>`:''}
    <div class="rd-foot">ক্লাস গোনা হয়েছে সাপ্তাহিক শিডিউল ধরে (ছুটি/বাতিল ধরা হয়নি)। গতি প্রতিদিন নিজে থেকে জমা হয়, তাই সময়ের সঙ্গে আরও নির্ভুল হবে।</div></div>`;
}
function sfOpen(){ showKhataModal('🧭 সিলেবাস পূর্বাভাস', sfBody()); }

/* ======================= ২) 📉 ছাত্র হারানোর আগাম সতর্কতা ======================= */
/* pure (unit-tested). f: {recentMarked, recentAbsent, recentLate, prevMarked, prevAbsent, hwN, hwNone, hwPartial, dueMonths, curUnpaidLate, daysSinceSeen, makeups} */
function churnScore(f){
  const R=[]; let total=0; const add=(key,pts,text)=>{ if(pts>0){ total+=pts; R.push({key,pts:Math.round(pts),text}); } };
  const rate=f.recentMarked>=3?f.recentAbsent/f.recentMarked:0, prevRate=f.prevMarked>=3?f.prevAbsent/f.prevMarked:0;
  add('abs', Math.min(40, rate*100*0.8), `গত ৪ সপ্তাহে ${f.recentMarked} ক্লাসের মধ্যে ${f.recentAbsent} দিন অনুপস্থিত`);
  if(f.prevMarked>=3 && f.recentMarked>=3 && rate-prevRate>=0.15) add('trend',10,'আগের মাসের চেয়ে অনুপস্থিতি বাড়ছে');
  if(f.recentMarked>=3) add('late', Math.min(10, f.recentLate/f.recentMarked*20), `${f.recentLate} দিন দেরিতে এসেছে`);
  if(f.hwN>=3) add('hw', Math.min(15, (f.hwNone+f.hwPartial*0.5)/f.hwN*15), `শেষ ${f.hwN} ক্লাসের মধ্যে ${f.hwNone} দিন হোমওয়ার্ক করেনি`);
  let pay=0, ptxt=''; if(f.dueMonths>=2){ pay=25; ptxt=`${f.dueMonths} মাসের ফি বাকি`; } else if(f.dueMonths===1){ pay=15; ptxt='গত মাসের ফি বাকি'; }
  if(f.curUnpaidLate){ pay=Math.min(25,pay+8); ptxt=ptxt||'এই মাসের ফি এখনো আসেনি'; }
  add('pay', pay, ptxt);
  if(f.daysSinceSeen!=null && f.daysSinceSeen>=21) add('silent',15,`${f.daysSinceSeen} দিন ধরে ক্লাস হয়নি`);
  if(f.makeups>=2) add('makeup',5,`${f.makeups} টা মেকআপ ক্লাস বাকি`);
  const score=Math.min(100,Math.round(total)), enough=f.recentMarked>=3||f.hwN>=3||f.dueMonths>0||f.curUnpaidLate||(f.daysSinceSeen!=null&&f.daysSinceSeen>=21);
  R.sort((a,b)=>b.pts-a.pts);
  return {score, band:!enough?'nodata':(score>=55?'high':(score>=30?'medium':'low')), reasons:R};
}
/* pure: অভিভাবককে ভদ্র, দোষারোপহীন মেসেজ */
function churnMessage(o){
  const hi=`আসসালামু আলাইকুম${o.guardian?', '+o.guardian:''}।`, bye=o.teacher?`\n— ${o.teacher}`:'', n=o.name, k=o.key;
  if(k==='pay') return `${hi} ${n}-এর মাসিক ফি${o.amount?' '+o.amount:''} বাকি আছে। সুবিধামতো সময়ে পাঠিয়ে দিলে ভালো হয়। ধন্যবাদ।${bye}`;
  if(k==='hw') return `${hi} ${n} ইদানীং হোমওয়ার্ক কম করছে। বাসায় একটু খেয়াল রাখলে পড়াটা দ্রুত এগিয়ে যাবে। আমিও ক্লাসে নজর রাখছি।${bye}`;
  if(k==='silent') return `${hi} অনেকদিন ${n}-এর ক্লাস হয়নি। পড়াশোনা চালিয়ে যেতে চাইলে একটা সময় ঠিক করে নিই?${bye}`;
  if(k==='trend') return `${hi} ইদানীং ${n}-কে ক্লাসে একটু কম পাচ্ছি। সব ঠিক আছে তো? কোনো অসুবিধা থাকলে জানাবেন, ক্লাসের সময় বদলে নেওয়া যাবে।${bye}`;
  return `${hi} ${n}-কে কয়েকদিন ক্লাসে পাচ্ছি না। সব ঠিক আছে তো? কোনো অসুবিধা থাকলে জানাবেন, ক্লাসের সময় বদলে নিতে পারি।${bye}`;
}
/* attendance + homework grouped by student in ONE pass (so many students × a long history stays fast) */
function smIndex(){
  const att=getAttendanceMap(), notes=getNotes(), A={}, H={};
  Object.keys(att).forEach(k=>{ const p=k.split('|'), n=p.slice(2).join('|'); (A[n]=A[n]||[]).push([p[0],att[k]]); });
  Object.keys(notes).forEach(k=>{ const raw=notes[k]; if(!raw||!Array.isArray(raw.entries)) return; const d=k.split('|')[0]; raw.entries.forEach(e=>{ if(e.student&&e.hwStatus) (H[e.student]=H[e.student]||[]).push({d,s:e.hwStatus}); }); });
  return {att:A, hw:H};
}
function churnFeatures(name, ix){
  ix=ix||smIndex(); const base=todayDateOnly(), T=dateKeyStr(base);
  const back=n=>{ const d=new Date(base); d.setDate(base.getDate()-n); return dateKeyStr(d); }, c28=back(28), c84=back(84);
  const f={recentMarked:0,recentAbsent:0,recentLate:0,prevMarked:0,prevAbsent:0,hwN:0,hwNone:0,hwPartial:0,dueMonths:0,curUnpaidLate:false,daysSinceSeen:null,makeups:0};
  let latest=null;
  const mine=ix.att[name]||[];
  mine.forEach(([d,st])=>{
    if(st==='present'||st==='late'){ if(!latest||d>latest) latest=d; }
    if(st==='excused'||st==='cancelled'||st==='resched') return;
    if(d>c28&&d<=T){ f.recentMarked++; if(st==='absent') f.recentAbsent++; if(st==='late') f.recentLate++; }
    else if(d>c84&&d<=c28){ f.prevMarked++; if(st==='absent') f.prevAbsent++; }
  });
  (ix.hw[name]||[]).slice().sort((a,b)=>a.d<b.d?1:-1).slice(0,8).forEach(x=>{ f.hwN++; if(x.s==='none') f.hwNone++; else if(x.s==='partial') f.hwPartial++; });
  const fee=getStudentPayment(name).monthlyFee||0;
  if(fee>0){
    const d0=new Date(base.getFullYear(),base.getMonth(),1), first=mine.map(x=>x[0]).sort()[0]||T;
    for(let i=1;i<=2;i++){ const d=new Date(d0.getFullYear(),d0.getMonth()-i,1), mk=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0'); if(mk>=first.slice(0,7) && getStudentPaidForMonth(name,mk)<fee) f.dueMonths++; }
    if(base.getDate()>=15 && getStudentPaidForMonth(name,currentMonthKey())<fee) f.curUnpaidLate=true;
  }
  if(latest) f.daysSinceSeen=Math.round((base-new Date(latest+'T00:00:00'))/86400000);
  f.makeups=getMakeups().filter(m=>m.name===name).length;
  return f;
}
function churnAll(){
  const ix=smIndex();
  return getAllKnownNames().map(n=>{ const f=churnFeatures(n,ix), r=churnScore(f); return Object.assign({name:n,f},r); }).filter(x=>x.band!=='nodata').sort((a,b)=>b.score-a.score);
}
function smBn(s){ return String(s).replace(/\d+/g,m=>toBn(m)); }
const CH_CHIP={high:['🔴','উচ্চ ঝুঁকি'],medium:['🟡','মাঝারি'],low:['🟢','নিরাপদ']};
function churnBody(){
  const all=churnAll();
  if(!all.length) return `<div id="chBox">${emptyState({icon:'chart',title:'এখনো যথেষ্ট তথ্য নেই',body:'কয়েকটা ক্লাসের উপস্থিতি নিলে (আর হোমওয়ার্ক/ফি লিখলে) এখানে কে ছেড়ে দিতে পারে আগাম বলে দেব।'})}</div>`;
  const hi=all.filter(x=>x.band==='high').length, me=all.filter(x=>x.band==='medium').length, lo=all.filter(x=>x.band==='low').length;
  return `<div id="chBox"><div class="sm-sum"><div><b>${toBn(hi)}</b><span>উচ্চ ঝুঁকি</span></div><div><b>${toBn(me)}</b><span>মাঝারি</span></div><div><b>${toBn(lo)}</b><span>নিরাপদ</span></div></div>
    ${all.map(x=>{ const c=CH_CHIP[x.band], q=jsq(x.name);
      return `<div class="sm-card ${x.band}"><div class="sm-card-h"><span>${escapeHtml(x.name)}</span><em>${c[0]} ${c[1]} · ${toBn(x.score)}</em></div>
        <div class="rd-bar"><i style="width:${Math.max(3,x.score)}%"></i></div>
        ${x.reasons.slice(0,3).map(r=>`<div class="sm-line">• ${escapeHtml(isFinanceHidden()&&r.key==='pay'?'আর্থিক কারণ (আনলক করলে দেখা যাবে)':smBn(r.text))}</div>`).join('')||'<div class="sm-line">কোনো সতর্ক সংকেত নেই 👍</div>'}
        ${x.reasons.length?`<button type="button" class="pct-chip active" style="margin-top:8px;" onclick="churnMsgOpen('${q}')">📩 অভিভাবককে মেসেজ বানাও</button>`:''}</div>`; }).join('')}
    <div class="rd-foot">স্কোর = উপস্থিতি, দেরি, হোমওয়ার্ক, ফি, কতদিন ক্লাস হয়নি আর মেকআপ — সব মিলিয়ে ০–১০০। এটা ইঙ্গিত মাত্র, রায় নয়; আগে ছাত্র/অভিভাবকের সঙ্গে কথা বলো।</div></div>`;
}
function churnOpen(){ showKhataModal('📉 ছাত্র ঝুঁকি', churnBody()); }
function churnMsgOpen(name){
  const f=churnFeatures(name), r=churnScore(f), pr=getStudentProfile(name), top=(r.reasons[0]||{}).key||'abs';
  const due=(typeof getStudentTotalDue==='function')?getStudentTotalDue(name):0;
  smMsgPage(name, churnMessage({name, key:top, teacher:getTeacherName(false), guardian:(pr.guardianName||'').trim(), amount:(due>0&&!isFinanceHidden())?bnTakaOpen(due):''}));
}

/* ---------- মেসেজ পাতা (২ ও ৩ নম্বরে একই): এডিট করো → WhatsApp / কপি ---------- */
let smMsgName='';
function smMsgPage(name, text, extraHtml){
  smMsgName=name;
  showKhataModal('📩 মেসেজ — '+name, `<div style="font-size:11.5px;color:var(--muted);margin-bottom:6px;">পাঠানোর আগে দরকার মতো বদলে নাও:</div>
    <textarea id="sm_msg" class="kh-in" rows="10" style="resize:vertical;line-height:1.7;">${escapeHtml(text)}</textarea>
    <button class="kh-fab" style="margin-top:10px;" onclick="smSend()">📲 WhatsApp-এ পাঠাও</button>
    <button type="button" class="settings-btn" onclick="smCopy()">📋 কপি করো</button>${extraHtml||''}${typeof aiMsgHtml==='function'?aiMsgHtml():''}`);
}
function smSend(){ const pr=getStudentProfile(smMsgName); if(!(pr.guardianPhone||'').trim()) showWarningToast('অভিভাবকের ফোন সেভ করা নেই — WhatsApp-এ নিজে কন্টাক্ট বেছে নাও'); openWhatsApp(pr.guardianPhone, document.getElementById('sm_msg').value); }
function smCopy(){ const v=document.getElementById('sm_msg').value; try{ navigator.clipboard.writeText(v).then(()=>showSuccessToast('কপি হয়েছে'),()=>showWarningToast('কপি হয়নি')); }catch(e){ showWarningToast('কপি হয়নি'); } }

/* ======================= ৩) 🎙️ ক্লাস শেষে ভয়েস রিপোর্ট ======================= */
/* pure (unit-tested): মুখে বলা/লেখা এক টুকরো কথা → পড়ানো / হোমওয়ার্ক / পরের ক্লাস / মন্তব্য */
function vrParse(text){
  const out={taught:[],homework:[],next:[],remark:[]};
  String(text||'').split(/[।.!?\n]+/).map(s=>s.trim()).filter(Boolean).forEach(sen=>{
    if(/পরের ক্লাস|আগামী ক্লাস|পরবর্তী ক্লাস|পরের দিন|পরের বার|পরেরবার|পরের সপ্তাহ|আগামীকাল|কাল ক্লাসে/.test(sen)) out.next.push(sen);
    else if(/হোমওয়ার্ক|হোম ওয়ার্ক|বাড়ির কাজ|বাড়ীর কাজ|করে আসবে|করে আনবে|লিখে আনবে|শিখে আসবে|পড়ে আসবে|মুখস্থ/.test(sen)) out.homework.push(sen);
    else if(/ভালো করেছে|ভালো করেছ|ভালো বুঝেছে|মনোযোগ|দুর্বল|বেশি ভুল|অমনোযোগ|দেরিতে|দেরি করে|খেয়াল রাখ|উন্নতি|সমস্যা/.test(sen)) out.remark.push(sen);
    else out.taught.push(sen);
  });
  const j=a=>a.join('। ')+(a.length?'।':'');
  return {taught:j(out.taught), homework:j(out.homework), next:j(out.next), remark:j(out.remark)};
}
/* pure: অভিভাবকের জন্য রিপোর্ট; খালি অংশ বাদ */
function vrMessage(o){
  const L=['আসসালামু আলাইকুম'+(o.guardian?', '+o.guardian:'')+'।', `${o.name}-এর আজকের ক্লাসের সংক্ষিপ্ত রিপোর্ট${o.dateLabel?' ('+o.dateLabel+')':''}:`];
  const taught=String(o.taught||'').replace(/^আজ\s+/,''), next=String(o.next||'').replace(/^(পরের|আগামী|পরবর্তী)\s+ক্লাসে?,?\s*/,'');
  if(taught) L.push('📖 আজ যা পড়ানো হয়েছে: '+taught);
  if(o.homework) L.push('📝 বাড়ির কাজ: '+o.homework);
  if(next) L.push('🔜 পরের ক্লাসে: '+next);
  if(o.remark) L.push('💬 মন্তব্য: '+o.remark);
  L.push('ধন্যবাদ।'+(o.teacher?'\n— '+o.teacher:''));
  return L.join('\n');
}
function vrTodayNames(){
  const dow=DAYS[(todayDateOnly().getDay()+1)%7], set=[];
  SCHEDULE.forEach(s=>getCellText(s,dow).split(',').map(x=>x.trim()).filter(Boolean).forEach(n=>{ if(!set.includes(n)) set.push(n); }));
  const rest=getAllKnownNames().filter(n=>!set.includes(n)).sort((a,b)=>a.localeCompare(b));
  return {today:set, rest};
}
function vrOpen(){
  const {today,rest}=vrTodayNames(), opt=n=>`<option value="${escapeHtml(n)}">${escapeHtml(n)}</option>`;
  showKhataModal('🎙️ ক্লাস রিপোর্ট', `<div id="vrBox"><div style="font-size:12px;color:var(--muted);line-height:1.7;margin-bottom:8px;">ক্লাস শেষে ১০ সেকেন্ড বলো বা লেখো — যেমন: <i>"আজ ভগ্নাংশ যোগ করালাম। হোমওয়ার্ক পাতা ১২ করে আসবে। পরের ক্লাসে বিয়োগ ধরব। ভালো বুঝেছে।"</i> আমি গুছিয়ে অভিভাবকের মেসেজ বানিয়ে দেব।</div>
    <select id="vr_name" class="kh-in">${today.length?`<optgroup label="আজকের ক্লাসের ছাত্র">${today.map(opt).join('')}</optgroup>`:''}<optgroup label="সব ছাত্র">${rest.map(opt).join('')}</optgroup></select>
    <div style="position:relative;"><textarea id="vr_text" class="kh-in" rows="5" placeholder="এখানে লেখো বা 🎤 চেপে বলো…" style="padding-right:52px;"></textarea>
      <button type="button" class="mic-btn" data-mic="vr_text" aria-label="বলে লেখো" onclick="startVoice('vr_text',{append:true})" style="position:absolute;right:8px;top:8px;">${ICN.mic}</button></div>
    <button class="kh-fab" style="margin-top:10px;" onclick="vrMake()">✨ রিপোর্ট বানাও</button>
    <div style="font-size:10.5px;color:var(--muted);margin-top:8px;">🎤 বলে লেখা ইন্টারনেট লাগে (ফোনের স্পিচ সার্ভিস)। অফলাইনে কিবোর্ডের নিজের 🎤 দিয়ে বলো, অথবা টাইপ করো।</div></div>`);
}
function vrMake(){
  const name=(document.getElementById('vr_name')||{}).value, text=((document.getElementById('vr_text')||{}).value||'').trim();
  if(!name){ showWarningToast('আগে ছাত্র বেছে নাও।'); return; }
  if(!text){ showWarningToast('কিছু বলো বা লেখো।'); return; }
  const p=vrParse(text), pr=getStudentProfile(name), msg=vrMessage({name, guardian:(pr.guardianName||'').trim(), teacher:getTeacherName(false), dateLabel:bnDateLabel(todayDateOnly()), taught:p.taught, homework:p.homework, next:p.next, remark:p.remark});
  vrParsed={name, taught:p.taught, homework:p.homework, next:p.next};
  smMsgPage(name, msg, `<button type="button" class="settings-btn" onclick="vrSaveNote()">📓 ক্লাস-নোটেও সেভ করো (পড়ালাম · হোমওয়ার্ক · পরের পরিকল্পনা)</button>`);
}
let vrParsed=null;
function vrSaveNote(){
  if(!vrParsed) return; const d=todayDateOnly(), dow=DAYS[(d.getDay()+1)%7];
  const slot=SCHEDULE.find(s=>getCellText(s,dow).split(',').map(x=>x.trim()).includes(vrParsed.name));
  if(!slot){ showWarningToast('আজ এই ছাত্রের ক্লাস শিডিউলে নেই, তাই নোটে রাখা গেল না।'); return; }
  const entries=getNoteEntries(d,slot.num), mine=entries.find(e=>e.student===vrParsed.name&&!e.subject), rest=entries.filter(e=>e!==mine);
  const merged=Object.assign({student:vrParsed.name, subject:'', taught:'', homework:'', nextPlan:''}, mine||{});
  if(vrParsed.taught) merged.taught=vrParsed.taught; if(vrParsed.homework) merged.homework=vrParsed.homework; if(vrParsed.next) merged.nextPlan=vrParsed.next;
  setNoteEntries(d, slot.num, rest.concat([merged])); showSuccessToast('ক্লাস-নোটে সেভ হয়েছে');
}

/* ======================= রিপোর্ট ট্যাবের হাব কার্ড ======================= */
function smartHubHtml(){
  let sfLine='অধ্যায় ও ডেডলাইন দিলে পূর্বাভাস', chLine='উপস্থিতি নিলে ঝুঁকি দেখাবে';
  try{ const a=sfAll().filter(s=>s.hasTargets), bad=a.filter(s=>s.status==='behind'||s.status==='overdue').length, risk=a.filter(s=>s.status==='risk').length; if(a.length) sfLine=(bad||risk)?`${toBn(bad)} জন পিছিয়ে · ${toBn(risk)} জন ঝুঁকিতে`:'সবাই ঠিক পথে 🟢'; }catch(e){}
  try{ const c=churnAll(), hi=c.filter(x=>x.band==='high').length, me=c.filter(x=>x.band==='medium').length; if(c.length) chLine=(hi||me)?`${toBn(hi)} জন উচ্চ · ${toBn(me)} জন মাঝারি ঝুঁকি`:'কারো ঝুঁকি নেই 🟢'; }catch(e){}
  return `<div class="settings-section-title">✨ স্মার্ট সহকারী</div><div class="sm-grid">
    <button type="button" class="sm-tile glx-tile" onclick="aiChatOpen()"><b>🤖 AI জিজ্ঞেস করো</b><span>তোমার টিউশন নিয়ে বাংলায় প্রশ্ন করো — নাম ছাড়া, নিরাপদে</span></button>
    <button type="button" class="sm-tile glx-tile" onclick="fxOpen()"><b>🔮 ভবিষ্যৎ-যন্ত্র</b><span>১,৫০০টা সম্ভাব্য ভবিষ্যৎ চালিয়ে দেখো তোমার আয় কোথায় যেতে পারে</span></button>
    <button type="button" class="sm-tile glx-tile" onclick="glxOpen()"><b>🌌 ছাত্র-গ্যালাক্সি</b><span>তোমার টিউশনের জীবন্ত ত্রিমাত্রিক ব্রহ্মাণ্ড — টেনে ঘোরাও</span></button>
    <button type="button" class="sm-tile" onclick="sfOpen()"><b>🧭 সিলেবাস পূর্বাভাস</b><span>${sfLine}</span></button>
    <button type="button" class="sm-tile" onclick="churnOpen()"><b>📉 ছাত্র ঝুঁকি</b><span>${chLine}</span></button>
    <button type="button" class="sm-tile" onclick="dcOpen()"><b>🧠 সিদ্ধান্ত-সহকারী</b><span>কেন এমন হচ্ছে? · কী হলে কী হবে?</span></button>
    <button type="button" class="sm-tile" onclick="thkOpen()"><b>💭 চিন্তা-শক্তি</b><span>ছাত্রদের জন্য ৬ ধাপের ভাবনার প্রশ্ন</span></button>
    <button type="button" class="sm-tile" onclick="qpOpen()"><b>📝 নোট ও প্রশ্নপত্র</b><span>AI খসড়া → সম্পাদনা → অনুমোদন → A4 প্রিন্ট</span></button>
    <button type="button" class="sm-tile" onclick="resOpen()"><b>📊 ফল ও দুর্বলতা</b><span>কারণসহ দুর্বল অধ্যায় · অভিভাবকের ফল-রিপোর্ট</span></button>
    <button type="button" class="sm-tile" onclick="feeOpen()"><b>🧾 ফি ও হাজিরা</b><span>ছাড়/চার্জ · পেমেন্ট রিভার্স · হিসাব মেলানো</span></button>
    <button type="button" class="sm-tile" onclick="vrOpen()"><b>🎙️ ক্লাস রিপোর্ট</b><span>বলো → অভিভাবকের মেসেজ তৈরি</span></button></div>`;
}
setTimeout(sfSnapAll, 8000);

/* ===== js/17-galaxy.js ===== */
/* ============ 🌌 ছাত্র-গ্যালাক্সি — তোমার টিউশনের জীবন্ত ত্রিমাত্রিক ব্রহ্মাণ্ড ============ */
/* সূর্য = তুমি। প্রতিটা ছাত্র একটা গ্রহ: রং = ঝুঁকি/অগ্রগতি/আয় (মোড বদলাও), আকার = অগ্রগতি, কক্ষপথ = ক্লাসের সংখ্যা (ভেতরে বেশি), */
/* ঘোরার গতি = উপস্থিতি, লাল উপগ্রহ = ফি বাকি, ঝাপসা রেখা = একসঙ্গে পড়া ছাত্র। টেনে ঘোরাও, চিমটি কেটে জুম করো, ফোন হেলালে গভীরতা নড়ে। */

/* ---- pure (unit-tested) ---- */
function glxHash(s){ let h=2166136261>>>0; for(let i=0;i<s.length;i++){ h^=s.charCodeAt(i); h=Math.imul(h,16777619)>>>0; } return h; }
const GLX_BAND={low:'#5ef2c8', medium:'#f2c85e', high:'#ff6b81', nodata:'#8aa0ff'};
/* rows: [{name, progress 0..100, attendance null|0..100, band, sessions, fee, due, mates:[...]}] → planets on rings */
function glxBuild(rows, mode){
  mode=mode||'health';
  const maxFee=Math.max(1,...rows.map(r=>r.fee||0));
  /* বেশি ক্লাসের ছাত্র ভেতরের কক্ষপথে; কক্ষপথ ভরে গেলে পরেরটায় — যাতে ভিড় না হয় */
  const order=rows.slice().sort((a,b)=>(b.sessions||0)-(a.sessions||0)||a.name.localeCompare(b.name)), byRing={}; let k0=0, used=0;
  order.forEach(r=>{ if(used>=2+2*k0){ k0++; used=0; } (byRing[k0]=byRing[k0]||[]).push(r); used++; });
  const nodes=[], rings=[];
  Object.keys(byRing).map(Number).sort((a,b)=>a-b).forEach(k=>{
    const list=byRing[k].slice().sort((a,b)=>a.name.localeCompare(b.name)), rad=0.34+0.15*k, seed=(glxHash('ring'+k)%628)/100;
    rings.push(rad);
    list.forEach((r,i)=>{
      const att=r.attendance==null?60:r.attendance, prog=Math.max(0,Math.min(100,Number(r.progress)||0)), fr=Math.min(1,(r.fee||0)/maxFee);
      let color; if(mode==='progress') color=`hsl(${Math.round(prog*1.4)},85%,62%)`; else if(mode==='income') color=`hsl(45,92%,${Math.round(42+30*fr)}%)`; else color=GLX_BAND[r.band]||GLX_BAND.nodata;
      nodes.push({name:r.name, ring:k, r:rad, a0:seed+Math.PI*2*i/list.length+(glxHash(r.name)%100)/2000, speed:(0.035+att/100*0.11)*(k%2?-1:1),
        size:mode==='income'?5+fr*9:5+prog/100*9, color, glow:0.45+att/200, sat:!!r.due, incl:((glxHash(r.name+'i')%100)/100-0.5)*0.22, phase:(glxHash(r.name+'p')%628)/100, mates:r.mates||[]});
    });
  });
  return {nodes, rings};
}
/* pure: 3-D → screen. cam:{rx,ry,zoom} */
function glxProject(p, cam, w, h){
  const cy=Math.cos(cam.ry), sy=Math.sin(cam.ry), cx=Math.cos(cam.rx), sx=Math.sin(cam.rx);
  const x=p.x*cy+p.z*sy; let z=-p.x*sy+p.z*cy; const y=p.y*cx-z*sx; z=p.y*sx+z*cx;
  const f=2.6/(2.6+z*0.9), S=Math.min(w,h)*0.46*cam.zoom;
  return {sx:w/2+x*f*S, sy:h/2+y*f*S, z, f};
}
function glxPos(n, t){ const a=n.a0+n.speed*t; return {x:n.r*Math.cos(a), z:n.r*Math.sin(a), y:Math.sin(a+n.phase)*n.r*n.incl*3}; }

/* ---- data from the app ---- */
function glxRows(){
  const hid=(typeof isFinanceHidden==='function')&&isFinanceHidden(), prog=getProgressData(), rows=[], cellsByName={}, ix=smIndex();
  SCHEDULE.forEach(s=>DAYS.forEach(d=>{ const names=getCellText(s,d).split(',').map(x=>x.trim()).filter(Boolean); names.forEach(n=>{ (cellsByName[n]=cellsByName[n]||[]).push(names); }); }));
  Object.keys(cellsByName).forEach(name=>{
    let tot=0, cnt=0; Object.keys(prog[name]||{}).forEach(s=>(prog[name][s]||[]).forEach(c=>{ tot+=Number(c.pct)||0; cnt++; }));
    let att=null, band='nodata', fee=0, due=false;
    try{ att=computeStudentSummary(name).attendanceRate; }catch(e){}
    try{ band=churnScore(churnFeatures(name,ix)).band; }catch(e){}
    if(!hid){ try{ fee=getStudentPayment(name).monthlyFee||0; due=getStudentTotalDue(name)>0; }catch(e){} }
    const mates=new Set(); cellsByName[name].forEach(g=>{ if(g.length>1) g.forEach(m=>{ if(m!==name) mates.add(m); }); });
    rows.push({name, progress:cnt?tot/cnt:0, attendance:att, band, sessions:cellsByName[name].length, fee, due, mates:[...mates]});
  });
  return rows;
}

/* ---- renderer ---- */
let glx={raf:0, nodes:[], rings:[], rows:[], cam:{rx:0.85,ry:0,zoom:1}, t:0, last:0, sel:null, mode:'health', auto:true, idle:0, ptr:{}, moved:0, tilt:{x:0,y:0}, stars:[], reduce:false, shoot:null};
function glxOpen(){
  const rows=glxRows();
  if(!rows.length){ showWarningToast('গ্যালাক্সি বানাতে আগে শিডিউলে ছাত্র বসাও।'); return; }
  glx.rows=rows; glx.sel=null; glx.mode='health'; glx.auto=true; glx.t=0; glx.cam={rx:1.0,ry:0.3,zoom:1.14}; glx.reduce=!!(window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches);
  glx.stars=Array.from({length:170},()=>({x:Math.random(),y:Math.random(),z:Math.random(),p:Math.random()*6.28}));
  showKhataModal('🌌 ছাত্র-গ্যালাক্সি', `<div id="glxWrap" class="glx-wrap"><canvas id="glxCanvas"></canvas><div class="glx-scan"></div>
    <div class="glx-top"><div class="glx-tag"><b>STUDENT GALAXY</b><span>● ${toBn(rows.length)} জন · ☀️ সূর্য = তুমি</span></div>
      <div class="glx-modes"><button type="button" data-m="health" class="on" onclick="glxMode('health')">ঝুঁকি</button><button type="button" data-m="progress" onclick="glxMode('progress')">অগ্রগতি</button><button type="button" data-m="income" onclick="glxMode('income')">আয়</button></div></div>
    <div class="glx-legend">রং = মোড · আকার = অগ্রগতি · কক্ষপথ = ক্লাস (ভেতরে বেশি) · গতি = উপস্থিতি</div><div id="glxHud" class="glx-hud" style="display:none;"></div></div>`);
  setTimeout(()=>{ glxSetup(); },60);
}
function glxMode(m){ glx.mode=m; document.querySelectorAll('.glx-modes button').forEach(b=>b.classList.toggle('on',b.dataset.m===m)); const sel=glx.sel&&glx.sel.name; glxRebuild(); if(sel){ const n=glx.nodes.find(x=>x.name===sel); if(n) glxSelect(n); } }
function glxRebuild(){ const b=glxBuild(glx.rows, glx.mode); glx.nodes=b.nodes; glx.rings=b.rings; }
function glxSetup(){
  const wrap=document.getElementById('glxWrap'), cv=document.getElementById('glxCanvas'); if(!wrap||!cv) return;
  const top=wrap.getBoundingClientRect().top, H=Math.max(380,Math.round(window.innerHeight-top-6)), W=wrap.clientWidth, dpr=Math.min(2,window.devicePixelRatio||1);
  wrap.style.height=H+'px'; cv.width=W*dpr; cv.height=H*dpr; cv.style.width=W+'px'; cv.style.height=H+'px'; glx.W=W; glx.H=H; glx.dpr=dpr;
  glxRebuild();
  const P=glx.ptr; let pinch=0;
  cv.onpointerdown=e=>{ cv.setPointerCapture(e.pointerId); P[e.pointerId]={x:e.clientX,y:e.clientY}; glx.moved=0; glx.auto=false; glx.idle=0; };
  cv.onpointermove=e=>{ const p=P[e.pointerId]; if(!p) return; const ids=Object.keys(P);
    if(ids.length===2){ const [a,b]=ids.map(i=>P[i]); const d0=Math.hypot(a.x-b.x,a.y-b.y); P[e.pointerId]={x:e.clientX,y:e.clientY}; const [c,d]=ids.map(i=>P[i]); const d1=Math.hypot(c.x-d.x,c.y-d.y); glx.cam.zoom=Math.max(0.6,Math.min(2.2,glx.cam.zoom*(d1/(d0||d1)))); glx.moved+=10; return; }
    const dx=e.clientX-p.x, dy=e.clientY-p.y; glx.moved+=Math.abs(dx)+Math.abs(dy); glx.cam.ry+=dx*0.008; glx.cam.rx=Math.max(-0.25,Math.min(1.35,glx.cam.rx+dy*0.006)); P[e.pointerId]={x:e.clientX,y:e.clientY}; };
  cv.onpointerup=cv.onpointercancel=e=>{ const had=P[e.pointerId]; delete P[e.pointerId]; if(had && glx.moved<8 && e.type==='pointerup'){ const r=cv.getBoundingClientRect(); glxTap(e.clientX-r.left, e.clientY-r.top); } };
  cv.onwheel=e=>{ e.preventDefault(); glx.cam.zoom=Math.max(0.6,Math.min(2.2,glx.cam.zoom*(e.deltaY<0?1.08:0.93))); glx.auto=false; glx.idle=0; };
  if(!glx.gyro){ glx.gyro=true; window.addEventListener('deviceorientation',e=>{ if(e.gamma==null) return; glx.tilt.x=Math.max(-1,Math.min(1,(e.gamma||0)/35)); glx.tilt.y=Math.max(-1,Math.min(1,((e.beta||45)-45)/35)); }); }
  if(glx.raf) cancelAnimationFrame(glx.raf); glx.last=performance.now(); glx.raf=requestAnimationFrame(glxFrame);
  if(!glx.vis){ glx.vis=true; document.addEventListener('visibilitychange',()=>{ const c=document.getElementById('glxCanvas'); if(!document.hidden && !glx.raf && c && c.offsetParent){ glx.last=performance.now(); glx.raf=requestAnimationFrame(glxFrame); } }); }
}
function glxTap(x,y){
  let best=null, bd=1e9; glx.nodes.forEach(n=>{ if(n.px==null) return; const d=Math.hypot(n.px-x,n.py-y); if(d<Math.max(n.pr+16,26) && d<bd){ bd=d; best=n; } });
  if(best) glxSelect(best); else { glx.sel=null; const h=document.getElementById('glxHud'); if(h) h.style.display='none'; }
}
function glxSelect(n){
  glx.sel=n; const r=glx.rows.find(x=>x.name===n.name)||{}, hid=(typeof isFinanceHidden==='function')&&isFinanceHidden(), h=document.getElementById('glxHud'); if(!h) return;
  const bar=(l,v,c)=>`<div class="glx-bar"><span>${l}</span><i><u style="width:${Math.max(2,Math.min(100,v))}%;background:${c}"></u></i><b>${toBn(Math.round(v))}%</b></div>`;
  let nextC=''; try{ const s=sfSessionDates(n.name,14)[0]; if(s) nextC=`পরের ক্লাস: ${sfDateBn(s)}`; }catch(e){}
  const band={low:'নিরাপদ',medium:'মাঝারি ঝুঁকি',high:'উচ্চ ঝুঁকি',nodata:'তথ্য কম'}[r.band]||'';
  h.innerHTML=`<div class="glx-hud-h"><b style="color:${n.color}">${escapeHtml(n.name)}</b><button type="button" onclick="glxClose()" aria-label="বন্ধ">✕</button></div>
    ${bar('অগ্রগতি',r.progress||0,'#7bd8ff')}${r.attendance==null?'':bar('উপস্থিতি',r.attendance,'#5ef2c8')}
    <div class="glx-hud-m"><span>${band}</span><span>সপ্তাহে ${toBn(r.sessions||0)} ক্লাস</span>${nextC?`<span>${nextC}</span>`:''}${(!hid&&r.due)?'<span class="due">🔴 ফি বাকি</span>':''}${n.mates.length?`<span>👥 ${n.mates.slice(0,3).map(escapeHtml).join(', ')}</span>`:''}</div>
    <div class="glx-hud-b"><button type="button" onclick="churnMsgOpen('${jsq(n.name)}')">📩 মেসেজ</button><button type="button" onclick="sfOpen()">🧭 সিলেবাস</button></div>`;
  h.style.display='block';
}
function glxClose(){ glx.sel=null; const h=document.getElementById('glxHud'); if(h) h.style.display='none'; }
function glxFrame(ts){
  const cv=document.getElementById('glxCanvas'); if(!cv || !cv.offsetParent || document.hidden){ glx.raf=0; return; }   // page closed (hidden, but still in the DOM) or app in background: stop drawing, save battery
  const dt=Math.min(0.05,(ts-glx.last)/1000); glx.last=ts; if(!glx.reduce) glx.t+=dt;
  glx.idle+=dt; if(!glx.auto && glx.idle>7 && !Object.keys(glx.ptr).length) glx.auto=true;
  if(glx.auto && !glx.reduce) glx.cam.ry+=dt*0.1;
  const ctx=cv.getContext('2d'), W=glx.W, H=glx.H, dpr=glx.dpr, T=glx.t; ctx.setTransform(dpr,0,0,dpr,0,0);
  const cam={rx:glx.cam.rx+glx.tilt.y*0.12, ry:glx.cam.ry+glx.tilt.x*0.18, zoom:glx.cam.zoom};
  /* space */
  const bg=ctx.createRadialGradient(W/2,H/2,10,W/2,H/2,Math.max(W,H)*0.75); bg.addColorStop(0,'#101a3a'); bg.addColorStop(0.5,'#080c1f'); bg.addColorStop(1,'#02030a'); ctx.fillStyle=bg; ctx.fillRect(0,0,W,H);
  const neb=(x,y,r,c)=>{ const g=ctx.createRadialGradient(x,y,0,x,y,r); g.addColorStop(0,c); g.addColorStop(1,'rgba(0,0,0,0)'); ctx.fillStyle=g; ctx.fillRect(0,0,W,H); };
  neb(W*(0.25-cam.ry*0.02),H*0.3,W*0.6,'rgba(120,70,255,0.16)'); neb(W*(0.8-cam.ry*0.02),H*0.75,W*0.55,'rgba(0,200,255,0.12)');
  glx.stars.forEach(s=>{ const px=((s.x+cam.ry*0.03*(0.3+s.z))%1+1)%1*W, py=(s.y+cam.rx*0.01*s.z)%1*H, a=0.25+0.6*Math.abs(Math.sin(T*0.8*s.z+s.p)); ctx.globalAlpha=a; ctx.fillStyle='#cfe4ff'; ctx.fillRect(px,py,0.6+s.z*1.4,0.6+s.z*1.4); }); ctx.globalAlpha=1;
  if(!glx.shoot && !glx.reduce && Math.random()<0.004) glx.shoot={x:Math.random()*W*0.7,y:Math.random()*H*0.4,l:0};
  if(glx.shoot){ const s=glx.shoot; s.l+=dt*1.6; ctx.strokeStyle=`rgba(190,230,255,${Math.max(0,1-s.l)})`; ctx.lineWidth=1.4; ctx.beginPath(); ctx.moveTo(s.x+s.l*160,s.y+s.l*90); ctx.lineTo(s.x+s.l*160-60,s.y+s.l*90-34); ctx.stroke(); if(s.l>1) glx.shoot=null; }
  /* orbit rings */
  ctx.lineWidth=1; glx.rings.forEach((rad,i)=>{ ctx.strokeStyle=`rgba(120,190,255,${0.16-i*0.015})`; ctx.beginPath(); for(let k=0;k<=72;k++){ const a=k/72*Math.PI*2, p=glxProject({x:rad*Math.cos(a),y:0,z:rad*Math.sin(a)},cam,W,H); k?ctx.lineTo(p.sx,p.sy):ctx.moveTo(p.sx,p.sy); } ctx.stroke(); });
  /* project everything, sort far → near */
  const items=glx.nodes.map(n=>{ const p=glxProject(glxPos(n,T),cam,W,H); n.px=p.sx; n.py=p.sy; n.pr=n.size*p.f*Math.min(1.5,glx.cam.zoom); n.pz=p.z; return n; });
  /* constellation lines between students who study together */
  ctx.lineWidth=1; const byName={}; items.forEach(n=>{ byName[n.name]=n; }); items.forEach(n=>n.mates.forEach(m=>{ const o=byName[m]; if(o && n.name<m){ ctx.strokeStyle='rgba(160,220,255,0.18)'; ctx.beginPath(); ctx.moveTo(n.px,n.py); ctx.lineTo(o.px,o.py); ctx.stroke(); } }));
  /* sun */
  const c=glxProject({x:0,y:0,z:0},cam,W,H), sr=(16+Math.sin(T*2)*1.6)*c.f*Math.min(1.4,glx.cam.zoom);
  ctx.globalCompositeOperation='lighter'; const sg=ctx.createRadialGradient(c.sx,c.sy,0,c.sx,c.sy,sr*4.5); sg.addColorStop(0,'rgba(255,230,150,0.95)'); sg.addColorStop(0.25,'rgba(255,170,60,0.45)'); sg.addColorStop(1,'rgba(255,120,0,0)'); ctx.fillStyle=sg; ctx.beginPath(); ctx.arc(c.sx,c.sy,sr*4.5,0,6.283); ctx.fill();
  for(let r=0;r<9;r++){ const a=T*0.3+r*0.698; ctx.strokeStyle='rgba(255,210,120,0.22)'; ctx.beginPath(); ctx.moveTo(c.sx+Math.cos(a)*sr*1.3,c.sy+Math.sin(a)*sr*1.3); ctx.lineTo(c.sx+Math.cos(a)*sr*(2.4+Math.sin(T*1.5+r)*0.5),c.sy+Math.sin(a)*sr*(2.4+Math.sin(T*1.5+r)*0.5)); ctx.stroke(); }
  ctx.globalCompositeOperation='source-over'; ctx.fillStyle='#fff3c4'; ctx.beginPath(); ctx.arc(c.sx,c.sy,sr*0.8,0,6.283); ctx.fill();
  /* planets */
  items.sort((a,b)=>b.pz-a.pz).forEach(n=>{
    const sel=glx.sel&&glx.sel.name===n.name, r=n.pr, dim=0.55+0.45*(1-(n.pz+1)/2);
    ctx.globalCompositeOperation='lighter'; const g=ctx.createRadialGradient(n.px,n.py,0,n.px,n.py,r*3.4); g.addColorStop(0,n.color); g.addColorStop(1,'rgba(0,0,0,0)'); ctx.globalAlpha=0.5*n.glow*dim; ctx.fillStyle=g; ctx.beginPath(); ctx.arc(n.px,n.py,r*3.4,0,6.283); ctx.fill();
    ctx.globalCompositeOperation='source-over'; ctx.globalAlpha=Math.min(1,0.55+dim*0.5);
    const pg=ctx.createRadialGradient(n.px-r*0.35,n.py-r*0.4,r*0.1,n.px,n.py,r); pg.addColorStop(0,'#ffffff'); pg.addColorStop(0.35,n.color); pg.addColorStop(1,'rgba(10,14,40,0.95)'); ctx.fillStyle=pg; ctx.beginPath(); ctx.arc(n.px,n.py,r,0,6.283); ctx.fill(); ctx.globalAlpha=1;
    if(n.sat){ const a=T*2.4+n.phase, sx=n.px+Math.cos(a)*(r+8), sy=n.py+Math.sin(a)*(r+8)*0.7; ctx.fillStyle='#ff4d5e'; ctx.shadowColor='#ff4d5e'; ctx.shadowBlur=8; ctx.beginPath(); ctx.arc(sx,sy,2.4,0,6.283); ctx.fill(); ctx.shadowBlur=0; }
    if(sel){ ctx.strokeStyle='rgba(255,255,255,0.9)'; ctx.lineWidth=1.4; ctx.setLineDash([5,4]); ctx.lineDashOffset=-T*20; ctx.beginPath(); ctx.arc(n.px,n.py,r+9,0,6.283); ctx.stroke(); ctx.setLineDash([]); }
    if(sel || n.pz<0.15 && glx.nodes.length<=22 || r>9.5){ ctx.font='600 11px sans-serif'; ctx.textAlign='center'; ctx.fillStyle=sel?'#fff':'rgba(220,235,255,0.82)'; ctx.fillText(n.name.split(/\s+/)[0].slice(0,9), n.px, n.py+r+14); }
  });
  glx.raf=requestAnimationFrame(glxFrame);
}

/* ===== js/18-think.js ===== */
/* ============ 🧠 সিদ্ধান্ত-সহকারী (শিক্ষকের জন্য) + 💭 চিন্তা-শক্তি (ছাত্রদের জন্য) ============ */

/* ======================= 🧠 সিদ্ধান্ত-সহকারী ======================= */
/* "কেন?" — একটাই ব্যাখ্যায় ঝাঁপ না দিয়ে কয়েকটা সম্ভাব্য কারণ, প্রতিটার প্রমাণ + বিপরীত দিক + কী যাচাই করবে; দলের সঙ্গে তুলনা করে */
/* pure (unit-tested). f: {recentMarked,recentAbsent,cohortAbsRate,hwN,hwNone,hwPartial,sessions,cohortSessions,syllabusBad(0|1|2),perClass,dueMonths,daysSinceSeen} */
function dcWhy(f){
  const F=[], pct=x=>Math.round(x*100), my=f.recentMarked>=3?f.recentAbsent/f.recentMarked:null;
  if(my!=null && my>0){
    const coh=(f.cohortAbsRate==null)?null:f.cohortAbsRate, higher=coh==null||my>coh*1.3+0.02;
    F.push({key:'abs', score:Math.min(1,my/0.5)*(higher?1:0.55), evidence:`গত ৪ সপ্তাহে ${f.recentMarked} ক্লাসের ${f.recentAbsent}টায় অনুপস্থিত (${pct(my)}%)${coh!=null?` — দলের মাঝামাঝি ${pct(coh)}%`:''}`,
      counter:higher?'':'দলের বাকিদেরও অনুপস্থিতি কাছাকাছি — এটা একা এই ছাত্রের সমস্যা নাও হতে পারে (ঋতু, পরীক্ষা, উৎসব?)', check:'শেষ কয়দিন কেন আসেনি, সরাসরি জিজ্ঞেস করেছ?'});
  }
  if(f.hwN>=3){ const r=(f.hwNone+0.5*f.hwPartial)/f.hwN;
    if(r>0) F.push({key:'hw', score:Math.min(1,r/0.6)*(f.hwN>=5?1:0.7), evidence:`শেষ ${f.hwN} ক্লাসের ${f.hwNone}টায় হোমওয়ার্ক করেনি${f.hwPartial?`, ${f.hwPartial}টায় অর্ধেক`:''}`,
      counter:f.hwN<5?`নমুনা মাত্র ${f.hwN}টা — এখনই জোর দিয়ে বলা যায় না`:'', check:'হোমওয়ার্কটা কি তার জন্য বেশি কঠিন বা বেশি লম্বা?'}); }
  if(f.sessions!=null && f.cohortSessions!=null && f.sessions<f.cohortSessions){
    const gap=(f.cohortSessions-f.sessions)/f.cohortSessions;
    F.push({key:'load', score:Math.min(1,gap*1.2)*(f.syllabusBad?1:0.5), evidence:`সপ্তাহে ${f.sessions}টা ক্লাস, দলের মাঝামাঝি ${f.cohortSessions}টা`,
      counter:f.syllabusBad?'':'সিলেবাস তো পিছিয়ে নেই — কম ক্লাস এখনো সমস্যা হয়নি', check:'ক্লাস বাড়ানো কি সম্ভব, নাকি ক্লাসের মান বাড়ালেই হবে?'});
  }
  if(f.syllabusBad) F.push({key:'syl', score:f.syllabusBad>=2?0.9:0.6, evidence:`ডেডলাইনের কাজ সময়ের তুলনায় বেশি${f.perClass?` (প্রতি ক্লাসে ${f.perClass} অধ্যায় লাগবে)`:''}`,
      counter:'হতে পারে ডেডলাইনটাই বেশি আঁটসাঁট ছিল — ছাত্রের দোষ নয়', check:'ডেডলাইনটা কি আদৌ বাস্তবসম্মত ছিল?'});
  if(f.dueMonths>=1) F.push({key:'pay', score:Math.min(1,0.4+0.25*f.dueMonths), evidence:`${f.dueMonths} মাসের ফি বাকি`, counter:'ফি দেরি মানেই অনাগ্রহ নয় — পরিবারের আর্থিক চাপও হতে পারে', check:'ফির কথা ভদ্রভাবে তুলেছ, নাকি এড়িয়ে গেছ?'});
  if(f.daysSinceSeen!=null && f.daysSinceSeen>=14) F.push({key:'silent', score:Math.min(1,f.daysSinceSeen/30), evidence:`${f.daysSinceSeen} দিন ধরে ক্লাস হয়নি`, counter:'ছুটি, পরীক্ষা বা অসুস্থতা হতে পারে', check:'শেষবার কবে যোগাযোগ হয়েছে?'});
  F.sort((a,b)=>b.score-a.score);
  const causes=F.filter(x=>x.score>=0.25).slice(0,3), points=(f.recentMarked||0)+(f.hwN||0);
  const confidence=points<6?'low':((causes[0]&&causes[0].score>=0.6&&(!causes[1]||causes[0].score-causes[1].score>=0.2))?'high':'medium');
  return {causes:causes.map(c=>Object.assign({},c,{score:Math.round(c.score*100)/100})), confidence, points};
}
/* pure: মোটা অনুমান — আগে থেকেই ঝুঁকিতে থাকা ছাত্রের ফি বাড়ালে ছাড়ার সম্ভাবনা বেশি */
function dcLeaveProb(score, raisePct){ return Math.min(0.9, Math.max(0,score)/100*0.4 + Math.min(0.5, Math.max(0,raisePct)/100*0.8)); }
/* pure: "কী হলে কী?" — radarCompute দুবার (আগে/পরে) চালিয়ে তফাত।
   act: {type:'raise',name,by} | {type:'drop',name} | {type:'add',fee,slots} */
function dcSim(slots, cellOf, feeOf, o, act, leaveScore){
  const base=radarCompute(slots,cellOf,feeOf,o);
  let cell2=cellOf, fee2=feeOf, used=0;
  if(act.type==='raise') fee2=n=>n===act.name?(Number(feeOf(n))||0)+act.by:feeOf(n);
  else if(act.type==='drop') cell2=(s,d)=>String(cellOf(s,d)||'').split(',').map(x=>x.trim()).filter(x=>x&&x!==act.name).join(', ');
  else if(act.type==='add'){ const free=base.free.slice(0,Math.max(1,act.slots||1)); used=free.length; const key=new Set(free.map(x=>x.num+'|'+x.day)); cell2=(s,d)=>key.has(s.num+'|'+d)?'__নতুন':cellOf(s,d); fee2=n=>n==='__নতুন'?act.fee:feeOf(n); }
  const after=radarCompute(slots,cell2,fee2,o), r={before:{income:base.income,hrs:base.busyHrs,avg:base.avg}, after:{income:after.income,hrs:after.busyHrs,avg:after.avg}, dIncome:after.income-base.income, dHours:after.busyHrs-base.busyHrs, dAvg:after.avg-base.avg, used};
  const me=base.rows.find(x=>x.name===act.name);
  if(act.type==='raise'){ const fee0=Number(feeOf(act.name))||0, newFee=fee0+act.by, pct=fee0>0?act.by/fee0*100:0, p=dcLeaveProb(leaveScore||0,pct);
    r.fee0=fee0; r.newFee=newFee; r.raisePct=pct; r.p=p; r.expected=(1-p)*newFee-fee0; r.breakEven=newFee>0?act.by/newFee:0; }
  if(act.type==='drop'){ r.fee0=Number(feeOf(act.name))||0; r.freedHrs=Math.max(0,-r.dHours); r.recover=Math.round(base.avg*r.freedHrs); r.myRate=me?me.rate:0; r.avgRate=base.avg; r.myPct=me?me.pct:0; }
  return r;
}
function dcFeatures(name, cohort){
  const f=churnFeatures(name,cohort.ix), sf=(sfAll().find(x=>x.name===name))||{}, first=(sf.items||[])[0]||{};
  f.syllabusBad=(sf.status==='behind'||sf.status==='overdue')?2:(sf.status==='risk'?1:0); f.perClass=first.perClass?toBn(first.perClass.toFixed(2)):'';
  f.sessions=cohort.sessions[name]||0; f.cohortSessions=cohort.medSess; f.cohortAbsRate=cohort.medAbs; return f;
}
function dcCohort(){
  const names=getAllKnownNames(), sess={}, abs=[], ix=smIndex();
  SCHEDULE.forEach(s=>DAYS.forEach(d=>getCellText(s,d).split(',').map(x=>x.trim()).filter(Boolean).forEach(n=>{ sess[n]=(sess[n]||0)+1; })));
  names.forEach(n=>{ try{ const f=churnFeatures(n,ix); if(f.recentMarked>=3) abs.push(f.recentAbsent/f.recentMarked); }catch(e){} });
  const med=a=>{ if(!a.length) return null; const s=a.slice().sort((x,y)=>x-y), m=Math.floor(s.length/2); return s.length%2?s[m]:(s[m-1]+s[m])/2; };
  return {sessions:sess, medSess:med(Object.values(sess)), medAbs:med(abs), ix};
}
let dcSt={name:'', act:''};
const DC_LABEL={abs:'অনুপস্থিতি',hw:'হোমওয়ার্ক',load:'ক্লাসের সংখ্যা',syl:'সিলেবাসের চাপ',pay:'ফি/আর্থিক চাপ',silent:'যোগাযোগ বিচ্ছিন্ন'};
function dcBody(){
  const names=getAllKnownNames().slice().sort((a,b)=>a.localeCompare(b));
  if(!names.length) return `<div id="dcBox">${emptyState({icon:'chart',title:'এখনো কোনো ছাত্র নেই',body:'শিডিউলে ছাত্র বসালে এখানে বিশ্লেষণ পাবে।'})}</div>`;
  const flagged={}; try{ churnAll().forEach(x=>{ if(x.band==='high'||x.band==='medium') flagged[x.name]=x.band; }); sfAll().forEach(s=>{ if(s.status==='behind'||s.status==='overdue') flagged[s.name]=flagged[s.name]||'syl'; }); }catch(e){}
  if(!dcSt.name||!names.includes(dcSt.name)) dcSt.name=Object.keys(flagged)[0]||names[0];
  const cohort=dcCohort(), f=dcFeatures(dcSt.name,cohort), why=dcWhy(f), hid=isFinanceHidden();
  if(hid) why.causes=why.causes.map(c=>c.key==='pay'?Object.assign({},c,{evidence:'আর্থিক কারণ — আনলক করলে দেখা যাবে',counter:'',check:''}):c);
  const conf={high:['🟢','বেশ নিশ্চিত'],medium:['🟡','আংশিক নিশ্চিত'],low:['🔴','তথ্য কম — অনুমান মাত্র']}[why.confidence];
  const opts=names.sort((a,b)=>(flagged[b]?1:0)-(flagged[a]?1:0)||a.localeCompare(b)).map(n=>`<option value="${escapeHtml(n)}"${n===dcSt.name?' selected':''}>${flagged[n]?'⚠️ ':''}${escapeHtml(n)}</option>`).join('');
  const whyHtml=why.causes.length?why.causes.map((c,i)=>`<div class="dc-cause"><div class="dc-ct"><span>${i+1}. ${DC_LABEL[c.key]}</span><i><u style="width:${Math.round(c.score*100)}%"></u></i></div><div class="dc-ev">📊 ${escapeHtml(smBn(c.evidence))}</div>${c.counter?`<div class="dc-co">⚖️ <b>বিপরীত দিক:</b> ${escapeHtml(smBn(c.counter))}</div>`:''}${c.check?`<div class="dc-ck">❓ ${escapeHtml(c.check)}</div>`:''}</div>`).join(''):`<div class="sm-hint">এই ছাত্রের মধ্যে উল্লেখযোগ্য কোনো সতর্ক সংকেত পাওয়া যায়নি 👍</div>`;
  let sim=''; if(hid) sim=`<div class="sm-hint">🙈 আর্থিক হিসাব লুকানো — "কী হলে কী?" দেখতে আনলক করো।</div>`; else sim=dcSimHtml();
  return `<div id="dcBox"><select class="kh-in" onchange="dcPick(this.value)">${opts}</select>
    <div class="rd-sec">🔍 কেন এমন হচ্ছে? <small style="color:var(--muted);font-weight:400">${conf[0]} ${conf[1]}</small></div>${whyHtml}
    <div class="dc-unk">🌫️ <b>অ্যাপ যা জানে না:</b> ছাত্রের নিজের মনের অবস্থা, বাড়ির পরিস্থিতি, স্কুলের চাপ। ওপরের কারণগুলো সম্ভাবনা মাত্র — ছাত্র বা অভিভাবকের সঙ্গে কথা বলে নিশ্চিত হও, তারপর সিদ্ধান্ত নাও।</div>
    <div class="rd-sec">🔮 কী হলে কী হবে?</div>${sim}</div>`;
}
function dcSimHtml(){
  const name=dcSt.name, fee=getStudentPayment(name).monthlyFee||0, chips=[['r100','ফি +৳১০০'],['r500','ফি +৳৫০০'],['r10','ফি +১০%'],['drop','ছেড়ে দিলে'],['add1','নতুন ছাত্র (১ স্লট)'],['add2','নতুন ছাত্র (২ স্লট)']];
  const bar=`<div class="dc-chips">${chips.map(([k,l])=>`<button type="button" class="pct-chip${dcSt.act===k?' active':''}" onclick="dcAct('${k}')">${l}</button>`).join('')}</div>`;
  if(!dcSt.act) return bar+`<div class="sm-hint">একটা বেছে নাও — দেখাব আয়, সময় আর ঘণ্টা-প্রতি আয় কীভাবে বদলায়, সঙ্গে ঝুঁকিটাও।</div>`;
  const rd=radarData(), perSlot=rd.perSlot||0, k=dcSt.act, A=(k==='r100')?{type:'raise',name,by:100}:(k==='r500')?{type:'raise',name,by:500}:(k==='r10')?{type:'raise',name,by:Math.max(50,Math.round(fee*0.1/50)*50)}:(k==='drop')?{type:'drop',name}:{type:'add',fee:perSlot*(k==='add2'?2:1),slots:k==='add2'?2:1};
  if(A.type==='raise' && !(fee>0)) return bar+`<div class="sm-hint">${escapeHtml(name)}-এর মাসিক ফি দেওয়া নেই, তাই ফি বাড়ানোর হিসাব হবে না।</div>`;
  let leave=0; try{ leave=churnScore(churnFeatures(name)).score; }catch(e){}
  const r=dcSim(SCHEDULE,getCellText,n=>getStudentPayment(n).monthlyFee,{travel:radarTravel(),days:DAYS},A,leave), sg=x=>(x>=0?'+':'−')+bnTaka(Math.abs(x)), hh=x=>toBn(Math.abs(x).toFixed(1))+' ঘণ্টা';
  let h=`<div class="dc-res"><div class="dc-grid"><div><small>মাসিক আয়</small><b>${bnTaka(r.before.income)} → ${bnTaka(r.after.income)}</b><em class="${r.dIncome>=0?'up':'dn'}">${sg(r.dIncome)}</em></div><div><small>মাসে কাজের সময়</small><b>${toBn(r.before.hrs.toFixed(0))} → ${toBn(r.after.hrs.toFixed(0))} ঘণ্টা</b><em>${r.dHours>=0?'+':'−'}${hh(r.dHours)}</em></div><div><small>ঘণ্টা-প্রতি আয়</small><b>${bnTaka(r.before.avg)} → ${bnTaka(r.after.avg)}</b><em class="${r.dAvg>=0?'up':'dn'}">${sg(r.dAvg)}</em></div></div>`;
  if(A.type==='raise'){
    h+=`<div class="dc-note">⚖️ <b>ঝুঁকির হিসাব (মোটা অনুমান):</b> ফি ${toBn(Math.round(r.raisePct))}% বাড়ালে ${escapeHtml(name)}-এর ছেড়ে দেওয়ার সম্ভাবনা ≈ ${toBn(Math.round(r.p*100))}%। প্রত্যাশিত ফল: <b class="${r.expected>=0?'up':'dn'}">${sg(r.expected)}</b>। ছাড়ার সম্ভাবনা <b>${toBn(Math.round(r.breakEven*100))}%</b>-এর কম মনে হলে বাড়ানো লাভজনক।</div>
      <div class="dc-note">🔄 <b>বিপরীত যুক্তি:</b> ছেড়ে গেলে শুধু ${bnTaka(r.fee0)} নয়, নতুন ছাত্র পেতে সময়ও লাগে। আবার না বাড়ালে সময়ের তুলনায় এই ছাত্র থেকে আয় কমই থাকবে।</div>`;
  } else if(A.type==='drop'){
    h+=`<div class="dc-note">⚖️ ${escapeHtml(name)}-এর ঘণ্টা-প্রতি আয় ${bnTaka(r.myRate)} (গড় ${bnTaka(r.avgRate)})। ছাড়লে ${hh(r.freedHrs)} ফাঁকা হয়; সেই সময়ে গড় হারে একজন পেলে ≈ ${bnTaka(r.recover)} ফেরত আসে।</div>
      <div class="dc-note">🔄 <b>সাবধান:</b> এটা শুধু টাকা-সময়ের হিসাব। ছাত্রের ভবিষ্যৎ, সম্পর্ক, নতুন ছাত্র পাওয়ার নিশ্চয়তা — কিছুই এতে নেই।</div>`;
  } else {
    h+=`<div class="dc-note">⚖️ ${toBn(r.used)}টা ফাঁকা স্লটে ফি ≈ ${bnTaka(A.fee)} ধরে হিসাব। ${r.dAvg<0?'ঘণ্টা-প্রতি আয় <b class="dn">কমবে</b> — মানে এই ফিতে নতুন ছাত্র নিলে তুমি আগের চেয়ে কম হারে খাটবে; ফি আরেকটু বেশি চাওয়ার কথা ভাবো।':'ঘণ্টা-প্রতি আয় <b class="up">বাড়বে</b> — ভালো সুযোগ।'}</div>
      <div class="dc-note">🔄 <b>বিপরীত যুক্তি:</b> ফাঁকা সময় মানেই বিনামূল্যের সময় নয় — বিশ্রাম, নিজের পড়াশোনা, ছাত্রদের জন্য প্রস্তুতিও লাগে।</div>`;
  }
  return bar+h+`<div class="rd-foot">সংখ্যাগুলো তোমার শিডিউল ও ফি থেকে আসল হিসাব; "ছাড়ার সম্ভাবনা" একটা মোটা অনুমান (ঝুঁকি-স্কোর আর বাড়ানোর হারের ওপর), নিখুঁত ভবিষ্যদ্বাণী নয়।</div></div>`;
}
function dcRefresh(){ const b=document.getElementById('khataModalBody'); if(b&&b.querySelector('#dcBox')){ const y=b.scrollTop; b.innerHTML=dcBody(); b.scrollTop=y; } }
function dcPick(n){ dcSt.name=n; dcSt.act=''; dcRefresh(); }
function dcAct(k){ dcSt.act=(dcSt.act===k)?'':k; dcRefresh(); }
function dcOpen(){ dcSt.act=''; showKhataModal('🧠 সিদ্ধান্ত-সহকারী', dcBody()); }

/* ======================= 💭 চিন্তা-শক্তি (ছাত্রদের জন্য) ======================= */
/* ক্লাসের টপিক থেকে ৬ স্তরের প্রশ্ন (মনে রাখা → বোঝা → প্রয়োগ → বিশ্লেষণ → মূল্যায়ন → সৃষ্টি)। ছাত্রের সাড়া লিখে রাখলে স্তর নিজে ওপরে/নিচে যায়। */
const THK_LEVELS=[{n:1,name:'স্মরণ',icon:'🧠'},{n:2,name:'বোঝা',icon:'💡'},{n:3,name:'প্রয়োগ',icon:'🛠️'},{n:4,name:'বিশ্লেষণ',icon:'🔬'},{n:5,name:'মূল্যায়ন',icon:'⚖️'},{n:6,name:'সৃষ্টি',icon:'🚀'}];
const THK_T={
  1:['"{t}"-এর মূল কথাটা কী — এক লাইনে বলো।','"{t}" থেকে সবচেয়ে জরুরি তিনটা শব্দ বা সূত্র কী কী?','বই না দেখে বলো — "{t}"-এ কোন কোন ধাপ আছে?'],
  2:['"{t}" নিজের ভাষায় বুঝিয়ে বলো, যেন ছোট ভাই-বোন বুঝতে পারে।','"{t}" আর আগের পড়া কোন জায়গায় মেলে?','"{t}"-এর একটা নিজের মতো উদাহরণ বা ছবি বলো।'],
  3:['রোজকার জীবনের একটা সমস্যা "{t}" দিয়ে কীভাবে সমাধান করবে?','"{t}" ব্যবহার করে একটা সম্পূর্ণ নতুন উদাহরণ বানাও।','"{t}" কোন কোন জায়গায় কাজে লাগে — তিনটা বলো।'],
  4:['"{t}" কেন এভাবে কাজ করে? কারণটা ধাপে ধাপে বলো।','"{t}"-এর কোন অংশটা বাদ দিলে পুরোটা ভেঙে পড়ে?','"{t}" আর এর কাছাকাছি একটা বিষয়ের মিল ও অমিল কী?'],
  5:['"{t}" নিয়ে মানুষের একটা সাধারণ ভুল ধারণা কী? কেন ভুল?','কোন অবস্থায় "{t}"-এর পদ্ধতি কাজ করবে না? একটা বিপরীত উদাহরণ দাও।','"{t}" সমাধানের দুটো উপায়ের কোনটা ভালো — যুক্তি দিয়ে বেছে নাও।'],
  6:['"{t}" নিয়ে নিজে একটা কঠিন প্রশ্ন বানাও, আর তার উত্তরও দাও।','"{t}" অন্যকে শেখানোর জন্য ৩ মিনিটের একটা ছোট পাঠ সাজাও।','যদি নিয়মটা বদলে যায়, "{t}" তখন কেমন হবে? নতুন নিয়ম বানিয়ে দেখাও।']
};
const THK_SUBJ=[
  [/গণিত|math|অঙ্ক|হিসাব/i,{4:['এই নিয়মটা কেন সত্যি? একটা প্রমাণ বা যুক্তি দাও।'],5:['একটা সংখ্যা বসিয়ে যাচাই করো — কোন ক্ষেত্রে নিয়মটা ভেঙে যায়?'],3:['একটা শব্দ-সমস্যা বানাও যার সমাধান এই নিয়মে হয়।']}],
  [/বিজ্ঞান|science|পদার্থ|রসায়ন|জীব/i,{4:['এটা না ঘটলে কী হতো?'],5:['কীভাবে পরীক্ষা করে দেখবে দাবিটা ঠিক কি না?'],3:['ঘরে বসে এটা দেখানোর মতো একটা ছোট পরীক্ষা ভাবো।']}],
  [/ইংরেজি|english|বাংলা|ভাষা|ব্যাকরণ/i,{4:['বাক্যটা অন্যভাবে লিখলে মানে কীভাবে বদলায়?'],5:['দুটো শব্দের কোনটা এখানে বেশি মানানসই — কেন?'],6:['এই নিয়ম ব্যবহার করে নিজের একটা ছোট অনুচ্ছেদ লেখো।']}],
  [/সমাজ|ইতিহাস|ভূগোল|history|geography|ধর্ম/i,{4:['এর পেছনের কারণ কী ছিল? ফলাফল কী হলো?'],5:['এর পক্ষে একটা আর বিপক্ষে একটা যুক্তি দাও।'],6:['তুমি সেখানে থাকলে কী সিদ্ধান্ত নিতে?']}]
];
const THK_SOCRATIC=['তুমি কেন এটা মনে করছ?','এর বিপরীত কোনো উদাহরণ আছে?','কীভাবে নিশ্চিত হবে যে এটা ঠিক?','আরেকটু খুলে বলো — "এটা" বলতে কী বোঝাচ্ছ?','এটা না হলে কী হতো?','আর কোনো উপায়ে করা যায় কি?'];
/* pure (unit-tested) */
function thkQuestions(topic, subject, level, seed){
  const t=(String(topic||'').trim())||'আজকের পড়া', lv=Math.max(1,Math.min(6,level|0||1)); let arr=(THK_T[lv]||[]).slice();
  THK_SUBJ.forEach(([re,m])=>{ if(re.test(subject||'') && m[lv]) arr=arr.concat(m[lv]); });
  const rot=arr.length?Math.abs(seed|0)%arr.length:0, rotated=arr.slice(rot).concat(arr.slice(0,rot));
  return rotated.slice(0,3).map(q=>q.replace(/\{t\}/g,t));
}
/* pure: স্তর = অগ্রগতি দেখে শুরু; তারপর শিক্ষকের লেখা সাড়া (১ আটকে গেল · ২ ঠিকঠাক · ৩ দারুণ) দেখে ওঠা-নামা */
function thkNextLevel(log, progress){
  const base=progress>=80?5:(progress>=60?4:(progress>=30?3:2)), L=(log||[]).slice(-6);
  if(!L.length) return {level:base, why:`অগ্রগতি ${Math.round(progress||0)}% দেখে শুরু`};
  const lv=L[L.length-1].level, last2=L.slice(-2).filter(x=>x.level===lv);
  if(last2.length===2 && last2.every(x=>x.rating===3)) return {level:Math.min(6,lv+1), why:'টানা দুবার দারুণ করেছে — এক ধাপ ওপরে'};
  if(last2.length===2 && last2.every(x=>x.rating===1)) return {level:Math.max(1,lv-1), why:'টানা দুবার আটকে গেছে — এক ধাপ নিচে'};
  return {level:lv, why:'এই স্তরে আরও একটু অনুশীলন'};
}
const THK_KEY='tr_thinkLog';
function thkLog(){ return lsGet(THK_KEY,{}); }
function thkProgress(name){ let t=0,c=0; const p=getProgressData()[name]||{}; Object.keys(p).forEach(s=>(p[s]||[]).forEach(x=>{ t+=Number(x.pct)||0; c++; })); return c?t/c:0; }
function thkDefaults(name){
  const p=getProgressData()[name]||{}; let subject='', topic='';
  Object.keys(p).some(s=>{ const ch=(p[s]||[]).find(x=>(Number(x.pct)||0)<100); if(ch){ subject=s; topic=ch.chapter||''; return true; } return false; });
  return {subject, topic};
}
let thkSt={name:'', topic:'', subject:'', level:0, seed:0, touched:false};
function thkBody(){
  const names=getAllKnownNames().slice().sort((a,b)=>a.localeCompare(b));
  if(!names.length) return `<div id="thkBox">${emptyState({icon:'chart',title:'এখনো কোনো ছাত্র নেই',body:'শিডিউলে ছাত্র বসালে এখানে চিন্তা-শক্তির প্রশ্ন বানাতে পারবে।'})}</div>`;
  if(!thkSt.name||!names.includes(thkSt.name)){ thkSt.name=names[0]; thkSt.touched=false; }
  const log=thkLog()[thkSt.name]||[], prog=thkProgress(thkSt.name), sug=thkNextLevel(log,prog), d=thkDefaults(thkSt.name);
  if(!thkSt.touched){ thkSt.topic=d.topic; thkSt.subject=d.subject; }
  const lv=thkSt.level||sug.level, qs=thkQuestions(thkSt.topic,thkSt.subject,lv,thkSt.seed), t=(thkSt.topic||'').trim()||'আজকের পড়া';
  const hist=log.slice(-8).map(x=>`<i class="thk-dot r${x.rating}" title="স্তর ${x.level}"></i>`).join('');
  const ladder=THK_LEVELS.map(L=>`<button type="button" class="thk-step${L.n===lv?' on':''}${L.n===sug.level?' sug':''}" onclick="thkLevel(${L.n})"><span>${L.icon}</span><b>${toBn(L.n)}</b><small>${L.name}</small></button>`).join('');
  const nm=names.map(n=>`<option value="${escapeHtml(n)}"${n===thkSt.name?' selected':''}>${escapeHtml(n)}</option>`).join('');
  const all=names.map(n=>{ const l=thkLog()[n]||[], s=thkNextLevel(l,thkProgress(n)); return `<div class="thk-row" onclick="thkPick('${jsq(n)}')"><span>${escapeHtml(n)}</span><em>${THK_LEVELS[s.level-1].icon} স্তর ${toBn(s.level)} · ${THK_LEVELS[s.level-1].name}</em></div>`; }).join('');
  return `<div id="thkBox"><select class="kh-in" onchange="thkPick(this.value)">${nm}</select>
    <div class="thk-two"><input class="kh-in" id="thk_topic" placeholder="টপিক / অধ্যায়" value="${escapeHtml(thkSt.topic)}" onchange="thkField('topic',this.value)"><input class="kh-in" id="thk_subj" placeholder="বিষয়" value="${escapeHtml(thkSt.subject)}" onchange="thkField('subject',this.value)"></div>
    <div class="rd-sec">🪜 চিন্তা-সিঁড়ি <small style="color:var(--muted);font-weight:400">— ${escapeHtml(sug.why)}</small></div>
    <div class="thk-ladder">${ladder}</div><div class="thk-hist">${hist?`সাম্প্রতিক সাড়া: ${hist}`:''}</div>
    <div class="rd-sec">❓ আজকের প্রশ্ন (স্তর ${toBn(lv)} · ${THK_LEVELS[lv-1].name}) <button type="button" class="pct-chip" onclick="thkShuffle()">🔀 অন্য প্রশ্ন</button></div>
    ${qs.map((q,i)=>`<div class="thk-q"><b>${toBn(i+1)}.</b> ${escapeHtml(q)}</div>`).join('')}
    <div class="thk-tip"><b>🗣️ উত্তর দেওয়ার পর জিজ্ঞেস করো:</b>${THK_SOCRATIC.slice(0,4).map(s=>`<div>• ${s}</div>`).join('')}</div>
    <div class="thk-tip"><b>🕵️ ভুল ধরার খেলা:</b><div>আজ ইচ্ছে করে "${escapeHtml(t)}" নিয়ে একটা ভুল কথা বলো — ও ধরতে পারে কি না দেখো। ধরলে জিজ্ঞেস করো: "তুমি কীভাবে নিশ্চিত হলে?"</div></div>
    <div class="rd-sec">📝 ছাত্র কেমন সাড়া দিল?</div>
    <div class="thk-rate"><button type="button" onclick="thkRate(1)">😕<span>আটকে গেল</span></button><button type="button" onclick="thkRate(2)">🙂<span>ঠিকঠাক</span></button><button type="button" onclick="thkRate(3)">🤩<span>দারুণ যুক্তি দিল</span></button></div>
    <button type="button" class="settings-btn" onclick="thkParentMsg()">📩 অভিভাবককে "আজকের ভাবনার প্রশ্ন" পাঠাও</button>
    <div class="rd-sec">👥 সবার চিন্তা-স্তর</div><div class="thk-all">${all}</div>
    <div class="rd-foot">প্রশ্নগুলো শিক্ষাবিজ্ঞানের ৬ ধাপের (স্মরণ থেকে সৃষ্টি) নিয়মে সাজানো টেমপ্লেট — টপিক বসিয়ে তৈরি হয়। ছাত্রের উত্তর যাচাই তুমিই করবে; অ্যাপ শুধু কোন স্তরে ঠেলতে হবে তা মনে রাখে।</div></div>`;
}
function thkRefresh(){ const b=document.getElementById('khataModalBody'); if(b&&b.querySelector('#thkBox')){ const y=b.scrollTop; b.innerHTML=thkBody(); b.scrollTop=y; } }
function thkPick(n){ thkSt.name=n; thkSt.level=0; thkSt.touched=false; thkSt.seed=0; thkRefresh(); }
function thkField(k,v){ thkSt[k]=v; thkSt.touched=true; thkRefresh(); }
function thkLevel(n){ thkSt.level=n; thkRefresh(); }
function thkShuffle(){ thkSt.seed=(thkSt.seed||0)+1; thkRefresh(); }
function thkCurLevel(){ const l=thkLog()[thkSt.name]||[]; return thkSt.level||thkNextLevel(l,thkProgress(thkSt.name)).level; }
function thkRate(r){
  const all=thkLog(), arr=all[thkSt.name]||[], lv=thkCurLevel();
  arr.push({d:dateKeyStr(todayDateOnly()), topic:(thkSt.topic||'').slice(0,60), level:lv, rating:r}); all[thkSt.name]=arr.slice(-60); lsSet(THK_KEY,all);
  thkSt.level=0; thkSt.seed=0; showSuccessToast(r===3?'দারুণ! এই ধাপ মনে রাখলাম 🚀':(r===1?'ঠিক আছে, পরের বার সহজ ধাপে যাব':'সাড়া লেখা হয়েছে')); thkRefresh();
}
function thkParentMsg(){
  const pr=getStudentProfile(thkSt.name), lv=thkCurLevel(), q=thkQuestions(thkSt.topic,thkSt.subject,lv,thkSt.seed)[0], g=(pr.guardianName||'').trim(), tn=getTeacherName(false);
  smMsgPage(thkSt.name, `আসসালামু আলাইকুম${g?', '+g:''}।\nআজ ${thkSt.name}-কে একটা ভাবনার প্রশ্ন দিয়েছি:\n"${q}"\nবাসায় ওকে নিজের মতো করে উত্তর দিতে দিন, আর মাঝে "কেন?" জিজ্ঞেস করুন — সঠিক উত্তরের চেয়ে ভাবার চেষ্টাটাই আসল।\nধন্যবাদ।${tn?'\n— '+tn:''}`);
}
function thkOpen(){ thkSt.level=0; thkSt.seed=0; thkSt.touched=false; showKhataModal('💭 চিন্তা-শক্তি', thkBody()); }

/* ===== js/19-future.js ===== */
/* ============ 🔮 ভবিষ্যৎ-যন্ত্র — তোমার টিউশনের "ডিজিটাল টুইন" ============ */
/* তোমার আসল ডেটা (ফি, ছাত্র-ঝুঁকি, ফি-আদায়ের ধরন, ফাঁকা স্লট) থেকে ১,৫০০টা সম্ভাব্য ভবিষ্যৎ চালায় (মন্টি কার্লো সিমুলেশন)। */
/* ফল: আগামী মাসগুলোর আয়ের সম্ভাবনার পরিসর, লক্ষ্যে পৌঁছানোর সম্ভাবনা, আর কোন পদক্ষেপে সবচেয়ে বেশি লাভ (সংবেদনশীলতা বিশ্লেষণ)। */
/* এটা ভবিষ্যদ্বাণী নয় — অনুমানের ওপর দাঁড়ানো সম্ভাবনার ছবি; অনুমানগুলো পর্দাতেই লেখা থাকে। */

/* ---- pure (unit-tested) ---- */
function fxRng(a){ return function(){ a|=0; a=a+0x6D2B79F5|0; let t=Math.imul(a^a>>>15,1|a); t=t+Math.imul(t^t>>>7,61|t)^t; return ((t^t>>>14)>>>0)/4294967296; }; }
function fxInvPoisson(u, lam){ if(!(lam>0)) return 0; let p=Math.exp(-lam), c=p, k=0; while(u>c && k<25){ k++; p*=lam/k; c+=p; } return k; }
function fxPct(sorted, p){ if(!sorted.length) return 0; const i=(sorted.length-1)*p, lo=Math.floor(i), hi=Math.ceil(i); return sorted[lo]+(sorted[hi]-sorted[lo])*(i-lo); }
/* ঝুঁকি-স্কোর (০–১০০) → মাসে ছাড়ার সম্ভাবনা: ০ ≈ ২%, ১০০ ≈ ২৭%; স্কোর না থাকলে ৪% */
function fxHazard(score){ return (score==null||!isFinite(score))?0.04:0.02+Math.max(0,Math.min(100,score))/100*0.25; }
/* o: {students:[{name,fee,hazard,reliability}], months, runs, newRate, newFee, newHazard, freeSlots, seed, goal, base0, keep}
   প্রতিটা সিমুলেশনে একই র‍্যান্ডম সংখ্যার ধারা (common random numbers) — তাই "পদক্ষেপ নিলে" আর "না নিলে" তুলনাটা নিরপেক্ষ */
function fxSim(o){
  const M=o.months, R=o.runs||1500, S=o.students||[], keep=Math.min(R,o.keep==null?70:o.keep), cap=Math.max(0,Math.min(10,o.freeSlots|0)), newFee=o.newFee||0, newRate=Math.max(0,o.newRate||0), newHaz=o.newHazard==null?0.03:o.newHazard;
  const base0=o.base0!=null?o.base0:S.reduce((t,s)=>t+s.fee,0), byMonth=Array.from({length:M+1},()=>new Float64Array(R)), paths=[]; let goalHit=0, aboveHit=0, endStud=0, cum=0;
  for(let r=0;r<R;r++){
    const rnd=fxRng((o.seed|0)+r*7919+1), alive=S.map(()=>true), newActive=[]; let carry=0; const path=r<keep?[base0]:null; byMonth[0][r]=base0;
    let inc=0;
    for(let m=1;m<=M;m++){
      inc=carry; carry=0;
      for(let i=0;i<S.length;i++){ const s=S[i], uL=rnd(), uP=rnd(); if(alive[i]&&uL<s.hazard) alive[i]=false; if(alive[i]){ if(uP<s.reliability) inc+=s.fee; else carry+=s.fee; } }   // দেরি হলে ফি পরের মাসে আসে
      for(let j=0;j<cap;j++){ const u=rnd(); if(j<newActive.length&&newActive[j]){ if(u<newHaz) newActive[j]=false; else inc+=newFee; } }
      const arrivals=fxInvPoisson(rnd(),newRate); for(let a=0;a<arrivals&&newActive.length<cap;a++) newActive.push(true);
      byMonth[m][r]=inc; cum+=inc; if(path) path.push(inc);
    }
    if(path) paths.push(path);
    if(o.goal>0 && inc>=o.goal) goalHit++; if(inc>=base0*0.999) aboveHit++;
    endStud+=alive.filter(Boolean).length+newActive.filter(Boolean).length;
  }
  const bands=byMonth.map(arr=>{ const s=Float64Array.from(arr).sort(), mean=arr.reduce((t,x)=>t+x,0)/R; return {p10:fxPct(s,0.1),p25:fxPct(s,0.25),p50:fxPct(s,0.5),p75:fxPct(s,0.75),p90:fxPct(s,0.9),mean}; });
  return {months:M, runs:R, bands, paths, base0, pGoal:o.goal>0?goalHit/R:null, pAbove:aboveHit/R, endStudents:endStud/R, avgMonthly:cum/(R*M)};
}
/* pure: কার ছাড়ার সম্ভাবনা + প্রত্যাশিত ক্ষতি (বিশ্লেষণধর্মী) */
function fxTopRisk(students, months, n){
  return (students||[]).map(s=>{ let loss=0; for(let m=1;m<=months;m++) loss+=s.fee*(1-Math.pow(1-s.hazard,m)); return {name:s.name, fee:s.fee, pLeave:1-Math.pow(1-s.hazard,months), expectedLoss:loss}; })
    .sort((a,b)=>b.expectedLoss-a.expectedLoss).slice(0,n||3);
}
/* pure: কোন পদক্ষেপে সবচেয়ে লাভ — একই সিমুলেশন, একটা লিভার বদলে */
function fxLevers(o){
  const M=o.months, base=fxSim(Object.assign({},o,{keep:0})), S=o.students, top=fxTopRisk(S,M,1)[0], mk=f=>fxSim(Object.assign({},o,{keep:0},f));
  const L=[
    {key:'retainRisky', label:'ঝুঁকিতে থাকা সবাইকে ধরে রাখলে', sim:mk({students:S.map(s=>s.hazard>0.08?Object.assign({},s,{hazard:0.02}):s)})},
    top&&{key:'retainTop', label:`${top.name}-কে ধরে রাখলে`, sim:mk({students:S.map(s=>s.name===top.name?Object.assign({},s,{hazard:0.02}):s)})},
    {key:'newx2', label:'নতুন ছাত্র আনার হার দ্বিগুণ করলে', sim:mk({newRate:Math.max(0.2,(o.newRate||0)*2)})},
    {key:'fee10', label:'সবার ফি ১০% বাড়ালে (কেউ কেউ ছাড়তে পারে)', sim:mk({students:S.map(s=>Object.assign({},s,{fee:s.fee*1.1,hazard:Math.min(0.95,s.hazard*1.5+0.01)})), newFee:(o.newFee||0)*1.1})},
    {key:'collect', label:'ফি সময়মতো আদায় নিশ্চিত করলে', sim:mk({students:S.map(s=>Object.assign({},s,{reliability:1}))})}
  ].filter(Boolean).map(x=>({key:x.key, label:x.label, dAvg:x.sim.avgMonthly-base.avgMonthly, dGoal:base.pGoal==null?null:x.sim.pGoal-base.pGoal, dAbove:x.sim.pAbove-base.pAbove}));
  L.sort((a,b)=>b.dAvg-a.dAvg); return L;
}

/* ---- data from the app ---- */
function fxInputs(){
  const rd=radarData(), scores={}, due={};
  try{ const ix=smIndex(); getAllKnownNames().forEach(n=>{ const f=churnFeatures(n,ix), r=churnScore(f); scores[n]=r.band==='nodata'?null:r.score; due[n]=f.dueMonths; }); }catch(e){}
  const students=rd.rows.filter(r=>r.fee>0).map(r=>({name:r.name, fee:r.fee, hazard:fxHazard(scores[r.name]), reliability:(due[r.name]||0)>=1?0.8:0.95}));
  const avg=students.length?students.reduce((t,s)=>t+s.fee,0)/students.length:0;
  return {students, newFee:Math.round(avg), freeSlots:rd.free.length, goal:radarGoal(), seed:glxHash(students.map(s=>s.name+s.fee).join('|'))};
}

/* ---- screen ---- */
let fx={months:6, newRate:0.4, res:null, levers:null, top:null, o:null, t:1, raf:0, last:0, cursor:null, W:0, H:0, dpr:1};
function fxOpen(){
  if(isFinanceHidden()){ showWarningToast('আগে আর্থিক হিসাব আনলক করো (রিপোর্ট ট্যাবের উপরে "দেখাও")।'); return; }
  const nr=Number(lsGet('tr_fxNew',0.4)); fx.newRate=isFinite(nr)?Math.max(0,Math.min(2,nr)):0.4; fx.months=6; fx.cursor=null;
  showKhataModal('🔮 ভবিষ্যৎ-যন্ত্র', '<div id="fxBox"></div>'); fxRun(true);
}
function fxRun(animate){
  const inp=fxInputs(), box=document.getElementById('fxBox'); if(!box) return;
  if(!inp.students.length){ box.innerHTML=emptyState({icon:'chart',title:'এখনো হিসাবের মতো ফি নেই',body:'শিক্ষার্থীদের মাসিক ফি দিলে এখানে আগামী মাসগুলোর সম্ভাব্য আয় দেখাবে।'}); return; }
  fx.o=Object.assign({},inp,{months:fx.months, newRate:fx.newRate, runs:1500, keep:70}); const t0=performance.now();
  fx.res=fxSim(fx.o); fx.levers=fxLevers(fx.o); fx.top=fxTopRisk(inp.students,fx.months,3); fx.ms=Math.round(performance.now()-t0);
  box.innerHTML=fxHtml(); fxSetup(animate);
}
function fxK(v){ return v>=1000?toBn((v/1000).toFixed(v>=10000?0:1))+'হা':toBn(Math.round(v)); }
function fxHtml(){
  const r=fx.res, M=fx.months, b=r.bands[M], goal=fx.o.goal, p=goal>0?r.pGoal:r.pAbove, pct=Math.round(p*100), col=pct>=70?'#5ef2c8':(pct>=40?'#f2c85e':'#ff6b81');
  const circ=2*Math.PI*44, maxd=Math.max(1,...fx.levers.map(l=>Math.abs(l.dAvg)));
  const chips=[3,6,12].map(m=>`<button type="button" class="pct-chip${m===M?' active':''}" onclick="fxSetMonths(${m})">${toBn(m)} মাস</button>`).join('');
  return `<div class="fx-tag"><b>FUTURE ENGINE</b><span>● ${toBn(r.runs)}টা কল্পিত ভবিষ্যৎ · ${toBn(fx.ms)} মিলিসেকেন্ডে</span></div>
    <div class="fx-chips">${chips}</div>
    <div class="fx-wrap"><canvas id="fxCanvas"></canvas></div><div id="fxRead" class="fx-read">টেনে দেখো — কোন মাসে কত হতে পারে</div>
    <div class="fx-cards"><div class="fx-gauge"><svg viewBox="0 0 100 100"><circle cx="50" cy="50" r="44" class="bg"/><circle cx="50" cy="50" r="44" class="fg" id="fxRing" style="stroke:${col};stroke-dasharray:${circ.toFixed(1)};stroke-dashoffset:${circ.toFixed(1)}" data-to="${(circ*(1-p)).toFixed(1)}"/></svg><div class="fx-gn" style="color:${col}">${toBn(pct)}%</div></div>
      <div class="fx-gl"><b>${goal>0?`${toBn(M)} মাস পরে ${bnTaka(goal)}-এ পৌঁছানোর সম্ভাবনা`:`${toBn(M)} মাস পরে আজকের আয়ের ওপরে থাকার সম্ভাবনা`}</b>
        <span>মাঝারি পরিস্থিতিতে আয় <em>${bnTaka(b.p50)}</em></span><span>খারাপ দিনে (১০%) <em class="dn">${bnTaka(b.p10)}</em> · ভালো দিনে (৯০%) <em class="up">${bnTaka(b.p90)}</em></span><span>${toBn(M)} মাস পরে গড়ে ${toBn(r.endStudents.toFixed(1))} জন ছাত্র থাকবে (এখন ${toBn(fx.o.students.length)} জন)</span></div></div>
    ${goal>0?'':`<div class="sm-hint">🎯 আয়ের রাডারে লক্ষ্য দিলে এখানে "লক্ষ্যে পৌঁছানোর সম্ভাবনা" দেখাবে।</div>`}
    <div class="rd-sec">⚡ কোন পদক্ষেপে সবচেয়ে বেশি লাভ?</div>
    ${fx.levers.map(l=>`<div class="fx-lev"><div class="fx-lt"><span>${escapeHtml(l.label)}</span><b class="${l.dAvg>=0?'up':'dn'}">${l.dAvg>=0?'+':'−'}${bnTaka(Math.abs(l.dAvg))}/মাস গড়ে</b></div><div class="rd-bar"><i style="width:${Math.max(3,Math.abs(l.dAvg)/maxd*100)}%;background:${l.dAvg>=0?'var(--paid)':'var(--due)'}"></i></div>${l.dGoal!=null?`<div class="fx-ls">লক্ষ্যে পৌঁছানোর সম্ভাবনা ${l.dGoal>=0?'+':'−'}${toBn(Math.round(Math.abs(l.dGoal)*100))}%</div>`:`<div class="fx-ls">আজকের আয়ের ওপরে থাকার সম্ভাবনা ${l.dAbove>=0?'+':'−'}${toBn(Math.round(Math.abs(l.dAbove)*100))}%</div>`}</div>`).join('')}
    <div class="rd-sec">🎯 সবচেয়ে বড় ঝুঁকি (${toBn(M)} মাসে)</div>
    ${fx.top.map(t=>`<div class="fx-risk"><span>${escapeHtml(t.name)}</span><em>ছাড়ার সম্ভাবনা ${toBn(Math.round(t.pLeave*100))}% · প্রত্যাশিত ক্ষতি ${bnTaka(t.expectedLoss)}</em></div>`).join('')}
    <div class="rd-sec">🎚️ নতুন ছাত্র আনার হার</div>
    <div class="fx-step"><button type="button" onclick="fxNewStep(-0.1)" aria-label="কমাও">−</button><b>মাসে গড়ে ${toBn(fx.newRate.toFixed(1))} জন</b><button type="button" onclick="fxNewStep(0.1)" aria-label="বাড়াও">+</button></div>
    <div class="fx-asm"><b>🧪 অনুমান (সৎভাবে):</b><div>• ছাড়ার হার তোমার ঝুঁকি-স্কোর থেকে ধরা (স্কোর ০ ≈ মাসে ২%, ১০০ ≈ ২৭%) — বাস্তবে যাচাই করা নয়।</div><div>• ফি ৯৫% সময়মতো আসে (বাকি থাকলে ৮০%); দেরি হলে পরের মাসে আসে।</div><div>• নতুন ছাত্র মাসে গড়ে ${toBn(fx.newRate.toFixed(1))} জন আসে, ফাঁকা স্লট থাকা পর্যন্ত (সর্বোচ্চ ১০), ফি ≈ ${bnTaka(fx.o.newFee)}, মাসে ৩% ছাড়ে।</div><div>• ছুটি, মৌসুমি ওঠানামা, পরীক্ষার চাপ ধরা হয়নি। এটা <b>সম্ভাবনার পরিসর</b>, ভবিষ্যদ্বাণী নয়।</div></div>`;
}
function fxSetMonths(m){ fx.months=m; fx.cursor=null; fxRun(true); }
function fxNewStep(d){ fx.newRate=Math.max(0,Math.min(2,Math.round((fx.newRate+d)*10)/10)); lsSet('tr_fxNew',fx.newRate); fx.cursor=null; const b=document.getElementById('khataModalBody'), y=b?b.scrollTop:0; fxRun(true); if(b) b.scrollTop=y; }
function fxSetup(animate){
  const cv=document.getElementById('fxCanvas'); if(!cv) return; const wrap=cv.parentElement, W=wrap.clientWidth||340, H=270, dpr=Math.min(2,window.devicePixelRatio||1);
  cv.width=W*dpr; cv.height=H*dpr; cv.style.width=W+'px'; cv.style.height=H+'px'; fx.W=W; fx.H=H; fx.dpr=dpr;
  const at=e=>{ const r=cv.getBoundingClientRect(), padL=44, padR=14, x=(e.clientX-r.left-padL)/(W-padL-padR); fx.cursor=Math.max(0,Math.min(fx.months,Math.round(x*fx.months))); if(!fx.raf) fxDraw(1); fxReadout(); };
  cv.onpointerdown=e=>{ cv.setPointerCapture(e.pointerId); at(e); }; cv.onpointermove=e=>{ if(e.buttons||e.pointerType==='touch') at(e); };
  const reduce=!!(window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches);
  setTimeout(()=>{ const ring=document.getElementById('fxRing'); if(ring) ring.style.strokeDashoffset=ring.dataset.to; },60);
  if(animate && !reduce){ fx.t=0; fx.last=performance.now(); if(fx.raf) cancelAnimationFrame(fx.raf); fx.raf=requestAnimationFrame(fxFrame); } else { fx.t=1; fxDraw(1); }
}
function fxFrame(ts){
  const cv=document.getElementById('fxCanvas'); if(!cv||!cv.offsetParent||document.hidden){ fx.raf=0; return; }
  fx.t=Math.min(1,fx.t+Math.min(0.05,(ts-fx.last)/1000)/2.6); fx.last=ts; fxDraw(fx.t);
  if(fx.t<1) fx.raf=requestAnimationFrame(fxFrame); else fx.raf=0;                                     // one-off animation: no loop left running
}
function fxReadout(){
  const el=document.getElementById('fxRead'); if(!el||fx.cursor==null||!fx.res) return; const b=fx.res.bands[fx.cursor];
  el.innerHTML=`<b>${fx.cursor===0?'এখন':toBn(fx.cursor)+' মাস পরে'}</b> — খারাপ <span class="dn">${bnTaka(b.p10)}</span> · মাঝারি <span style="color:#f2c85e">${bnTaka(b.p50)}</span> · ভালো <span class="up">${bnTaka(b.p90)}</span>`;
}
function fxDraw(t){
  const cv=document.getElementById('fxCanvas'); if(!cv||!fx.res) return; const ctx=cv.getContext('2d'), W=fx.W, H=fx.H, r=fx.res, M=r.months, goal=fx.o.goal;
  ctx.setTransform(fx.dpr,0,0,fx.dpr,0,0); const bg=ctx.createLinearGradient(0,0,0,H); bg.addColorStop(0,'#0a1230'); bg.addColorStop(1,'#03040c'); ctx.fillStyle=bg; ctx.fillRect(0,0,W,H);
  const padL=44, padR=14, padT=16, padB=26, x=m=>padL+(W-padL-padR)*m/M;
  let top=Math.max(...r.bands.map(b=>b.p90), ...r.paths.map(p=>Math.max(...p)), goal>0?goal:0, r.base0)*1.08, y=v=>H-padB-(H-padT-padB)*v/top;
  ctx.strokeStyle='rgba(120,190,255,0.12)'; ctx.fillStyle='rgba(180,210,255,0.55)'; ctx.font='10px sans-serif'; ctx.lineWidth=1; ctx.textAlign='right';
  for(let k=0;k<=4;k++){ const v=top*k/4, yy=y(v); ctx.beginPath(); ctx.moveTo(padL,yy); ctx.lineTo(W-padR,yy); ctx.stroke(); ctx.fillText('৳'+fxK(v),padL-6,yy+3); }
  ctx.textAlign='center'; for(let m=0;m<=M;m++){ if(M>6&&m%2) continue; ctx.fillText(toBn(m),x(m),H-9); }
  const reveal=t*M;
  const pathTo=(arr,upto)=>{ ctx.beginPath(); for(let m=0;m<=Math.floor(upto);m++){ m?ctx.lineTo(x(m),y(arr[m])):ctx.moveTo(x(m),y(arr[m])); } const f=upto-Math.floor(upto); if(f>0&&Math.floor(upto)<M){ const m=Math.floor(upto); ctx.lineTo(x(m)+(x(m+1)-x(m))*f, y(arr[m])+(y(arr[m+1])-y(arr[m]))*f); } };
  ctx.globalCompositeOperation='lighter'; ctx.lineWidth=1; ctx.strokeStyle='rgba(90,200,255,0.16)'; r.paths.forEach(p=>{ pathTo(p,reveal); ctx.stroke(); }); ctx.globalCompositeOperation='source-over';
  const fade=Math.max(0,Math.min(1,(t-0.3)/0.5)), band=(lo,hi,a)=>{ ctx.beginPath(); for(let m=0;m<=M;m++){ const yy=y(r.bands[m][hi]); m?ctx.lineTo(x(m),yy):ctx.moveTo(x(m),yy); } for(let m=M;m>=0;m--) ctx.lineTo(x(m),y(r.bands[m][lo])); ctx.closePath(); ctx.fillStyle=`rgba(120,200,255,${a*fade})`; ctx.fill(); };
  band('p10','p90',0.12); band('p25','p75',0.2);
  if(goal>0){ const yg=y(goal); ctx.setLineDash([6,5]); ctx.strokeStyle='rgba(255,90,200,0.85)'; ctx.lineWidth=1.4; ctx.beginPath(); ctx.moveTo(padL,yg); ctx.lineTo(W-padR,yg); ctx.stroke(); ctx.setLineDash([]); ctx.fillStyle='rgba(255,140,220,0.95)'; ctx.textAlign='left'; ctx.fillText('🎯 লক্ষ্য',padL+4,yg-5); }
  ctx.strokeStyle='#f2c85e'; ctx.lineWidth=2.4; ctx.shadowColor='rgba(242,200,94,0.9)'; ctx.shadowBlur=10; pathTo(r.bands.map(b=>b.p50),reveal); ctx.stroke(); ctx.shadowBlur=0;
  if(fx.cursor!=null){ const c=fx.cursor, xc=x(c); ctx.strokeStyle='rgba(255,255,255,0.55)'; ctx.setLineDash([3,4]); ctx.beginPath(); ctx.moveTo(xc,padT); ctx.lineTo(xc,H-padB); ctx.stroke(); ctx.setLineDash([]); [['p10','#ff8a9a'],['p50','#f2c85e'],['p90','#7dffd8']].forEach(([k,col])=>{ ctx.fillStyle=col; ctx.shadowColor=col; ctx.shadowBlur=8; ctx.beginPath(); ctx.arc(xc,y(r.bands[c][k]),4,0,6.283); ctx.fill(); ctx.shadowBlur=0; }); }
}

/* ===== js/20-khata-brain.js ===== */
/* ============ 🧠 খাতা-বুদ্ধি: বিশ্বাস-স্কোর · তাগাদা-পরিকল্পনা · ক্যাশ-রানওয়ে ============ */
/* ১) প্রতিটা দেনাদারের শোধের ইতিহাস (কত দিনে ফেরত দেয়, কত % ফেরত দিয়েছে, কতদিন ধরে বকেয়া) থেকে বিশ্বাস-স্কোর */
/* ২) কাকে আজ তাগাদা দিলে সবচেয়ে বেশি টাকা আসার সম্ভাবনা — স্কোর অনুযায়ী সুর বদলানো মেসেজসহ */
/* ৩) আগামী ৩০/৬০/৯০ দিনে ক্যাশ কোথায় যেতে পারে — তোমার আসল খরচ-আয়, রিপিট বিল আর আদায়ের সম্ভাবনা নিয়ে ১,২০০টা সিমুলেশন */

/* ---- pure (unit-tested) ---- */
function kzDays(a,b){ return Math.round((new Date(b+'T00:00:00')-new Date(a+'T00:00:00'))/86400000); }
/* txs: এই ব্যক্তির লেনদেন। "ধার দিলাম" (gave) বনাম "ফেরত পেলাম" (got_back) — পুরনো ধার আগে শোধ হয় ধরে (FIFO) */
function kzRepayStats(txs, today){
  const g=[], p=[]; (txs||[]).slice().sort((a,b)=>a.date<b.date?-1:(a.date>b.date?1:0)).forEach(t=>{ if(t.type==='gave') g.push({d:t.date,left:t.amount,orig:t.amount}); else if(t.type==='got_back') p.push({d:t.date,amt:t.amount}); });
  let gi=0, delaySum=0, delayAmt=0, matched=0; const total=g.reduce((s,x)=>s+x.left,0);
  p.forEach(r=>{ let rem=r.amt; while(rem>0&&gi<g.length){ const q=g[gi], use=Math.min(rem,q.left); delaySum+=Math.max(0,kzDays(q.d,r.d))*use; delayAmt+=use; matched+=use; q.left-=use; rem-=use; if(q.left<=0) gi++; } });
  const open=g.find(x=>x.left>0), lastPay=p.length?p[p.length-1].d:null;
  /* "কত % ফেরত দিয়েছে" মাপা হয় শুধু ৩০ দিনের বেশি পুরনো ধারে — সদ্য নেওয়া ধার শোধের সময় পায়নি, তাকে দোষ দেওয়া অন্যায় */
  const mature=g.filter(x=>kzDays(x.d,today)>30), mTot=mature.reduce((t,x)=>t+x.orig,0), mPaid=mature.reduce((t,x)=>t+(x.orig-x.left),0);
  return {n:g.length, total, matched, repaidShare:mTot>0?mPaid/mTot:(total>0?matched/total:null), avgDelay:delayAmt>0?delaySum/delayAmt:null, openAge:open?Math.max(0,kzDays(open.d,today)):0, lastPayDays:lastPay?Math.max(0,kzDays(lastPay,today)):null};
}
/* বিশ্বাস-স্কোর ০–১০০; যথেষ্ট ইতিহাস না থাকলে score:null */
function kzTrust(s, o){
  if(!s||s.n===0) return {score:null};
  if(s.matched<=0 && s.openAge<=30) return {score:null};
  let sc=55; if(s.repaidShare!=null) sc+=(s.repaidShare-0.5)*50;
  if(s.avgDelay!=null) sc+=s.avgDelay<=7?15:(s.avgDelay<=21?8:(s.avgDelay<=45?0:(s.avgDelay<=90?-12:-22)));
  sc-=Math.min(30,Math.max(0,s.openAge-30)*0.25); if(o&&o.due&&o.due<o.today&&o.net>0) sc-=10;
  return {score:Math.max(0,Math.min(100,Math.round(sc)))};
}
function kzBand(score){ return score==null?'new':(score>=70?'good':(score>=40?'mid':'bad')); }
/* ৩০ দিনের মধ্যে কিছু শোধ করার মোটা সম্ভাবনা */
function kzPayProb(t, s){
  if(!t||t.score==null) return 0.45;
  let p=0.1+0.75*t.score/100; if(s.lastPayDays!=null&&s.lastPayDays<=14) p+=0.1; if(s.openAge>120) p-=0.15;
  return Math.max(0.05,Math.min(0.95,p));
}
/* rows: khataDebtRows-এর ফল; txs: সব লেনদেন */
function kzPlan(rows, txs, today){
  const by={}; (txs||[]).forEach(t=>{ (by[t.person]=by[t.person]||[]).push(t); });
  const items=(rows||[]).filter(r=>r.net>0).map(r=>{
    const s=kzRepayStats(by[r.name],today), t=kzTrust(s,{due:r.due,today,net:r.net}), p=kzPayProb(t,s), band=kzBand(t.score);
    const urg=(r.overdue?1.35:1)*(1+Math.min(0.5,s.openAge/180)), expected=r.net*p, why=[];
    if(s.avgDelay!=null) why.push(`গড়ে ${Math.round(s.avgDelay)} দিনে শোধ করে`); if(s.repaidShare!=null&&s.n>0) why.push(`দেওয়া টাকার ${Math.round(s.repaidShare*100)}% ফেরত দিয়েছে`);
    if(s.openAge>45) why.push(`${s.openAge} দিন ধরে বকেয়া`); if(r.overdue) why.push('তাগাদার তারিখ পেরিয়েছে'); if(s.lastPayDays!=null&&s.lastPayDays<=30) why.push(`${s.lastPayDays} দিন আগে কিছু দিয়েছে`);
    if(t.score==null) why.push('আগের লেনদেন কম — পূর্বাভাস অনিশ্চিত');
    return {name:r.name, net:r.net, score:t.score, band, p, expected, priority:expected*urg+r.net*0.05, tone:band==='good'?'soft':(band==='mid'?'firm':(band==='bad'?'direct':'neutral')), openAge:s.openAge, why};
  }).sort((a,b)=>b.priority-a.priority);
  return {items, expectedAll:items.reduce((t,x)=>t+x.expected,0)};
}
/* সুর বদলানো ভদ্র মেসেজ: ভালো দেনাদারকে হালকা মনে করানো, দুর্বলকে সরাসরি তারিখ চাওয়া */
function kzMessage(o){
  const hi=`আসসালামু আলাইকুম ${o.name}।`, bye=o.teacher?`\n— ${o.teacher}`:'', amt=o.amount;
  if(o.tone==='soft') return `${hi} কেমন আছেন? আমার হিসাবে ${amt} বাকি আছে — সুবিধামতো সময়ে দিয়ে দিলে ভালো হয়। ধন্যবাদ।${bye}`;
  if(o.tone==='firm') return `${hi} ${amt} বাকি আছে অনেকদিন হলো। কবে নাগাদ দিতে পারবেন জানালে আমার হিসাব রাখতে সুবিধা হয়।${bye}`;
  if(o.tone==='direct') return `${hi} ${amt} টাকা ${o.openAge||'অনেক'} দিন ধরে বকেয়া। আমারও টাকার দরকার আছে — আগামী ৩ দিনের মধ্যে একটা নির্দিষ্ট তারিখ জানাবেন, অথবা আগে কিছু অংশ পাঠিয়ে দিন।${bye}`;
  return `${hi} আমার হিসাবে ${amt} বাকি আছে। সুবিধামতো সময়ে দিয়ে দিলে ভালো হয়।${bye}`;
}
/* গত win দিনের দৈনিক খরচ/আয় (রিপিট এন্ট্রি বাদ — ওগুলো আলাদা ধরা হয়); খাতা ব্যবহার শুরুর আগের দিনগুলো শূন্য ধরা হয় না */
function kzHistory(daily, today, win){
  const f=x=>x.getFullYear()+'-'+String(x.getMonth()+1).padStart(2,'0')+'-'+String(x.getDate()).padStart(2,'0'), t=new Date(today+'T00:00:00'), dates=[];
  for(let i=win-1;i>=0;i--){ const d=new Date(t); d.setDate(t.getDate()-i); dates.push(f(d)); }
  const O={}, I={}; (daily||[]).forEach(e=>{ if(/রিপিট/.test(e.note||'')) return; const m=e.kind==='in'?I:O; m[e.date]=(m[e.date]||0)+(e.amount||0); });
  const first=(daily||[]).map(e=>e.date).filter(d=>d<=today).sort()[0]; let si=first?dates.findIndex(d=>d>=first):0; if(si<0) si=0;
  const use=dates.slice(si); return {out:use.map(d=>O[d]||0), inn:use.map(d=>I[d]||0), days:use.length};
}
/* ক্যাশ-রানওয়ে সিমুলেশন। o:{cash,days,runs,seed,hist:{out,inn},recur:[{kind,amount,day}],recvs:[{net,p30}],today,outMul}
   প্রতিটা দিনের খরচ/আয় আসল ইতিহাস থেকে র‍্যান্ডম দিন তুলে নেওয়া; দেনাদার ১ বার (কখনো অর্ধেক) শোধ করে */
function kzRunway(o){
  const D=o.days, R=o.runs||1200, H=o.hist, mul=o.outMul==null?1:o.outMul, bal=Array.from({length:D+1},()=>new Float64Array(R)), t0=new Date(o.today+'T00:00:00');
  const fixed=new Float64Array(D+1); for(let d=1;d<=D;d++){ const dt=new Date(t0); dt.setDate(t0.getDate()+d); const dim=new Date(dt.getFullYear(),dt.getMonth()+1,0).getDate(); (o.recur||[]).forEach(it=>{ if(Math.min(it.day||1,dim)===dt.getDate()) fixed[d]+=it.kind==='in'?it.amount:-it.amount; }); }
  let neg=0, firstNegSum=0; const hasH=H&&H.out.length>0;
  for(let r=0;r<R;r++){
    const rnd=fxRng((o.seed|0)+r*104729+3), pay=(o.recvs||[]).map(v=>{ const u1=rnd(),u2=rnd(),u3=rnd(), pH=1-Math.pow(1-v.p30,D/30); return u1<pH?{day:1+Math.floor(u2*D),amt:v.net*(u3<0.35?0.5:1)}:null; });
    let b=o.cash, minB=b, firstNeg=0; bal[0][r]=b;
    for(let d=1;d<=D;d++){ const i1=rnd(), i2=rnd(); let net=fixed[d]; if(hasH){ net-=H.out[Math.floor(i1*H.out.length)]*mul; net+=H.inn[Math.floor(i2*H.inn.length)]; } pay.forEach(x=>{ if(x&&x.day===d) net+=x.amt; }); b+=net; bal[d][r]=b; if(b<minB) minB=b; if(b<0&&!firstNeg) firstNeg=d; }
    if(minB<0){ neg++; firstNegSum+=firstNeg; }
  }
  const bands=bal.map(a=>{ const s=Float64Array.from(a).sort(); return {p10:fxPct(s,0.1),p25:fxPct(s,0.25),p50:fxPct(s,0.5),p75:fxPct(s,0.75),p90:fxPct(s,0.9)}; });
  const p10Neg=bands.findIndex(b=>b.p10<0);
  return {days:D, runs:R, bands, pRunout:neg/R, avgFirstNeg:neg?firstNegSum/neg:0, p10NegDay:p10Neg<0?0:p10Neg, hasHist:hasH, histDays:hasH?H.out.length:0};
}
/* কোন পদক্ষেপে রানওয়ে সবচেয়ে ভালো হয় */
function kzRunwayLevers(o){
  const base=kzRunway(o), D=o.days, mk=f=>kzRunway(Object.assign({},o,f)), top=(o.recvs||[]).slice().sort((a,b)=>b.net-a.net).slice(0,3).map(x=>x.id);
  const L=[
    {key:'collect', label:'বড় 3 জন দেনাদারের কাছ থেকে আদায় নিশ্চিত করলে', sim:mk({recvs:(o.recvs||[]).map(v=>top.includes(v.id)?Object.assign({},v,{p30:0.97}):v)})},
    {key:'cut', label:'দৈনিক খরচ 10% কমালে', sim:mk({outMul:(o.outMul==null?1:o.outMul)*0.9})},
    {key:'rise', label:'দৈনিক খরচ 10% বাড়লে', sim:mk({outMul:(o.outMul==null?1:o.outMul)*1.1})}
  ].map(x=>({key:x.key,label:x.label,dEnd:x.sim.bands[D].p10-base.bands[D].p10,dRun:x.sim.pRunout-base.pRunout}));
  L.sort((a,b)=>b.dEnd-a.dEnd); return {base, levers:L};
}

/* ---- data from the app ---- */
function kzTrustMap(list, people, today, rows){
  const by={}; (list||[]).forEach(t=>{ (by[t.person]=by[t.person]||[]).push(t); }), m={};
  (rows||[]).forEach(r=>{ if(r.net>0){ const s=kzRepayStats(by[r.name],today), t=kzTrust(s,{due:r.due,today,net:r.net}); m[r.name]={score:t.score, band:kzBand(t.score)}; } });
  return m;
}
function kzPill(x){ if(!x) return ''; const ic={good:'🟢',mid:'🟡',bad:'🔴',new:'⚪'}[x.band]; return `<span class="kz-pill ${x.band}" title="বিশ্বাস-স্কোর">${ic} ${x.score==null?'নতুন':enNum(x.score)}</span>`; }
function kzInputs(days){
  const T=dateKeyStr(todayDateOnly()), list=getKhata(), people=getLs('tr_khataPeople'), rows=khataDebtRows(list,people,'all','',T), plan=kzPlan(rows,list,T);
  const hist=kzHistory(getDaily(),T,90), recur=(lsGet(KH_REC_KEY,[])||[]).map(r=>({kind:r.kind,amount:Number(r.amount)||0,day:r.day||1}));
  return {cash:khataCashInfo().cash, days, runs:1200, seed:glxHash(T+':'+list.length+':'+getDaily().length), hist, recur, recvs:plan.items.map((x,i)=>({id:i,net:x.net,p30:x.p})), today:T, plan};
}
function kzBannerHtml(list, people, T, rows){
  let plan; try{ plan=kzPlan(rows,list,T); }catch(e){ return ''; }
  const topN=plan.items.slice(0,3), exp=topN.reduce((t,x)=>t+x.expected,0), parts=[];
  if(topN.length) parts.push(`আজ শীর্ষ ${enNum(topN.length)} জনকে তাগাদা দিলে ≈ <b>${enTaka(exp)}</b> আদায়ের সম্ভাবনা`);
  try{ const h=kzHistory(getDaily(),T,90), c=khataCashInfo().cash; if(h.days>=7){ const burn=h.out.reduce((a,b)=>a+b,0)/h.days-h.inn.reduce((a,b)=>a+b,0)/h.days; parts.push(burn>0?(c>0?`ক্যাশ গড় হারে ≈ ${enNum(Math.floor(c/burn))} দিন চলবে`:'ক্যাশ ঋণাত্মক'):'আয় ≥ খরচ — ক্যাশ নিরাপদ'); } }catch(e){}
  if(!parts.length) return '';
  return `<button type="button" class="kz-banner" onclick="kzOpen()"><div class="kz-b-t">🧠 খাতা-বুদ্ধি <i>নতুন</i></div><div class="kz-b-s">${parts.join(' · ')}</div><div class="kz-b-go">বিশ্বাস-স্কোর · তাগাদা-পরিকল্পনা · ক্যাশ-রানওয়ে ›</div></button>`;
}

/* ---- screen ---- */
function kzT(v){ return v<0?'−'+enTaka(-v):enTaka(v); }
let kz={tab:'plan', days:60, res:null, lv:null, inp:null, t:1, raf:0, last:0, cursor:null, W:0, H:0, dpr:1};
function kzOpen(tab){ kz.tab=tab||'plan'; kz.cursor=null; showKhataModal('🧠 খাতা-বুদ্ধি','<div id="kzBox"></div>'); kzRender(true); }
function kzTab(t){ kz.tab=t; kz.cursor=null; kzRender(true); }
function kzRender(animate){
  const box=document.getElementById('kzBox'); if(!box) return;
  const seg=`<div class="kh-seg kr-seg"><button type="button" class="${kz.tab==='plan'?'on':''}" onclick="kzTab('plan')">🎯 তাগাদা-পরিকল্পনা</button><button type="button" class="${kz.tab==='run'?'on':''}" onclick="kzTab('run')">🌅 ক্যাশ-রানওয়ে</button></div>`;
  if(kz.tab==='plan'){ box.innerHTML=seg+kzPlanHtml(); return; }
  const inp=kzInputs(kz.days), t0=performance.now(); kz.inp=inp; const r=kzRunwayLevers(inp); kz.res=r.base; kz.lv=r.levers; kz.ms=Math.round(performance.now()-t0);
  box.innerHTML=seg+kzRunHtml(); kzSetup(animate);
}
function kzPlanHtml(){
  const T=dateKeyStr(todayDateOnly()), list=getKhata(), rows=khataDebtRows(list,getLs('tr_khataPeople'),'all','',T), plan=kzPlan(rows,list,T);
  if(!plan.items.length) return emptyState({icon:'book',title:'কারো কাছে পাওনা নেই 🎉',body:'কাউকে ধার দিলে এখানে তার বিশ্বাস-স্কোর আর তাগাদার পরিকল্পনা দেখাবে।'});
  const top=plan.items.slice(0,3), expTop=top.reduce((t,x)=>t+x.expected,0), tot=plan.items.reduce((t,x)=>t+x.net,0);
  return `<div class="kz-hero"><small>আজ শীর্ষ ${enNum(top.length)} জনকে তাগাদা দিলে</small><b>≈ ${enTaka(expTop)}</b><span>আদায়ের সম্ভাবনা (মোট পাওনা ${enTaka(tot)}, সবাইকে ধরলে ≈ ${enTaka(plan.expectedAll)} আসতে পারে 30 দিনে)</span></div>
    ${plan.items.map((x,i)=>`<div class="kz-card ${x.band}"><div class="kz-ch"><span class="kz-rank">${enNum(i+1)}</span><div class="kz-cn"><b>${escapeHtml(x.name)}</b><small>পাবো ${enTaka(x.net)}</small></div>${kzPill({band:x.band,score:x.score})}</div>
      <div class="kz-prob"><i><u style="width:${Math.round(x.p*100)}%"></u></i><span>30 দিনে শোধের সম্ভাবনা ${enNum(Math.round(x.p*100))}% · প্রত্যাশিত ${enTaka(x.expected)}</span></div>
      <div class="kz-why">${x.why.map(w=>`<em>${escapeHtml(enBn(w))}</em>`).join('')}</div>
      <div class="kz-act"><button type="button" class="pct-chip active" onclick="kzMsg('${jsq(x.name)}')">📩 ${x.tone==='soft'?'হালকা মনে করাও':(x.tone==='firm'?'ভদ্র তাগাদা':(x.tone==='direct'?'সরাসরি তাগাদা':'তাগাদা পাঠাও'))}</button><button type="button" class="pct-chip" onclick="openKhataPerson('${jsq(x.name)}')">হিসাব দেখো</button></div></div>`).join('')}
    <div class="rd-foot">বিশ্বাস-স্কোর = কত দিনে ফেরত দেয়, দেওয়া টাকার কত % ফেরত দিয়েছে, কতদিন ধরে বকেয়া, তাগাদার তারিখ পেরিয়েছে কি না। সম্ভাবনাগুলো এই ইতিহাস থেকে ধরা মোটা অনুমান — নতুন বা কম-লেনদেনের মানুষের ক্ষেত্রে অনিশ্চিত (⚪)। এটা কাউকে বিচার করার জন্য নয়, কাকে আগে মনে করাবে তা ঠিক করার জন্য।</div>`;
}
function enBn(s){ return String(s).replace(/\d+/g,m=>enNum(Number(m))); }
function kzMsg(name){
  const T=dateKeyStr(todayDateOnly()), list=getKhata(), rows=khataDebtRows(list,getLs('tr_khataPeople'),'all','',T), it=kzPlan(rows,list,T).items.find(x=>x.name===name); if(!it) return;
  smMsgPage(name, kzMessage({name, amount:enTaka(it.net), tone:it.tone, openAge:it.openAge, teacher:getTeacherName(false)}));
  const ph=(getLs('tr_khataPeople')[name]||{}).phone; if(ph){ const p=getStudentProfile(name); }
}
function kzRunHtml(){
  const r=kz.res, D=kz.days, b=r.bands[D], low=Math.min(...r.bands.map(x=>x.p10)), pr=Math.round(r.pRunout*100), col=pr<=10?'#5ef2c8':(pr<=35?'#f2c85e':'#ff6b81'), circ=2*Math.PI*44;
  const chips=[30,60,90].map(d=>`<button type="button" class="pct-chip${d===D?' active':''}" onclick="kzDays_(${d})">${enNum(d)} দিন</button>`).join(''), maxd=Math.max(1,...kz.lv.map(l=>Math.abs(l.dEnd)));
  const recur=kz.inp.recur.filter(x=>x.amount>0);
  return `<div class="fx-tag"><b>CASH RUNWAY</b><span>● ${enNum(r.runs)}টা কল্পিত ভবিষ্যৎ · ${enNum(kz.ms)} মিলিসেকেন্ডে${r.hasHist?` · গত ${enNum(r.histDays)} দিনের আসল খরচ-আয় থেকে`:''}</span></div>
    <div class="fx-chips">${chips}</div><div class="fx-wrap"><canvas id="kzCanvas"></canvas></div><div id="kzRead" class="fx-read">টেনে দেখো — কোন দিনে ক্যাশ কত থাকতে পারে</div>
    <div class="fx-cards"><div class="fx-gauge"><svg viewBox="0 0 100 100"><circle cx="50" cy="50" r="44" class="bg"/><circle cx="50" cy="50" r="44" class="fg" id="kzRing" style="stroke:${col};stroke-dasharray:${circ.toFixed(1)};stroke-dashoffset:${circ.toFixed(1)}" data-to="${(circ*(1-r.pRunout)).toFixed(1)}"/></svg><div class="fx-gn" style="color:${col}">${enNum(pr)}%</div></div>
      <div class="fx-gl"><b>${enNum(D)} দিনের মধ্যে ক্যাশ ফুরিয়ে যাওয়ার (0-র নিচে নামার) সম্ভাবনা</b><span>এখন ক্যাশ <em>${kzT(kz.inp.cash)}</em> → ${enNum(D)} দিন পরে মাঝারি <em>${kzT(b.p50)}</em></span><span>খারাপ দিনে (10%) <em class="${b.p10<0?'dn':''}">${kzT(b.p10)}</em> · ভালো দিনে (90%) <em class="up">${kzT(b.p90)}</em></span>${r.p10NegDay?`<span class="dn">⚠️ খারাপ পরিস্থিতিতে প্রায় ${enNum(r.p10NegDay)} দিনের মাথায় ক্যাশ ফুরোতে পারে</span>`:''}</div></div>
    ${!r.hasHist||r.histDays<14?`<div class="sm-hint">ℹ️ ক্যাশবক্সে ${r.hasHist?'মাত্র '+enNum(r.histDays)+' দিনের':'কোনো'} এন্ট্রি আছে। কমপক্ষে 2 সপ্তাহ এন্ট্রি দিলে এই পূর্বাভাস অনেক নির্ভুল হবে।</div>`:''}
    <div class="rd-sec">⚡ কোন পদক্ষেপে ক্যাশ সবচেয়ে বেশি নিরাপদ?</div>
    ${kz.lv.map(l=>`<div class="fx-lev"><div class="fx-lt"><span>${escapeHtml(l.label)}</span><b class="${l.dEnd>=0?'up':'dn'}">${l.dEnd>=0?'+':'−'}${enTaka(Math.abs(l.dEnd))}</b></div><div class="rd-bar"><i style="width:${Math.max(3,Math.abs(l.dEnd)/maxd*100)}%;background:${l.dEnd>=0?'var(--paid)':'var(--due)'}"></i></div><div class="fx-ls">${enNum(D)} দিন পরে খারাপ-দিনের ক্যাশে · ফুরোনোর সম্ভাবনা ${l.dRun<=0?'−':'+'}${enNum(Math.round(Math.abs(l.dRun)*100))}%</div></div>`).join('')}
    ${recur.length?`<div class="rd-sec">🔁 হিসাবে ধরা রিপিট বিল/আয়</div>${recur.map(x=>`<div class="fx-risk"><span>${x.kind==='in'?'পাওনা আয়':'রিপিট খরচ'} — মাসের ${enNum(x.day)} তারিখ</span><em>${x.kind==='in'?'+':'−'}${enTaka(x.amount)}</em></div>`).join('')}`:''}
    <div class="fx-asm"><b>🧪 অনুমান (সৎভাবে):</b><div>• দৈনিক খরচ-আয় তোমার গত ${enNum(Math.min(90,r.histDays||0))} দিনের আসল দিনগুলো থেকে র‍্যান্ডম তুলে নেওয়া (রিপিট এন্ট্রি আলাদা ধরা)।</div><div>• প্রতিটা দেনাদার 30 দিনে শোধের সম্ভাবনা বিশ্বাস-স্কোর থেকে; শোধ করলে একবারে, কখনো অর্ধেক।</div><div>• "আমি দেব" (যাদের কাছে ধার) এখানে ধরা হয়নি; উৎসব/পরীক্ষার মতো বিশেষ খরচও না। এটা <b>সম্ভাবনার পরিসর</b>, ভবিষ্যদ্বাণী নয়।</div></div>`;
}
function kzDays_(d){ kz.days=d; kz.cursor=null; kzRender(true); }
function kzSetup(animate){
  const cv=document.getElementById('kzCanvas'); if(!cv) return; const W=cv.parentElement.clientWidth||340, H=250, dpr=Math.min(2,window.devicePixelRatio||1);
  cv.width=W*dpr; cv.height=H*dpr; cv.style.width=W+'px'; cv.style.height=H+'px'; kz.W=W; kz.H=H; kz.dpr=dpr;
  const at=e=>{ const r=cv.getBoundingClientRect(), x=(e.clientX-r.left-44)/(W-44-14); kz.cursor=Math.max(0,Math.min(kz.days,Math.round(x*kz.days))); if(!kz.raf) kzDraw(1); kzReadout(); };
  cv.onpointerdown=e=>{ cv.setPointerCapture(e.pointerId); at(e); }; cv.onpointermove=e=>{ if(e.buttons||e.pointerType==='touch') at(e); };
  const reduce=!!(window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches);
  setTimeout(()=>{ const ring=document.getElementById('kzRing'); if(ring) ring.style.strokeDashoffset=ring.dataset.to; },60);
  if(animate&&!reduce){ kz.t=0; kz.last=performance.now(); if(kz.raf) cancelAnimationFrame(kz.raf); kz.raf=requestAnimationFrame(kzFrame); } else { kz.t=1; kzDraw(1); }
}
function kzFrame(ts){
  const cv=document.getElementById('kzCanvas'); if(!cv||!cv.offsetParent||document.hidden){ kz.raf=0; return; }
  kz.t=Math.min(1,kz.t+Math.min(0.05,(ts-kz.last)/1000)/2); kz.last=ts; kzDraw(kz.t); kz.raf=kz.t<1?requestAnimationFrame(kzFrame):0;
}
function kzReadout(){ const el=document.getElementById('kzRead'); if(!el||kz.cursor==null||!kz.res) return; const b=kz.res.bands[kz.cursor]; el.innerHTML=`<b>${kz.cursor===0?'আজ':enNum(kz.cursor)+' দিন পরে'}</b> — খারাপ <span class="${b.p10<0?'dn':''}">${kzT(b.p10)}</span> · মাঝারি <span style="color:#f2c85e">${kzT(b.p50)}</span> · ভালো <span class="up">${kzT(b.p90)}</span>`; }
function kzDraw(t){
  const cv=document.getElementById('kzCanvas'); if(!cv||!kz.res) return; const ctx=cv.getContext('2d'), W=kz.W, H=kz.H, r=kz.res, D=r.days;
  ctx.setTransform(kz.dpr,0,0,kz.dpr,0,0); const bg=ctx.createLinearGradient(0,0,0,H); bg.addColorStop(0,'#0a1230'); bg.addColorStop(1,'#03040c'); ctx.fillStyle=bg; ctx.fillRect(0,0,W,H);
  const padL=44, padR=14, padT=14, padB=24, x=d=>padL+(W-padL-padR)*d/D;
  let hi=Math.max(...r.bands.map(b=>b.p90),1)*1.08, lo=Math.min(...r.bands.map(b=>b.p10),0)*1.1; if(hi-lo<1) hi=lo+1; const y=v=>padT+(H-padT-padB)*(hi-v)/(hi-lo);
  ctx.font='10px sans-serif'; ctx.lineWidth=1; ctx.strokeStyle='rgba(120,190,255,0.12)'; ctx.fillStyle='rgba(180,210,255,0.55)'; ctx.textAlign='right';
  for(let k=0;k<=4;k++){ const v=lo+(hi-lo)*k/4, yy=y(v); ctx.beginPath(); ctx.moveTo(padL,yy); ctx.lineTo(W-padR,yy); ctx.stroke(); ctx.fillText(Math.abs(v)>=1000?(v<0?'−':'')+enNum(Math.round(Math.abs(v)/1000))+'k':enNum(Math.round(v)),padL-6,yy+3); }
  ctx.textAlign='center'; [0,0.25,0.5,0.75,1].forEach(f=>{ const d=Math.round(D*f); ctx.fillText(enNum(d),x(d),H-8); });
  const zero=y(0); ctx.strokeStyle='rgba(255,100,120,0.7)'; ctx.setLineDash([5,4]); ctx.lineWidth=1.3; ctx.beginPath(); ctx.moveTo(padL,zero); ctx.lineTo(W-padR,zero); ctx.stroke(); ctx.setLineDash([]); ctx.fillStyle='rgba(255,140,160,0.9)'; ctx.textAlign='left'; ctx.fillText('0 = ক্যাশ শেষ',padL+4,zero-4);
  const upto=Math.round(t*D), band=(a,b,al)=>{ ctx.beginPath(); for(let d=0;d<=upto;d++){ const yy=y(r.bands[d][b]); d?ctx.lineTo(x(d),yy):ctx.moveTo(x(d),yy); } for(let d=upto;d>=0;d--) ctx.lineTo(x(d),y(r.bands[d][a])); ctx.closePath(); ctx.fillStyle=`rgba(120,200,255,${al})`; ctx.fill(); };
  band('p10','p90',0.13); band('p25','p75',0.22);
  ctx.strokeStyle='#f2c85e'; ctx.lineWidth=2.4; ctx.shadowColor='rgba(242,200,94,0.9)'; ctx.shadowBlur=10; ctx.beginPath(); for(let d=0;d<=upto;d++){ d?ctx.lineTo(x(d),y(r.bands[d].p50)):ctx.moveTo(x(d),y(r.bands[d].p50)); } ctx.stroke(); ctx.shadowBlur=0;
  ctx.strokeStyle='rgba(255,138,154,0.85)'; ctx.lineWidth=1.4; ctx.beginPath(); for(let d=0;d<=upto;d++){ d?ctx.lineTo(x(d),y(r.bands[d].p10)):ctx.moveTo(x(d),y(r.bands[d].p10)); } ctx.stroke();
  if(kz.cursor!=null){ const c=kz.cursor, xc=x(c); ctx.strokeStyle='rgba(255,255,255,0.55)'; ctx.setLineDash([3,4]); ctx.beginPath(); ctx.moveTo(xc,padT); ctx.lineTo(xc,H-padB); ctx.stroke(); ctx.setLineDash([]); [['p10','#ff8a9a'],['p50','#f2c85e'],['p90','#7dffd8']].forEach(([k,col])=>{ ctx.fillStyle=col; ctx.shadowColor=col; ctx.shadowBlur=8; ctx.beginPath(); ctx.arc(xc,y(r.bands[c][k]),4,0,6.283); ctx.fill(); ctx.shadowBlur=0; }); }
}

/* ===== js/21-ai.js ===== */
/* ============ 🤖 AI সহকারী (Claude) — গোপনীয়তা-আগে নকশা ============ */
/* • নাম/ফোন ফোনেই সরিয়ে ("ছাত্র-1") তবেই কিছু বাইরে যায়; উত্তর এলে ফোনেই আবার আসল নাম বসে। */
/* • API কী অ্যাপে থাকে না — শুধু তোমার Netlify সার্ভারে (netlify/functions/ai.mjs)। অ্যাপ পাসকোড দিয়ে সেই ফাংশনকে ডাকে। */
/* • চ্যাটে AI সরাসরি তোমার ডেটা দেখে না: সে "টুল" চায় (যেমন ঝুঁকিতে কারা), টুল ফোনেই চলে, শুধু নাম-ছাড়া ফল ফেরত যায়। */
/* • AI না থাকলে (অফলাইন/পাসকোড নেই/সীমা শেষ) অ্যাপের বাকি সব আগের মতোই চলে — AI একটা বাড়তি স্তর, নির্ভরতা নয়। */

/* ---- pure (unit-tested) ---- */
/* বাংলাদেশি মোবাইল নম্বর (ইংরেজি/বাংলা অঙ্ক, +88, ফাঁক/হাইফেনসহ) → [ফোন]; টাকা বা তারিখ কাটে না */
const AI_PHONE_CAND=/\+?[\d০-৯][\d০-৯\s-]{8,16}[\d০-৯]/g;
function aiScrubPhones(t){ return String(t).replace(AI_PHONE_CAND,m=>{ const d=m.replace(/[০-৯]/g,c=>'০১২৩৪৫৬৭৮৯'.indexOf(c)).replace(/[\s-]/g,'').replace(/^\+/,''); return /^(?:88)?01[3-9]\d{8}$/.test(d)?'[ফোন]':m; }); }
function aiTokenMap(names){
  const uniq=[...new Set((names||[]).map(n=>String(n||'').trim()).filter(Boolean))].sort((a,b)=>b.length-a.length||a.localeCompare(b)), fwd={}, rev={};
  uniq.forEach((n,i)=>{ const t='ছাত্র-'+(i+1); fwd[n]=t; rev[t]=n; });
  return {fwd, rev, order:uniq};
}
function aiEsc(s){ return s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'); }
/* নাম (দীর্ঘটা আগে) → টোকেন; ফোন নম্বর → [ফোন] */
function aiScrub(text, map){
  let t=aiScrubPhones(text==null?'':text);
  map.order.forEach(n=>{ t=t.replace(new RegExp(aiEsc(n),'g'),map.fwd[n]); }); return t;
}
/* টোকেন (বড় নম্বর আগে, যাতে "ছাত্র-10"-এর ভেতরে "ছাত্র-1" না ভাঙে) → আসল নাম */
function aiRestore(text, map){
  let t=String(text==null?'':text); Object.keys(map.rev).sort((a,b)=>b.length-a.length).forEach(k=>{ t=t.split(k).join(map.rev[k]); }); return t;
}
const AI_TONES={warm:'আন্তরিক ও উষ্ণ',polite:'বিনয়ী ও পেশাদার',firm:'ভদ্র কিন্তু দৃঢ়'};
function aiPolishSystem(tone, len){
  return `You help a private tutor in Bangladesh polish a WhatsApp message to a student's parent. Rewrite the draft in natural, polite Bangla. Tone: ${AI_TONES[tone]||AI_TONES.polite}. Keep every fact, number, date and amount exactly as written. Keep tokens such as ছাত্র-1 or [ফোন] unchanged. Do not add new facts, promises, deadlines or threats. Keep it under ${Math.round(len*1.3+40)} characters. Output ONLY the message text, nothing else.`;
}
const AI_CHAT_SYSTEM='তুমি একজন বাংলাদেশি প্রাইভেট টিউটরের সহকারী। শুধু টুল থেকে পাওয়া তথ্যের ভিত্তিতে বাংলায় সংক্ষেপে (সর্বোচ্চ ৫ বাক্য) উত্তর দাও। তথ্য না থাকলে সরাসরি "জানি না" বলে কোন তথ্য লাগবে তা বলো — আন্দাজ কোরো না। ছাত্রদের নাম "ছাত্র-N" টোকেনে আসে; উত্তরেও হুবহু ওই টোকেনই লেখো। কোনো ছাত্রকে দোষারোপ কোরো না — স্কোর ও সম্ভাবনা ইঙ্গিত মাত্র, রায় নয়। চিকিৎসা বা আইনি পরামর্শ দিও না।';
/* anthropic content blocks → {text, toolUses[]} */
function aiBlocks(content){
  const text=(content||[]).filter(b=>b&&b.type==='text').map(b=>b.text).join('\n').trim(), toolUses=(content||[]).filter(b=>b&&b.type==='tool_use');
  return {text, toolUses};
}
const AI_ERR={offline:'ইন্টারনেট নেই — AI-র জন্য নেট লাগে',no_pass:'AI-র পাসকোড দেওয়া নেই (সেটিংস → AI সহকারী)',not_configured:'সার্ভারে AI চালু করা হয়নি (ANTHROPIC_API_KEY নেই)',no_passcode:'সার্ভারে AI_PASSCODE সেট করা নেই',bad_pass:'পাসকোড মেলেনি',cap:'আজকের AI-র সীমা শেষ — কাল আবার চেষ্টা করো',slow:'AI ধীরে সাড়া দিল — আবার চেষ্টা করো',upstream_auth:'Claude API কী ঠিক নেই — Netlify-তে দেখো',upstream_rate:'Claude এখন ব্যস্ত — একটু পরে',upstream_bad:'অনুরোধটা Claude নিতে পারেনি',upstream:'Claude-এর দিকে সমস্যা — একটু পরে',http_404:'AI ফাংশন ডিপ্লয় করা নেই (netlify/functions/ai.mjs)',http_502:'সার্ভারে সমস্যা — আবার চেষ্টা করো',timeout:'সময় শেষ — আবার চেষ্টা করো'};
function aiErrText(code){ return AI_ERR[code]||('AI ত্রুটি: '+code); }

/* ---- transport ---- */
const AI_URL='/.netlify/functions/ai';
function aiDevice(){ let d=lsGet('tr_aiDev',''); if(!/^[A-Za-z0-9_-]{16,64}$/.test(d)){ const b=crypto.getRandomValues(new Uint8Array(18)); d='d'+[...b].map(x=>x.toString(36).padStart(2,'0')).join('').slice(0,30); lsSet('tr_aiDev',d); } return d; }
function aiOn(){ return lsGet('tr_aiOn',true)!==false; }
async function aiCall(o){
  if(!navigator.onLine) return {ok:false,error:'offline'};
  const pass=lsGet('tr_aiPass',''); if(!pass) return {ok:false,error:'no_pass'};
  const ctrl=new AbortController(), to=setTimeout(()=>ctrl.abort(),25000);
  try{
    const res=await fetch(AI_URL,{method:'POST',headers:{'Content-Type':'application/json'},signal:ctrl.signal,body:JSON.stringify({pass,device:aiDevice(),model:o.model||'claude-haiku-5-5',system:o.system,messages:o.messages,tools:o.tools,max_tokens:o.max_tokens||600})});
    const j=await res.json().catch(()=>({}));
    if(!res.ok) return {ok:false,error:j.error||('http_'+res.status),which:j.which};
    if(j.remaining) lsSet('tr_aiLeft',Object.assign({d:dateKeyStr(todayDateOnly())},j.remaining));
    return {ok:true,data:j};
  }catch(e){ return {ok:false,error:(e&&e.name==='AbortError')?'timeout':'offline'}; } finally { clearTimeout(to); }
}
function aiLeftText(){ const l=lsGet('tr_aiLeft',null); return (l&&l.d===dateKeyStr(todayDateOnly()))?`আজ আর ${toBn(l.device)}টা অনুরোধ বাকি`:''; }

/* ---- ১) মেসেজ AI দিয়ে সাজানো (২ ও ৩ নম্বরের মেসেজ পাতায় বসে) ---- */
function aiMsgHtml(){
  if(!aiOn()) return '';
  return `<div class="ai-box"><div class="ai-t">✨ AI দিয়ে সাজাও <small>নাম ও ফোন ছাড়া পাঠানো হয়</small></div><div class="ai-tones">${Object.keys(AI_TONES).map(k=>`<button type="button" class="pct-chip" onclick="aiPolish('${k}')">${AI_TONES[k]}</button>`).join('')}</div><div id="aiMsgNote" class="ai-note"></div></div>`;
}
let aiPrevMsg=null;
async function aiPolish(tone){
  const ta=document.getElementById('sm_msg'), note=document.getElementById('aiMsgNote'); if(!ta) return; const draft=ta.value.trim(); if(!draft){ showWarningToast('আগে মেসেজ লেখো।'); return; }
  if(!lsGet('tr_aiPass','')){ aiSetupPage(); return; }
  const map=aiTokenMap(aiNames()); note.textContent='⏳ AI সাজাচ্ছে…';
  const r=await aiCall({system:aiPolishSystem(tone,draft.length),messages:[{role:'user',content:aiScrub(draft,map)}],max_tokens:500});
  if(!r.ok){ note.textContent='⚠️ '+aiErrText(r.error); return; }
  const out=aiBlocks(r.data.content).text; if(!out){ note.textContent='⚠️ AI কিছু লেখেনি — আবার চেষ্টা করো'; return; }
  aiPrevMsg=ta.value; ta.value=aiRestore(out,map);
  note.innerHTML=`✅ সাজানো হয়েছে — পাঠানোর আগে পড়ে নাও। <button type="button" class="ai-undo" onclick="aiUndoMsg()">↩ আগের লেখা ফেরাও</button> ${aiLeftText()}`;
}
function aiUndoMsg(){ const ta=document.getElementById('sm_msg'); if(ta&&aiPrevMsg!=null){ ta.value=aiPrevMsg; const n=document.getElementById('aiMsgNote'); if(n) n.textContent='আগের লেখা ফেরানো হয়েছে।'; } }

/* ---- ২) চ্যাট: AI টুল চায়, টুল ফোনেই চলে ---- */
function aiNames(){
  const n=[]; try{ getAllKnownNames().forEach(x=>n.push(x)); Object.keys(khataBalances(getKhata())).forEach(x=>n.push(x)); const st=lsGet('tr_students',{}); Object.keys(st).forEach(k=>{ n.push(k); const g=(st[k]||{}).guardianName; if(g) n.push(g); }); }catch(e){}
  return n;
}
const AI_TOOLS=[
  {name:'get_overview',description:'টিউশনের সারসংক্ষেপ: ছাত্র সংখ্যা, সপ্তাহের ক্লাস-ঘণ্টা, ঝুঁকি ও সিলেবাসের গণনা (টাকার তথ্য নয়)',input_schema:{type:'object',properties:{}}},
  {name:'list_risky_students',description:'ঝুঁকিতে থাকা ছাত্রদের তালিকা (স্কোর ও কারণসহ), সবচেয়ে ঝুঁকিপূর্ণ আগে',input_schema:{type:'object',properties:{limit:{type:'integer',minimum:1,maximum:10}}}},
  {name:'get_student',description:'একজন ছাত্রের বিস্তারিত: উপস্থিতি, অগ্রগতি, সপ্তাহে ক্লাস, ঝুঁকির কারণ, সিলেবাস অবস্থা। id যেমন "ছাত্র-3"',input_schema:{type:'object',properties:{id:{type:'string'}},required:['id']}},
  {name:'get_syllabus_status',description:'সিলেবাস পূর্বাভাস: কে ঠিক পথে, কে ঝুঁকিতে, কে পিছিয়ে',input_schema:{type:'object',properties:{}}},
  {name:'get_money_summary',description:'আর্থিক সারসংক্ষেপ: মাসের আয়, ঘণ্টা-প্রতি আয় (শুধু ফাইন্যান্স আনলক থাকলে)',input_schema:{type:'object',properties:{}}}
];
let aiSess=null;
function aiRunTool(name,input){
  const map=aiSess.map; input=input||{};
  try{
    if(name==='get_overview'){
      const names=getAllKnownNames(), ch=churnAll(), sf=sfAll().filter(s=>s.hasTargets), rd=radarData();
      return {students:names.length, weekly_class_hours:Math.round(rd.weeklyHrs*10)/10, free_slots_per_week:rd.free.length, risk:{high:ch.filter(x=>x.band==='high').length,medium:ch.filter(x=>x.band==='medium').length,low:ch.filter(x=>x.band==='low').length}, syllabus:{behind:sf.filter(s=>s.status==='behind'||s.status==='overdue').length,at_risk:sf.filter(s=>s.status==='risk').length,on_track:sf.filter(s=>s.status==='ok').length}};
    }
    if(name==='list_risky_students'){
      const lim=Math.max(1,Math.min(10,Number(input.limit)||5)); return {students:churnAll().filter(x=>x.band!=='low').slice(0,lim).map(x=>({id:map.fwd[x.name],band:x.band,score:x.score,reasons:x.reasons.slice(0,3).map(r=>isFinanceHidden()&&r.key==='pay'?'আর্থিক কারণ (লুকানো)':r.text)}))};
    }
    if(name==='get_student'){
      const real=map.rev[String(input.id||'').trim()]; if(!real) return {error:'এই id-র কোনো ছাত্র নেই'};
      const ix=smIndex(), f=churnFeatures(real,ix), r=churnScore(f), sf=sfAll().find(s=>s.name===real), sess=sfSessionDates(real,7).length, sum=(()=>{ try{ return computeStudentSummary(real); }catch(e){ return {}; } })();
      return {id:input.id, attendance_percent:sum.attendanceRate==null?null:Math.round(sum.attendanceRate), progress_percent:Math.round(thkProgress(real)), classes_per_week:(function(){ let c=0; SCHEDULE.forEach(s=>DAYS.forEach(d=>{ if(getCellText(s,d).split(',').map(x=>x.trim()).includes(real)) c++; })); return c; })(), risk:{band:r.band,score:r.score,reasons:r.reasons.map(x=>isFinanceHidden()&&x.key==='pay'?'আর্থিক কারণ (লুকানো)':x.text)}, syllabus:sf?{status:sf.status}:null};
    }
    if(name==='get_syllabus_status') return {students:sfAll().filter(s=>s.hasTargets).map(s=>({id:map.fwd[s.name],status:s.status,next_deadline_missing_chapters:s.items[0]?Math.round(s.items[0].need*10)/10:0}))};
    if(name==='get_money_summary'){
      if(isFinanceHidden()) return {locked:true,message:'ফাইন্যান্স আনলক করা নেই'};
      const rd=radarData(); return {monthly_income:rd.income, hourly_rate:Math.round(rd.avg), students_paying:rd.rows.filter(r=>r.fee>0).length, students_without_fee:rd.noFee.length};
    }
    return {error:'অজানা টুল'};
  }catch(e){ return {error:'টুল চালাতে সমস্যা'}; }
}
let aiChat={msgs:[],busy:false,log:[]};
function aiChatOpen(){
  if(!lsGet('tr_aiPass','')){ aiSetupPage(); return; }
  aiSess={map:aiTokenMap(aiNames())}; aiChat={msgs:[],busy:false,log:[]};
  const sugg=['এই সপ্তাহে কাকে নিয়ে সবচেয়ে বেশি চিন্তা করা উচিত?','সিলেবাস নিয়ে কে সবচেয়ে বিপদে?','আমার টিউশনের সার্বিক অবস্থা কেমন?'];
  showKhataModal('🤖 AI জিজ্ঞেস করো',`<div id="aiChatBox"><div class="ai-priv">🔒 নাম ও ফোন ছাড়া পাঠানো হয় · AI ফোনের ডেটা সরাসরি দেখে না, শুধু টুলের ফল পায়</div><div id="aiLog" class="ai-log"></div>
    <div class="ai-sugg">${sugg.map(s=>`<button type="button" class="pct-chip" onclick="aiSuggest(this)">${s}</button>`).join('')}</div>
    <div class="ai-in"><input class="kh-in" id="ai_q" placeholder="যা জানতে চাও লেখো…" autocomplete="off" onkeydown="if(event.key==='Enter'){event.preventDefault();aiSend();}"><button type="button" class="kh-fab" onclick="aiSend()">পাঠাও</button></div><div id="aiLeft" class="ai-note">${aiLeftText()}</div></div>`);
}
function aiSuggest(b){ document.getElementById('ai_q').value=b.textContent; aiSend(); }
function aiLogAdd(who,html,cls){ const l=document.getElementById('aiLog'); if(!l) return null; const d=document.createElement('div'); d.className='ai-b '+who+(cls?' '+cls:''); d.innerHTML=html; l.appendChild(d); l.scrollTop=l.scrollHeight; d.scrollIntoView&&d.scrollIntoView({block:'nearest'}); return d; }
async function aiSend(){
  const inp=document.getElementById('ai_q'); if(!inp||aiChat.busy) return; const q=inp.value.trim(); if(!q) return; inp.value=''; aiChat.busy=true;
  aiLogAdd('me',escapeHtml(q)); const wait=aiLogAdd('ai','⏳ ভাবছি…','wait'); let tools=0;
  aiChat.msgs.push({role:'user',content:aiScrub(q,aiSess.map)});
  for(let round=0;round<5;round++){
    const r=await aiCall({system:AI_CHAT_SYSTEM,messages:aiChat.msgs,tools:AI_TOOLS,max_tokens:700});
    if(!r.ok){ wait.className='ai-b ai err'; wait.textContent='⚠️ '+aiErrText(r.error); aiChat.msgs.pop(); aiChat.busy=false; return; }
    const {text,toolUses}=aiBlocks(r.data.content); aiChat.msgs.push({role:'assistant',content:r.data.content});
    if(r.data.stop_reason==='tool_use' && toolUses.length){
      const results=toolUses.map(t=>{ tools++; return {type:'tool_result',tool_use_id:t.id,content:JSON.stringify(aiRunTool(t.name,t.input))}; });
      aiChat.msgs.push({role:'user',content:results}); wait.textContent='🔧 তথ্য দেখছি…'; continue;
    }
    wait.className='ai-b ai'; wait.innerHTML=escapeHtml(aiRestore(text||'কোনো উত্তর পাইনি।',aiSess.map)).replace(/\n/g,'<br>')+`<div class="ai-meta">🔧 ${toBn(tools)}টা টুল · 🔒 নাম ছাড়া</div>`;
    const l=document.getElementById('aiLeft'); if(l) l.textContent=aiLeftText(); aiChat.busy=false; return;
  }
  wait.className='ai-b ai err'; wait.textContent='⚠️ অনেক ধাপ লাগছে — প্রশ্নটা ছোট করে আবার করো।'; aiChat.busy=false;
}

/* ---- সেটিংস কার্ড + সেটআপ পাতা ---- */
function aiCardHtml(){
  const has=!!lsGet('tr_aiPass','');
  return `<div id="aiCard" class="ab-card" style="margin-top:12px;"><div style="font-size:12.5px;font-weight:700;color:var(--paper);margin-bottom:4px;">🤖 AI সহকারী (Claude)</div>
    <div class="backup-status${has&&aiOn()?'':' backup-status-warn'}">${!aiOn()?'⏸ বন্ধ করা আছে':(has?'✅ পাসকোড দেওয়া আছে '+aiLeftText():'⚠️ এখনো চালু হয়নি — নিচে ধাপগুলো দেখো')}</div>
    <input class="kh-in" id="ai_pass" type="password" placeholder="AI পাসকোড (Netlify-তে যা দিয়েছ)" autocomplete="off" style="margin-top:8px;">
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:8px;"><button class="settings-btn" style="margin:0;" onclick="aiSavePass()">💾 সেভ</button><button class="settings-btn" style="margin:0;" onclick="aiTest()">🧪 পরীক্ষা</button></div>
    <button class="settings-btn" onclick="aiToggle()">${aiOn()?'⏸ AI বন্ধ করো':'▶️ AI চালু করো'}</button><button class="settings-btn" onclick="aiSetupPage()">📖 সেটআপের ধাপ ও গোপনীয়তা</button><div id="aiTestNote" class="ai-note"></div></div>`;
}
function aiSavePass(){ const v=(document.getElementById('ai_pass').value||'').trim(); if(!v){ showWarningToast('পাসকোড লেখো।'); return; } lsSet('tr_aiPass',v); showSuccessToast('AI পাসকোড সেভ হয়েছে'); const c=document.getElementById('aiCard'); if(c) c.outerHTML=aiCardHtml(); }
function aiToggle(){ lsSet('tr_aiOn',!aiOn()); const c=document.getElementById('aiCard'); if(c) c.outerHTML=aiCardHtml(); }
async function aiTest(){
  const n=document.getElementById('aiTestNote'); if(n) n.textContent='⏳ পরীক্ষা চলছে…';
  const r=await aiCall({system:'Reply with exactly: ঠিক আছে',messages:[{role:'user',content:'test'}],max_tokens:20});
  if(n) n.textContent=r.ok?('✅ AI কাজ করছে। '+aiLeftText()):('⚠️ '+aiErrText(r.error));
}
function aiSetupPage(){
  showKhataModal('📖 AI সেটআপ',`<div class="ai-setup"><div class="ai-priv">🔒 <b>কী বাইরে যায়:</b> নাম ও ফোন সরানো মেসেজের খসড়া, আর টুলের নাম-ছাড়া সারসংক্ষেপ (যেমন "ছাত্র-3: ঝুঁকি উচ্চ, কারণ অনুপস্থিতি")। <b>কী যায় না:</b> আসল নাম, ফোন নম্বর, ব্যাকআপ, খাতার লেনদেন।</div>
    <ol class="ai-steps"><li><b>Claude Platform-এ অ্যাকাউন্ট</b> খুলে একটা <b>API কী</b> বানাও (platform.claude.com)। সেখানে মাসিক <b>খরচের সীমা (spend limit)</b> ছোট একটা অঙ্কে বেঁধে দাও।</li>
    <li><b>Netlify</b> → তোমার প্রজেক্ট → Project configuration → Environment variables-এ দুটো যোগ করো: <code>ANTHROPIC_API_KEY</code> = ওই কী; <code>AI_PASSCODE</code> = তোমার নিজের বানানো একটা গোপন শব্দ।</li>
    <li>অ্যাপ আবার <b>ডিপ্লয়</b> করো (ফাংশন <code>ai.mjs</code> সহ পুরো ফোল্ডার)।</li>
    <li>এখানে সেটিংস → <b>AI সহকারী</b>-তে ওই গোপন শব্দ বসিয়ে সেভ করে <b>পরীক্ষা</b> চাপো।</li></ol>
    <div class="ai-priv">💰 <b>খরচ:</b> ছোট দ্রুত মডেল (Haiku 5.5) ব্যবহার হয়; প্রকাশিত দাম প্রায় $0.10 / $0.50 প্রতি ১০ লক্ষ টোকেন (ইনপুট/আউটপুট) — একটা চ্যাট-উত্তর সাধারণত এক সেন্টের ভগ্নাংশ। সঠিক দাম অফিসিয়াল প্রাইসিং পাতায় দেখে নিও। ফাংশনে নিজেই দৈনিক সীমা আছে (ডিভাইসপ্রতি ৮০, মোট ৪০০ অনুরোধ)।</div>
    <div class="ai-priv">🛡️ পাসকোড না থাকলে ফাংশন নিজেই চলতে অস্বীকার করে — যাতে অন্য কেউ তোমার টাকায় AI চালাতে না পারে।</div></div>`);
}

/* ===== js/22-bio.js ===== */
/* ============ 👆 আঙুলের ছাপ / ফেস লক (WebAuthn) ============ */
/* ফোনের নিজস্ব বায়োমেট্রিক (স্ক্রিন-লক) ব্যবহার হয় — আঙুলের ছাপ অ্যাপে বা কোথাও জমা হয় না, শুধু ফোন "হ্যাঁ, ঠিক মানুষ" সই করে দেয়। */
/* অ্যাপ সেই সই ফোনেই যাচাই করে (চ্যালেঞ্জ + আসল পাবলিক-কী)। আর্থিক হিসাব দেখানো, খাতা খোলা, এমনকি অ্যাপ খোলা — প্রতিটা আলাদাভাবে লক করা যায়। */
/* নিরাপত্তার সীমা (সৎভাবে): এটা অন্যের হাতে থাকা আনলক করা ফোন থেকে অ্যাপের গোপন তথ্য আড়াল করে; কেউ ফোনের ব্রাউজার-ডেটা সরাসরি ঘাঁটলে এটা ঠেকায় না। */
/* নিজেকে লক করে ফেলার বিপদ ঠেকাতে: চালুর আগে একবার সফল যাচাই লাগে, আর রিকভারি-কোড (অনলাইন ব্যাকআপের কোড) দিয়ে সবসময় বন্ধ করা যায়। */

/* ---- pure (unit-tested) ---- */
function bioB64u(b){ let s=''; const u=b instanceof Uint8Array?b:new Uint8Array(b); for(let i=0;i<u.length;i++) s+=String.fromCharCode(u[i]); return btoa(s).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,''); }
function bioFromB64u(s){ s=String(s).replace(/-/g,'+').replace(/_/g,'/'); while(s.length%4) s+='='; const bin=atob(s), u=new Uint8Array(bin.length); for(let i=0;i<bin.length;i++) u[i]=bin.charCodeAt(i); return u; }
/* ECDSA সই: ASN.1 DER → WebCrypto-র কাঁচা r||s */
function bioDerToRaw(der, size){
  const b=der instanceof Uint8Array?der:new Uint8Array(der); let i=2; if(b[0]!==0x30) throw new Error('der'); if(b[1]&0x80) i=2+(b[1]&0x7f);
  if(b[i]!==0x02) throw new Error('der'); const rl=b[i+1]; let r=b.slice(i+2,i+2+rl); i=i+2+rl; if(b[i]!==0x02) throw new Error('der'); const sl=b[i+1]; let s=b.slice(i+2,i+2+sl);
  const fix=x=>{ while(x.length>size&&x[0]===0) x=x.slice(1); if(x.length>size) throw new Error('der'); const o=new Uint8Array(size); o.set(x,size-x.length); return o; };
  const out=new Uint8Array(size*2); out.set(fix(r),0); out.set(fix(s),size); return out;
}
/* authenticatorData: rpIdHash(32) | flags(1) | signCount(4) */
function bioParseAuth(a){ const u=a instanceof Uint8Array?a:new Uint8Array(a); if(u.length<37) return null; return {rpIdHash:u.slice(0,32), flags:u[32], up:!!(u[32]&1), uv:!!(u[32]&4), counter:((u[33]<<24)|(u[34]<<16)|(u[35]<<8)|u[36])>>>0}; }
/* কখন আবার লক হবে: lockMin 0 = ব্যাকগ্রাউন্ডে গেলেই, -1 = কখনো নয়, নইলে এত মিনিট পরে */
function bioShouldRelock(hiddenAt, now, lockMin){ if(hiddenAt==null||lockMin<0) return false; return lockMin===0?true:(now-hiddenAt)>=lockMin*60000; }
function bioBytesEq(a,b){ if(a.length!==b.length) return false; let r=0; for(let i=0;i<a.length;i++) r|=a[i]^b[i]; return r===0; }

/* ---- config ---- */
function bioCfg(){ const c=lsGet('tr_bio',null); return (c&&c.id&&c.pk)?c:null; }
function bioWants(scope){ const c=bioCfg(); return !!(c&&c.on&&c.scope&&c.scope[scope]); }
async function bioSupported(){ try{ return !!(window.PublicKeyCredential && PublicKeyCredential.isUserVerifyingPlatformAuthenticatorAvailable && await PublicKeyCredential.isUserVerifyingPlatformAuthenticatorAvailable()); }catch(e){ return false; } }
async function bioSha(bytes){ return new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)); }

/* ---- enrol / verify ---- */
async function bioEnroll(){
  if(!(await bioSupported())){ showWarningToast('এই ফোনে আঙুলের ছাপ/ফেস লক পাওয়া গেল না — ফোনের সেটিংসে স্ক্রিন-লক আর ফিঙ্গারপ্রিন্ট চালু আছে কি দেখো।'); return false; }
  try{
    const cred=await navigator.credentials.create({publicKey:{challenge:crypto.getRandomValues(new Uint8Array(32)), rp:{name:'আমার টিউশন রুটিন', id:location.hostname}, user:{id:crypto.getRandomValues(new Uint8Array(16)), name:'teacher', displayName:'শিক্ষক'}, pubKeyCredParams:[{type:'public-key',alg:-7},{type:'public-key',alg:-257}], authenticatorSelection:{authenticatorAttachment:'platform', userVerification:'required', residentKey:'discouraged'}, attestation:'none', timeout:60000}});
    const r=cred.response, pk=r.getPublicKey&&r.getPublicKey(), alg=r.getPublicKeyAlgorithm&&r.getPublicKeyAlgorithm(); if(!pk||(alg!==-7&&alg!==-257)) throw new Error('unsupported');
    lsSet('tr_bio',{id:bioB64u(new Uint8Array(cred.rawId)), pk:bioB64u(new Uint8Array(pk)), alg, on:false, scope:{finance:true,khata:true,app:false}, lockMin:2});
  }catch(e){ showWarningToast('আঙুলের ছাপ চালু করা গেল না'+((e&&e.name==='NotAllowedError')?' (বাতিল হয়েছে)':'')+'।'); return false; }
  if(!(await bioVerify('setup'))){ localStorage.removeItem('tr_bio'); showWarningToast('যাচাই মেলেনি — তাই চালু করলাম না (যাতে নিজেকে লক না করো)।'); return false; }
  try{ abGetKey(); }catch(e){}                                            // রিকভারি-কোড নিশ্চিত করা
  const c=bioCfg(); c.on=true; lsSet('tr_bio',c); bioRefreshCard(); showSuccessToast('আঙুলের ছাপ-লক চালু হয়েছে ✅'); return true;
}
let bioBusy=false;
async function bioVerify(why){
  const c=bioCfg(); if(!c||bioBusy) return false; bioBusy=true;
  try{
    const challenge=crypto.getRandomValues(new Uint8Array(32));
    const a=await navigator.credentials.get({publicKey:{challenge, allowCredentials:[{type:'public-key',id:bioFromB64u(c.id)}], userVerification:'required', rpId:location.hostname, timeout:60000}});
    const r=a.response, clientJSON=new Uint8Array(r.clientDataJSON), cd=JSON.parse(new TextDecoder().decode(clientJSON)), auth=new Uint8Array(r.authenticatorData), p=bioParseAuth(auth);
    if(cd.type!=='webauthn.get'||cd.challenge!==bioB64u(challenge)||cd.origin!==location.origin||!p||!p.up||!p.uv) return false;
    if(!bioBytesEq(p.rpIdHash, await bioSha(new TextEncoder().encode(location.hostname)))) return false;
    const data=new Uint8Array(auth.length+32); data.set(auth,0); data.set(await bioSha(clientJSON),auth.length); const sig=new Uint8Array(r.signature);
    if(c.alg===-7){ const key=await crypto.subtle.importKey('spki',bioFromB64u(c.pk),{name:'ECDSA',namedCurve:'P-256'},false,['verify']); return await crypto.subtle.verify({name:'ECDSA',hash:'SHA-256'},key,bioDerToRaw(sig,32),data); }
    const key=await crypto.subtle.importKey('spki',bioFromB64u(c.pk),{name:'RSASSA-PKCS1-v1_5',hash:'SHA-256'},false,['verify']); return await crypto.subtle.verify('RSASSA-PKCS1-v1_5',key,sig,data);
  }catch(e){ return false; } finally { bioBusy=false; }
}

/* ---- integrations ---- */
function bioHooks(){ /* (খাতা-লক ও আর্থিক আনলক সরাসরি bioWants() ডাকে — নিচে ০২/০৭ ফাইলে) */ }
async function khBioUnlock(){ if(await bioVerify('khata')){ khataUnlocked=true; renderKhataTab(); } else showWarningToast('যাচাই মেলেনি — আবার চেষ্টা করো।'); }
async function bioUnlockFinance(){ if(await bioVerify('finance')){ financeUnlocked=true; refreshFinanceViews(); } else showWarningToast('যাচাই মেলেনি — আর্থিক হিসাব লুকানোই থাকল।'); }
/* অ্যাপ-খোলার গেট */
let bioFails=0;
function bioGateShow(){
  if(document.getElementById('bioGate')) return; const g=document.createElement('div'); g.id='bioGate'; g.className='bio-gate'; bioFails=0;
  g.innerHTML=`<div class="bio-card"><div class="bio-ic">🔒</div><div class="bio-t">আমার টিউশন রুটিন</div><div class="bio-s">আনলক করতে ফোনের আঙুলের ছাপ বা ফেস লক লাগবে</div><button type="button" class="kh-fab" onclick="bioGateGo()">👆 আনলক করো</button><button type="button" id="bioStuck" class="bio-stuck" style="display:none" onclick="bioRecoverOff()">আনলক হচ্ছে না? রিকভারি কোড দিয়ে লক বন্ধ করো</button></div>`;
  document.body.appendChild(g);
}
async function bioGateGo(){ if(await bioVerify('app')){ const g=document.getElementById('bioGate'); if(g) g.remove(); } else { bioFails++; showWarningToast('মেলেনি — আবার চেষ্টা করো।'); if(bioFails>=2){ const s=document.getElementById('bioStuck'); if(s) s.style.display='block'; } } }
/* রিকভারি: অনলাইন ব্যাকআপের ২০-অক্ষরের কোড ঠিক হলে লক বন্ধ */
function bioRecoverOff(code){
  const input=(code!==undefined)?code:prompt('অনলাইন ব্যাকআপের রিকভারি কোড লেখো (সেটিংস → ব্যাকআপ → 🔑 রিকভারি কোড দেখো-তে ছিল):'); if(input===null||input===undefined) return false;
  const mine=abNorm(lsGet('tr_abKey','')); if(mine.length===20 && abNorm(input)===mine){ const c=bioCfg(); if(c){ c.on=false; lsSet('tr_bio',c); } const g=document.getElementById('bioGate'); if(g) g.remove(); bioRefreshCard(); showSuccessToast('আঙুলের ছাপ-লক বন্ধ হয়েছে'); return true; }
  showWarningToast('কোড মেলেনি।'); return false;
}
/* ব্যাকগ্রাউন্ড থেকে ফিরলে (সময় পেরোলে) আবার লক */
let bioHiddenAt=null;
function bioOnVisibility(hidden, now){
  const c=bioCfg(); if(!c||!c.on) return;
  if(hidden){ bioHiddenAt=now; return; }
  if(bioShouldRelock(bioHiddenAt,now,c.lockMin)){
    if(c.scope.finance&&financeUnlocked){ financeUnlocked=false; try{ refreshFinanceViews(); }catch(e){} }
    if(c.scope.khata&&khataUnlocked){ khataUnlocked=false; try{ renderKhataTab(); }catch(e){} }
    if(c.scope.app) bioGateShow();
  }
  bioHiddenAt=null;
}
document.addEventListener('visibilitychange',()=>bioOnVisibility(document.hidden,Date.now()));
if(bioWants('app')) bioGateShow();

/* ---- settings card ---- */
function bioCardHtml(){
  const c=bioCfg(), on=!!(c&&c.on), sc=(c&&c.scope)||{}, ck=(k,l)=>`<label class="kf-chk" style="margin-top:6px;"><input type="checkbox" ${sc[k]?'checked':''} onchange="bioScope('${k}',this.checked)"><span>${l}</span></label>`;
  const mins=[[0,'ব্যাকগ্রাউন্ডে গেলেই'],[2,'২ মিনিট'],[15,'১৫ মিনিট'],[-1,'কখনো নয়']];
  return `<div id="bioCard" class="ab-card" style="margin-top:12px;"><div style="font-size:12.5px;font-weight:700;color:var(--paper);margin-bottom:4px;">👆 আঙুলের ছাপ / ফেস লক</div>
    <div class="backup-status${on?'':' backup-status-warn'}">${on?'✅ চালু আছে':'⏸ বন্ধ আছে'}</div>
    <div style="font-size:11.5px;color:var(--muted);line-height:1.7;margin:8px 0;">ফোনের নিজের বায়োমেট্রিক ব্যবহার হয়; আঙুলের ছাপ অ্যাপে বা সার্ভারে যায় না। এটা অন্যের হাতে থাকা আনলক করা ফোন থেকে তোমার আর্থিক হিসাব ও খাতা আড়াল করে।</div>
    ${on?`${ck('finance','আর্থিক হিসাব দেখাতে')}${ck('khata','খাতা খুলতে')}${ck('app','অ্যাপ খুলতেই')}
      <div style="font-size:11.5px;color:var(--muted);margin:10px 0 4px;">আবার লক হবে:</div><div class="pct-chip-row">${mins.map(([m,l])=>`<button type="button" class="pct-chip${c.lockMin===m?' active':''}" onclick="bioLockMin(${m})">${l}</button>`).join('')}</div>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:8px;"><button class="settings-btn" style="margin:0;" onclick="bioTest()">🧪 পরীক্ষা</button><button class="settings-btn" style="margin:0;" onclick="bioDisable()">⏸ বন্ধ করো</button></div>`
    :`<button class="settings-btn" onclick="bioEnroll()">👆 চালু করো</button>`}
    <div id="bioNote" class="ai-note"></div></div>`;
}
function bioRefreshCard(){ const c=document.getElementById('bioCard'); if(c) c.outerHTML=bioCardHtml(); }
function bioScope(k,v){ const c=bioCfg(); if(!c) return; c.scope[k]=!!v; lsSet('tr_bio',c); if(k==='finance'&&v){ financeUnlocked=false; try{ refreshFinanceViews(); }catch(e){} } }
function bioLockMin(m){ const c=bioCfg(); if(!c) return; c.lockMin=m; lsSet('tr_bio',c); bioRefreshCard(); }
async function bioTest(){ const n=document.getElementById('bioNote'); if(n) n.textContent='⏳ ফোনের যাচাই আসছে…'; const ok=await bioVerify('test'); if(n) n.textContent=ok?'✅ যাচাই সফল — সব ঠিক আছে।':'⚠️ যাচাই মেলেনি।'; }
async function bioDisable(){
  if(await bioVerify('off')){ const c=bioCfg(); c.on=false; lsSet('tr_bio',c); bioRefreshCard(); showSuccessToast('আঙুলের ছাপ-লক বন্ধ হয়েছে'); return; }
  if(confirm('যাচাই হলো না। রিকভারি কোড দিয়ে বন্ধ করতে চাও?')) bioRecoverOff();
}

/* ===== js/23-schema.js ===== */
/* ============ V71 ভিত্তি — ডেটা-স্কিমা সংস্করণ, নিরাপদ মাইগ্রেশন, "মুছে ফেলা"র স্মৃতি (tombstone) ============ */
/* নিয়ম (পরিকল্পনা §৮): ডেটার গঠন বদলালে (১) আগে স্ন্যাপশট, (২) ছোট ও বারবার চালানো-নিরাপদ (idempotent) ধাপ, */
/* (৩) পুরোনো রেকর্ড অক্ষত, (৪) সংস্করণ নম্বর একটাই জায়গায় (tr_schemaVer)। এই ফাইলে শুধু ঘোষণা — চালু হয় নিচের শেষে। */
const SCHEMA_VERSION = 75;
const SCHEMA_KEYS_NEW = ['tr_qbank','tr_results','tr_resultCfg','tr_resultPins','tr_adjust','tr_tombstones','tr_schemaVer'];

/* প্রতিটা ধাপ: {v, id, run()} — শুধু যোগ করে, কিছু মোছে/বদলায় না; দ্বিতীয়বার চালালেও কিছু ডুপ্লিকেট হয় না। */
const SCHEMA_MIGRATIONS = [
  { v:72, id:'v72-qbank',    run(){ if(!Array.isArray(lsGet('tr_qbank', null))) lsSet('tr_qbank', []); } },
  { v:73, id:'v73-results',  run(){ if(!Array.isArray(lsGet('tr_results', null))) lsSet('tr_results', []);
                                    if(!lsGet('tr_resultCfg', null)) lsSet('tr_resultCfg', {good:80, practice:60, last:3});
                                    if(!lsGet('tr_resultPins', null)) lsSet('tr_resultPins', {}); } },
  { v:74, id:'v74-fees',     run(){ if(!Array.isArray(lsGet('tr_adjust', null))) lsSet('tr_adjust', []);
                                    /* আগের মেকআপ তালিকায় status/ইতিহাসের ঘর নেই — পুরোনো রেকর্ড যেমন আছে তেমনই, শুধু আইডি নেই এমনগুলোয় আইডি বসে */
                                    const mk=lsGet('tr_makeups', []); let ch=false;
                                    if(Array.isArray(mk)) mk.forEach(m=>{ if(m && !m.id){ m.id=Date.now()+'_'+Math.random().toString(36).slice(2,7); ch=true; } });
                                    if(ch) lsSet('tr_makeups', mk); } },
  { v:75, id:'v75-tombs',    run(){ const t=lsGet('tr_tombstones', null); if(!t || typeof t!=='object' || Array.isArray(t)) lsSet('tr_tombstones', {}); } },
];
/* কতগুলো ধাপ বাকি (কিছু না চালিয়ে) — টেস্ট ও প্রিভিউয়ের জন্য */
function schemaPending(cur){ return SCHEMA_MIGRATIONS.filter(m=>m.v>(cur|0)); }
/* চালায়, ফেরত দেয় যেসব ধাপ চলেছে তাদের আইডি। snapshotFn থাকলে আগে সেটা (ব্যর্থ হলে ধাপ আটকায় না, কিন্তু ফল জানায়) */
function runSchemaMigrations(snapshotFn){
  const cur=Number(lsGet('tr_schemaVer', 70))||70, todo=schemaPending(cur), done=[];
  if(!todo.length){ if(cur<SCHEMA_VERSION) lsSet('tr_schemaVer', SCHEMA_VERSION); return {from:cur, ran:done, snapshot:false}; }
  let snap=false; try{ if(snapshotFn){ snapshotFn('before-migrate-v'+SCHEMA_VERSION); snap=true; } }catch(e){}
  todo.forEach(m=>{ try{ m.run(); done.push(m.id); }catch(e){ try{ console.warn('migration failed', m.id, e); }catch(_){} } });
  if(done.length===todo.length) lsSet('tr_schemaVer', SCHEMA_VERSION);      // একটাও ব্যর্থ হলে সংস্করণ বাড়ে না — পরের বার আবার চেষ্টা
  return {from:cur, ran:done, snapshot:snap};
}

/* ---- tombstone: "এই রেকর্ডটা ইচ্ছে করে মোছা হয়েছে" — মার্জের সময় অন্য ডিভাইসের পুরোনো কপি যেন ফিরে না আসে ---- */
/* গঠন: { "pay:<id>": তারিখ-মিলিসেকেন্ড, "att:<key>": ..., "note:<key>": ..., "exp:<id>": ... } */
function tombAdd(kind, id){ try{ const t=lsGet('tr_tombstones', {}); t[kind+':'+id]=Date.now(); lsSet('tr_tombstones', tombPrune(t)); }catch(e){} }
function tombClear(kind, id){ try{ const t=lsGet('tr_tombstones', {}); const k=kind+':'+id; if(k in t){ delete t[k]; lsSet('tr_tombstones', t); } }catch(e){} }
function tombHas(t, kind, id){ return !!(t && Object.prototype.hasOwnProperty.call(t, kind+':'+id)); }
function tombPrune(t, maxAgeMs, now){ const lim=(now||Date.now())-(maxAgeMs||180*86400000); const o={}; Object.keys(t||{}).forEach(k=>{ if(Number(t[k])>=lim) o[k]=t[k]; }); return o; }

/* ---- চালু করা (শুধু ব্রাউজারে) ---- */
if(typeof document!=='undefined'){
  try{ runSchemaMigrations(typeof safetySnapshot==='function' ? safetySnapshot : null); }catch(e){}
}

/* ===== js/24-qgen.js ===== */
/* ============ V72 — নোট, প্রশ্ন ও প্রশ্নপত্র জেনারেটর ============ */
/* প্রবাহ: শ্রেণি/বিষয়/অধ্যায় বাছো → (AI দিয়ে বা হাতে) খসড়া → প্রতিটা প্রশ্ন সম্পাদনা/বাদ/আবার তৈরি/অনুমোদন → যাচাই (নম্বর, MCQ) → প্রিন্ট/ডাউনলোড (প্রশ্নপত্র আর উত্তরমালা আলাদা)। */
/* নিয়ম: AI-কে ছাত্রের নাম/ফোন কখনো পাঠানো হয় না; অনিশ্চিত হলে AI "unsure" চিহ্ন দেয়; শিক্ষক অনুমোদন ছাড়া প্রিন্ট/ডাউনলোড বন্ধ। */

const QP_KIND_LABEL = {mcq:'বহুনির্বাচনি (MCQ)', short:'সংক্ষিপ্ত প্রশ্ন', creative:'সৃজনশীল', note:'সহজ নোট'};
const QP_BATCH = {mcq:3, short:3, creative:1, note:1};          // এক অনুরোধে কতগুলো — সার্ভারের ছোট সীমার মধ্যে থাকতে
const QP_LABELS = ['ক','খ','গ','ঘ'];
const QP_PART_KIND = ['জ্ঞানমূলক','অনুধাবনমূলক','প্রয়োগমূলক','উচ্চতর দক্ষতা'];
const QP_PART_MARKS = [1,2,3,4];
const QP_BOARDS = {nctb:'জাতীয় কারিকুলাম (NCTB)', madrasa:'মাদ্রাসা (দাখিল/আলিম)', english:'ইংলিশ মিডিয়াম', other:'অন্যান্য'};
const QP_LANGS = {bn:'বাংলা', en:'English', both:'বাংলা + English'};
const QP_LEVELS = {weak:'দুর্বল', mid:'মাঝারি', good:'ভালো'};
const QP_DIFFS = {easy:'সহজ', mid:'মাঝারি', hard:'কঠিন'};
const QP_TYPES = {note:'শুধু সহজ নোট', mcq:'শুধু MCQ', short:'শুধু সংক্ষিপ্ত প্রশ্ন', creative:'শুধু সৃজনশীল', model:'মডেল টেস্ট (MCQ + সংক্ষিপ্ত + সৃজনশীল)'};

/* ---------- pure (unit-tested) ---------- */
function qpUid(){ return 'q'+Date.now().toString(36)+Math.random().toString(36).slice(2,6); }
function qpN(n){ return typeof toBn==='function' ? toBn(n) : String(n); }
function qpEsc(s){ return typeof escapeHtml==='function' ? escapeHtml(s) : String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
function qpNorm(s){ return String(s==null?'':s).replace(/\s+/g,' ').trim().toLowerCase(); }
function qpNewItem(kind){
  const b={id:qpUid(), kind, approved:false, unsure:false};
  if(kind==='mcq') return Object.assign(b,{q:'', options:['','','',''], ans:null, explain:'', marks:1});
  if(kind==='short') return Object.assign(b,{q:'', answer:'', marks:2});
  if(kind==='creative') return Object.assign(b,{stem:'', parts:QP_LABELS.map((l,i)=>({q:'', a:'', marks:QP_PART_MARKS[i]})), marks:10});
  return Object.assign(b,{q:'', answer:'', marks:0});          // note: q = শিরোনাম, answer = নোটের মূল লেখা
}
function qpMarksOf(it){
  if(!it || it.kind==='note') return 0;
  if(it.kind==='creative') return (it.parts||[]).reduce((s,p)=>s+(Number(p.marks)||0),0);
  return Number(it.marks)||0;
}
function qpSumMarks(items){ return (items||[]).reduce((s,it)=>s+qpMarksOf(it),0); }
/* যাচাই: [{level:'error'|'warn', id, text}] — error থাকলে প্রিন্ট/ডাউনলোড আটকায় */
function qpValidate(items, full, opts){
  const out=[], add=(level,id,text)=>out.push({level,id,text}); items=items||[];
  const nonNote=items.filter(i=>i.kind!=='note');
  if(!items.length){ add('error',null,'কোনো প্রশ্ন বা নোট নেই।'); return out; }
  const seen={};
  items.forEach((it,idx)=>{
    const n=idx+1, tag=`প্রশ্ন ${qpN(n)}: `;
    if(it.unsure) add('warn',it.id,tag+'AI নিশ্চিত ছিল না — নিজে যাচাই করে সম্পাদনা/অনুমোদন করো।');
    if(it.kind==='mcq'){
      const o=Array.isArray(it.options)?it.options:[];
      if(!qpNorm(it.q)) add('error',it.id,tag+'প্রশ্ন খালি।');
      if(o.length!==4 || o.some(x=>!qpNorm(x))) add('error',it.id,tag+'চারটা অপশনই লিখতে হবে।');
      else if(new Set(o.map(qpNorm)).size!==4) add('error',it.id,tag+'দুটি অপশন একই — একাধিক সঠিক উত্তর হতে পারে।');
      if(!(Number.isInteger(it.ans) && it.ans>=0 && it.ans<o.length)) add('error',it.id,tag+'সঠিক উত্তর বাছা হয়নি (বা অপশনে নেই)।');
      if(!(qpMarksOf(it)>0)) add('error',it.id,tag+'নম্বর ০।');
    } else if(it.kind==='short'){
      if(!qpNorm(it.q)) add('error',it.id,tag+'প্রশ্ন খালি।');
      if(!(qpMarksOf(it)>0)) add('error',it.id,tag+'নম্বর ০।');
      if(!qpNorm(it.answer)) add('warn',it.id,tag+'নমুনা উত্তর নেই।');
    } else if(it.kind==='creative'){
      const p=Array.isArray(it.parts)?it.parts:[];
      if(!qpNorm(it.stem)) add('error',it.id,tag+'উদ্দীপক খালি।');
      if(p.length!==4 || p.some(x=>!qpNorm(x.q))) add('error',it.id,tag+'ক/খ/গ/ঘ চারটা উপপ্রশ্নই লিখতে হবে।');
      if(p.some(x=>!(Number(x.marks)>0))) add('error',it.id,tag+'কোনো উপপ্রশ্নের নম্বর ০।');
      if(p.some(x=>!qpNorm(x.a))) add('warn',it.id,tag+'কিছু উপপ্রশ্নের নমুনা উত্তর নেই।');
    } else if(it.kind==='note'){
      if(!qpNorm(it.answer)) add('error',it.id,'নোটের লেখা খালি।');
    }
    const key=qpNorm(it.kind==='creative'?it.stem:it.q); if(key){ if(seen[key]) add('warn',it.id,tag+'আগের একটা প্রশ্নের সঙ্গে হুবহু মিলে যাচ্ছে।'); seen[key]=1; }
  });
  if(nonNote.length){
    const sum=qpSumMarks(nonNote), f=Number(full)||0;
    if(!(f>0)) add('error',null,'পূর্ণমান দেওয়া হয়নি।');
    else if(sum!==f) add('error',null,`প্রশ্নের নম্বরের যোগফল ${qpN(sum)}, কিন্তু পূর্ণমান ${qpN(f)} — মেলেনি।`);
  }
  return out;
}
function qpReady(items, full){ const v=qpValidate(items, full); const errs=v.filter(x=>x.level==='error').length, un=(items||[]).filter(i=>!i.approved).length; return {ok: !errs && !un && (items||[]).length>0, errors:errs, unapproved:un, issues:v}; }

/* AI-র উত্তর (JSON) → আইটেম। কাটা পড়া উত্তর থেকেও সম্পূর্ণ অংশগুলো বাঁচায়। */
function qpExtractJson(text){
  let t=String(text||'').trim().replace(/^```(?:json)?\s*/i,'').replace(/```\s*$/,'');
  const a=t.search(/[\[{]/); if(a<0) return null; const open=t[a], close=open==='['?']':'}';
  const tryParse=s=>{ try{ return JSON.parse(s); }catch(e){ return undefined; } };
  const b=t.lastIndexOf(close); if(b>a){ const v=tryParse(t.slice(a,b+1)); if(v!==undefined) return v; }
  if(open==='['){ let end=t.length; for(let k=0;k<30;k++){ end=t.lastIndexOf('}',end-1); if(end<=a) break; const v=tryParse(t.slice(a,end+1)+']'); if(Array.isArray(v)) return v; } }
  return null;
}
function qpAnsIndex(v, n){
  if(typeof v==='number' && Number.isInteger(v) && v>=0 && v<n) return v;
  const s=String(v==null?'':v).trim(); if(/^[0-3]$/.test(s)) return +s;
  const i=['ক','খ','গ','ঘ'].indexOf(s); if(i>=0) return i; const j='abcd'.indexOf(s.toLowerCase()); if(s.length===1 && j>=0) return j;
  return null;
}
function qpParseAi(text, kind){
  const raw=qpExtractJson(text); if(raw==null) return {items:[], dropped:0, bad:true};
  const arr=Array.isArray(raw)?raw:[raw], items=[]; let dropped=0;
  arr.forEach(r=>{
    if(!r || typeof r!=='object'){ dropped++; return; }
    const it=qpNewItem(kind); it.unsure=r.unsure===true;
    if(kind==='mcq'){ it.q=String(r.q||'').trim(); it.options=(Array.isArray(r.options)?r.options:[]).slice(0,4).map(x=>String(x==null?'':x).trim()); while(it.options.length<4) it.options.push('');
      it.ans=qpAnsIndex(r.ans, 4); it.explain=String(r.explain||'').trim(); if(!it.q) { dropped++; return; } }
    else if(kind==='short'){ it.q=String(r.q||'').trim(); it.answer=String(r.answer||'').trim(); const m=Number(r.marks); if(m>0&&m<=10) it.marks=Math.round(m); if(!it.q){ dropped++; return; } }
    else if(kind==='creative'){ it.stem=String(r.stem||'').trim(); const ps=Array.isArray(r.parts)?r.parts:[]; it.parts=QP_LABELS.map((l,i)=>({q:String((ps[i]||{}).q||'').trim(), a:String((ps[i]||{}).a||'').trim(), marks:QP_PART_MARKS[i]})); it.marks=10; if(!it.stem){ dropped++; return; } }
    else { it.q=String(r.title||r.q||'').trim(); const parts=[]; if(r.objective) parts.push('🎯 শেখার উদ্দেশ্য: '+String(r.objective).trim()); if(r.body) parts.push(String(r.body).trim()); it.answer=parts.join('\n\n'); if(!it.answer){ dropped++; return; } }
    items.push(it);
  });
  return {items, dropped, bad:false};
}
/* প্রম্পট তৈরি। নাম/ফোন নেই; সোর্স লেখা থেকে ফোন নম্বর ছেঁটে ফেলা হয়। */
function qpPrompt(meta, kind, n, existing){
  const lang=QP_LANGS[meta.lang]||'বাংলা', cls=meta.cls?`${meta.cls} শ্রেণি`:'', board=QP_BOARDS[meta.board]||'', lvl=QP_LEVELS[meta.level]||'মাঝারি', diff=QP_DIFFS[meta.diff]||'মাঝারি';
  const system=['তুমি বাংলাদেশের একজন অভিজ্ঞ শিক্ষক-সহকারী। শুধু বৈধ JSON ফেরত দাও — কোনো ভূমিকা, ব্যাখ্যা, মার্কডাউন বা ``` চিহ্ন নয়।',
    'নিয়ম: (১) যা নির্ভুলভাবে জানো না তা বানিয়ে লিখো না; কোনো আইটেমের তথ্য নিয়ে সামান্য সন্দেহ থাকলে সেই আইটেমে "unsure":true দাও। (২) ভাষা: '+lang+'। (৩) কোনো মানুষের নাম বা ফোন নম্বর লিখো না। (৪) শিক্ষার্থীর স্তর ও কঠিনতা অনুযায়ী লেখো। (৫) বাংলা সংখ্যা বা ইংরেজি সংখ্যা — প্রশ্নের ভাষা অনুযায়ী ঠিক রাখো।'].join('\n');
  const head=`${board} ${cls} | বিষয়: ${meta.subject||''} | অধ্যায়/টপিক: ${meta.chapter||''} | শিক্ষার্থীর স্তর: ${lvl} | কঠিনতা: ${diff}`.replace(/\s+/g,' ').trim();
  const src=meta.source?`\nশুধু নিচের পাঠ্যাংশের ভিত্তিতে লেখো (বাইরের তথ্য যোগ কোরো না):\n<<<\n${(typeof aiScrubPhones==='function'?aiScrubPhones(meta.source):meta.source).slice(0,6000)}\n>>>`:'';
  const avoid=(existing&&existing.length)?`\nএই প্রশ্নগুলো আগেই আছে, আবার দিও না:\n${existing.slice(0,12).map(s=>'- '+String(s).slice(0,70)).join('\n')}`:'';
  let spec;
  if(kind==='mcq') spec=`${n}টা বহুনির্বাচনি প্রশ্ন। ফরম্যাট: [{"q":"প্রশ্ন","options":["অপশন১","অপশন২","অপশন৩","অপশন৪"],"ans":0,"explain":"১ বাক্যের ব্যাখ্যা","unsure":false}] — ans হলো ০ থেকে ৩ (সঠিক অপশনের সূচক); ঠিক একটাই সঠিক উত্তর হবে, চারটা অপশন ভিন্ন হবে।`;
  else if(kind==='short') spec=`${n}টা সংক্ষিপ্ত প্রশ্ন (প্রতিটা ২ নম্বরের)। ফরম্যাট: [{"q":"প্রশ্ন","answer":"সংক্ষিপ্ত নমুনা উত্তর","marks":2,"unsure":false}]`;
  else if(kind==='creative') spec=`${n}টা সৃজনশীল প্রশ্ন। ফরম্যাট: [{"stem":"উদ্দীপক (৩-৫ বাক্য)","parts":[{"q":"ক) জ্ঞানমূলক (১)","a":"নমুনা উত্তর"},{"q":"খ) অনুধাবনমূলক (২)","a":""},{"q":"গ) প্রয়োগমূলক (৩)","a":""},{"q":"ঘ) উচ্চতর দক্ষতা (৪)","a":""}],"unsure":false}] — parts-এ ঠিক ৪টা।`;
  else spec=`এই অধ্যায়ের একটা সহজ নোট। ফরম্যাট: {"title":"শিরোনাম","objective":"শেখার উদ্দেশ্য (১-২ বাক্য)","body":"সংজ্ঞা, সহজ ব্যাখ্যা, উদাহরণ, সূত্র (থাকলে), সাধারণ ভুল — ছোট ছোট অনুচ্ছেদে, প্রতিটা অংশের আগে শিরোনাম","unsure":false}`;
  return {system, user:`${head}${src}${avoid}\n\nতৈরি করো: ${spec}`};
}

/* ---------- প্রিন্ট/ডাউনলোড HTML ---------- */
function qpPartLine(p,i){ return `${QP_LABELS[i]}) ${p.q.replace(/^[কখগঘ]\)\s*/,'')}`; }
/* ছাত্রের প্রশ্নপত্র — এতে কখনো উত্তর/ব্যাখ্যা থাকে না */
function qpPaperBody(set){
  const m=set.meta||{}, items=set.items||[], E=qpEsc;
  if(m.type==='note'){
    return `<h1>${E(set.title||'নোট')}</h1><div class="qp-sub">${E([m.cls?m.cls+' শ্রেণি':'', m.subject, m.chapter].filter(Boolean).join(' · '))}</div>`+items.filter(i=>i.kind==='note').map(i=>`<h2>${E(i.q)}</h2><div class="qp-note">${E(i.answer).replace(/\n/g,'<br>')}</div>`).join('');
  }
  const parts=[], mcq=items.filter(i=>i.kind==='mcq'), sh=items.filter(i=>i.kind==='short'), cr=items.filter(i=>i.kind==='creative'); let n=0;
  const head=`<div class="qp-head"><h1>${E(set.title||'প্রশ্নপত্র')}</h1><div class="qp-sub">${E([m.cls?m.cls+' শ্রেণি':'', m.subject, m.chapter].filter(Boolean).join(' · '))}</div><div class="qp-meta"><span>সময়: ${qpN(m.minutes||0)} মিনিট</span><span>পূর্ণমান: ${qpN(set.full||qpSumMarks(items))}</span></div></div><div class="qp-who">নাম: ____________________ &nbsp; রোল: ______ &nbsp; তারিখ: __________</div>`;
  parts.push(head);
  if(mcq.length){ parts.push(`<h2>ক-বিভাগ: বহুনির্বাচনি <small>(প্রতিটি ${qpN(qpMarksOf(mcq[0]))} নম্বর)</small></h2>`);
    mcq.forEach(it=>{ n++; parts.push(`<div class="qp-q"><div class="qp-row"><b>${qpN(n)}.</b> <span>${E(it.q)}</span></div><div class="qp-opts">${it.options.map((o,i)=>`<span>${QP_LABELS[i]}. ${E(o)}</span>`).join('')}</div></div>`); }); }
  if(sh.length){ parts.push(`<h2>খ-বিভাগ: সংক্ষিপ্ত প্রশ্ন</h2>`);
    sh.forEach(it=>{ n++; parts.push(`<div class="qp-q"><div class="qp-row"><b>${qpN(n)}.</b> <span>${E(it.q)}</span><i class="qp-mk">${qpN(qpMarksOf(it))}</i></div></div>`); }); }
  if(cr.length){ parts.push(`<h2>গ-বিভাগ: সৃজনশীল প্রশ্ন</h2>`);
    cr.forEach(it=>{ n++; parts.push(`<div class="qp-q"><div class="qp-row"><b>${qpN(n)}.</b> <span class="qp-stem">${E(it.stem).replace(/\n/g,'<br>')}</span></div>${it.parts.map((p,i)=>`<div class="qp-row qp-part"><span>${E(qpPartLine(p,i))}</span><i class="qp-mk">${qpN(p.marks)}</i></div>`).join('')}</div>`); }); }
  return parts.join('');
}
/* শিক্ষকের উত্তরমালা — আলাদা পাতা/ফাইল */
function qpKeyBody(set){
  const items=(set.items||[]).filter(i=>i.kind!=='note'), E=qpEsc, m=set.meta||{}; let n=0;
  const rows=[];
  const order=['mcq','short','creative'];
  order.forEach(k=>items.filter(i=>i.kind===k).forEach(it=>{ n++;
    if(k==='mcq') rows.push(`<div class="qp-q"><div class="qp-row"><b>${qpN(n)}.</b> <span>উত্তর: <b>${QP_LABELS[it.ans]||'?'}</b> — ${E(it.options[it.ans]||'')}</span></div>${it.explain?`<div class="qp-ex">ব্যাখ্যা: ${E(it.explain)}</div>`:''}</div>`);
    else if(k==='short') rows.push(`<div class="qp-q"><div class="qp-row"><b>${qpN(n)}.</b> <span>${E(it.answer||'—')}</span><i class="qp-mk">${qpN(qpMarksOf(it))}</i></div></div>`);
    else rows.push(`<div class="qp-q"><div class="qp-row"><b>${qpN(n)}.</b> <span>সৃজনশীল — নমুনা উত্তর ও নম্বরবণ্টন</span></div>${it.parts.map((p,i)=>`<div class="qp-row qp-part"><span><b>${QP_LABELS[i]}</b> (${QP_PART_KIND[i]}) ${E(p.a||'—')}</span><i class="qp-mk">${qpN(p.marks)}</i></div>`).join('')}</div>`);
  }));
  return `<div class="qp-head"><h1>উত্তরমালা — ${E(set.title||'')}</h1><div class="qp-sub">${E([m.cls?m.cls+' শ্রেণি':'', m.subject, m.chapter].filter(Boolean).join(' · '))} · <b>শুধু শিক্ষকের জন্য</b></div></div>`+rows.join('');
}
const QP_CSS = `@page{size:A4;margin:14mm}*{box-sizing:border-box}body{font-family:'Hind Siliguri','Noto Sans Bengali','Kalpurush','SolaimanLipi',sans-serif;color:#111;line-height:1.55;font-size:13.5px;margin:0}
h1{font-size:20px;margin:0;text-align:center}h2{font-size:15px;margin:16px 0 6px;border-bottom:1.5px solid #111;padding-bottom:3px}h2 small{font-weight:400;font-size:12px}
.qp-sub{text-align:center;color:#444;font-size:12.5px;margin-top:2px}.qp-meta{display:flex;justify-content:space-between;margin-top:8px;font-weight:600}.qp-who{margin:10px 0 4px;font-size:12.5px}
.qp-q{margin:7px 0;page-break-inside:avoid;break-inside:avoid}.qp-row{display:flex;gap:6px;align-items:flex-start}.qp-row>span{flex:1}.qp-mk{font-style:normal;font-weight:700;min-width:22px;text-align:right}
.qp-opts{display:grid;grid-template-columns:1fr 1fr;gap:2px 14px;margin:3px 0 0 20px}.qp-part{margin-left:20px;margin-top:3px}.qp-stem{font-style:italic}.qp-ex{margin:2px 0 0 20px;color:#333;font-size:12.5px}.qp-note{white-space:normal;margin:4px 0 10px}`;
function qpFullDoc(inner, title){ return `<!DOCTYPE html><html lang="bn"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${qpEsc(title||'প্রশ্নপত্র')}</title><style>${QP_CSS}body{padding:14px;max-width:820px;margin:0 auto}@media print{body{padding:0;max-width:none}}</style></head><body>${inner}</body></html>`; }

/* ---------- screen ---------- */
let qp={meta:null, items:[], title:'', full:0, editing:null, busy:false, msg:'', setId:null, gen:null, planDone:0};
function qpFreshMeta(){ return {cls:'', board:'nctb', subject:'', chapter:'', lang:'bn', level:'mid', diff:'mid', type:'mcq', mcqN:5, shortN:0, creN:0, minutes:30, source:''}; }
function qpGetBank(){ const b=lsGet('tr_qbank',[]); return Array.isArray(b)?b:[]; }
function qpOpen(){ if(!qp.meta) qp.meta=qpFreshMeta(); showKhataModal('📝 নোট ও প্রশ্নপত্র','<div id="qpBox"></div>'); qpRender(); }
function qpSet(k,v){ qp.meta[k]=v; if(k==='type'){ const t=v; qp.meta.mcqN=(t==='mcq'||t==='model')?(qp.meta.mcqN||5):0; qp.meta.shortN=(t==='short'||t==='model')?(qp.meta.shortN||3):0; qp.meta.creN=(t==='creative'||t==='model')?(qp.meta.creN||1):0; qpRender(); } }
function qpSetNum(k,v){ qp.meta[k]=Math.max(0,Math.min(30,parseInt(v,10)||0)); }
function qpSetTitle(v){ qp.title=v; } function qpSetFull(v){ qp.full=Math.max(0,Number(v)||0); qpRender(); }
function qpOpts(map,sel){ return Object.keys(map).map(k=>`<option value="${k}"${k===sel?' selected':''}>${qpEsc(map[k])}</option>`).join(''); }
function qpSubjects(){ const s=new Set(); try{ const pd=getProgressData(); Object.keys(pd).forEach(n=>Object.keys(pd[n]||{}).forEach(x=>s.add(x))); }catch(e){} return [...s]; }
function qpSetupHtml(){
  const m=qp.meta, f=(l,h)=>`<label class="sm-field-label">${l}</label>${h}`, inp=(k,ph,list)=>`<input class="sm-field-input" value="${qpEsc(m[k]||'')}" placeholder="${ph}" ${list?`list="${list}"`:''} onchange="qpSet('${k}',this.value)">`;
  return `<details class="qp-setup" ${qp.items.length?'':'open'}><summary class="settings-btn" style="text-align:left;">⚙️ সেটআপ (শ্রেণি · বিষয় · অধ্যায় · ধরন)</summary>
   <datalist id="qpSubj">${qpSubjects().map(s=>`<option value="${qpEsc(s)}">`).join('')}</datalist>
   <div class="qp-grid">${f('শ্রেণি',inp('cls','যেমন ৮'))}${f('বোর্ড/কারিকুলাম',`<select class="sm-field-input" onchange="qpSet('board',this.value)">${qpOpts(QP_BOARDS,m.board)}</select>`)}
   ${f('বিষয়',inp('subject','যেমন গণিত','qpSubj'))}${f('অধ্যায়/টপিক',inp('chapter','যেমন অনুপাত ও শতকরা'))}
   ${f('ভাষা',`<select class="sm-field-input" onchange="qpSet('lang',this.value)">${qpOpts(QP_LANGS,m.lang)}</select>`)}${f('শিক্ষার্থীর স্তর',`<select class="sm-field-input" onchange="qpSet('level',this.value)">${qpOpts(QP_LEVELS,m.level)}</select>`)}
   ${f('কঠিনতা',`<select class="sm-field-input" onchange="qpSet('diff',this.value)">${qpOpts(QP_DIFFS,m.diff)}</select>`)}${f('আউটপুট',`<select class="sm-field-input" onchange="qpSet('type',this.value)">${qpOpts(QP_TYPES,m.type)}</select>`)}
   ${m.mcqN||m.type==='mcq'||m.type==='model'?f('MCQ সংখ্যা',`<input type="number" class="sm-field-input" min="0" max="30" value="${m.mcqN}" onchange="qpSetNum('mcqN',this.value)">`):''}
   ${m.type==='short'||m.type==='model'?f('সংক্ষিপ্ত প্রশ্ন সংখ্যা',`<input type="number" class="sm-field-input" min="0" max="30" value="${m.shortN}" onchange="qpSetNum('shortN',this.value)">`):''}
   ${m.type==='creative'||m.type==='model'?f('সৃজনশীল সংখ্যা',`<input type="number" class="sm-field-input" min="0" max="10" value="${m.creN}" onchange="qpSetNum('creN',this.value)">`):''}
   ${m.type!=='note'?f('সময় (মিনিট)',`<input type="number" class="sm-field-input" min="0" value="${m.minutes}" onchange="qpSetNum('minutes',this.value)">`):''}</div>
   ${f('বইয়ের পাঠ্যাংশ / নিজের বিষয়বস্তু (ঐচ্ছিক — দিলে AI শুধু এখান থেকে লিখবে)',`<textarea class="sm-field-input" rows="3" placeholder="এখানে পেস্ট করো…" onchange="qpSet('source',this.value)">${qpEsc(m.source||'')}</textarea>`)}
   <div class="qp-actions"><button type="button" class="modal-btn primary" onclick="qpGenerate()" ${qp.busy?'disabled':''}>🤖 AI দিয়ে খসড়া বানাও</button></div>
   <div class="qp-note-small">AI-কে কোনো ছাত্রের নাম/ফোন পাঠানো হয় না। নেট বা AI পাসকোড না থাকলে নিচ থেকে হাতে প্রশ্ন যোগ করো — বাকি সব (যাচাই, প্রিন্ট) একই কাজ করবে।</div></details>`;
}
function qpItemHtml(it, idx){
  const E=qpEsc, iss=qp.issues.filter(x=>x.id===it.id), bad=iss.some(x=>x.level==='error');
  if(qp.editing===it.id) return `<div class="qp-card editing">${qpEditHtml(it)}</div>`;
  let body='';
  if(it.kind==='mcq') body=`<div class="qp-qt">${E(it.q)}</div><div class="qp-op">${it.options.map((o,i)=>`<div class="${it.ans===i?'ok':''}">${QP_LABELS[i]}. ${E(o)}${it.ans===i?' ✓':''}</div>`).join('')}</div>${it.explain?`<div class="qp-ex">💡 ${E(it.explain)}</div>`:''}`;
  else if(it.kind==='short') body=`<div class="qp-qt">${E(it.q)}</div><div class="qp-ex">নমুনা: ${E(it.answer||'—')}</div>`;
  else if(it.kind==='creative') body=`<div class="qp-qt qp-stem">${E(it.stem)}</div>${it.parts.map((p,i)=>`<div class="qp-ex"><b>${QP_LABELS[i]}</b> ${E(p.q)} <i>(${qpN(p.marks)})</i></div>`).join('')}`;
  else body=`<div class="qp-qt"><b>${E(it.q)}</b></div><div class="qp-ex" style="white-space:pre-wrap;">${E(it.answer)}</div>`;
  return `<div class="qp-card${bad?' bad':''}${it.approved?' appr':''}"><div class="qp-ch"><b>${qpN(idx+1)}. ${QP_KIND_LABEL[it.kind]}</b>${it.kind==='note'?'':`<span>${qpN(qpMarksOf(it))} নম্বর</span>`}${it.unsure?'<span class="qp-uns">⚠ অনিশ্চিত</span>':''}${it.approved?'<span class="qp-ap">✔ অনুমোদিত</span>':''}</div>${body}
   ${iss.map(x=>`<div class="qp-iss ${x.level}">${x.level==='error'?'⛔':'⚠️'} ${E(x.text)}</div>`).join('')}
   <div class="qp-btns"><button type="button" onclick="qpEdit('${it.id}')">✎ সম্পাদনা</button><button type="button" onclick="qpApprove('${it.id}')">${it.approved?'↩ অনুমোদন তুলে নাও':'✔ অনুমোদন'}</button><button type="button" onclick="qpRegen('${it.id}')">↻ আবার</button><button type="button" onclick="qpDel('${it.id}')">🗑</button></div></div>`;
}
function qpEditHtml(it){
  const E=qpEsc, ta=(id,v,r)=>`<textarea class="sm-field-input" id="${id}" rows="${r||2}">${E(v||'')}</textarea>`, num=(id,v)=>`<input type="number" min="0" class="sm-field-input" id="${id}" value="${v}" style="width:80px;">`;
  let h='';
  if(it.kind==='mcq') h=`<label class="sm-field-label">প্রশ্ন</label>${ta('qe_q',it.q)}${it.options.map((o,i)=>`<label class="sm-field-label">অপশন ${QP_LABELS[i]}</label><input class="sm-field-input" id="qe_o${i}" value="${E(o)}">`).join('')}
    <label class="sm-field-label">সঠিক উত্তর</label><select class="sm-field-input" id="qe_ans"><option value="">— বাছো —</option>${QP_LABELS.map((l,i)=>`<option value="${i}"${it.ans===i?' selected':''}>${l}</option>`).join('')}</select><label class="sm-field-label">ব্যাখ্যা</label>${ta('qe_exp',it.explain)}<label class="sm-field-label">নম্বর</label>${num('qe_marks',it.marks)}`;
  else if(it.kind==='short') h=`<label class="sm-field-label">প্রশ্ন</label>${ta('qe_q',it.q)}<label class="sm-field-label">নমুনা উত্তর</label>${ta('qe_ans_txt',it.answer,3)}<label class="sm-field-label">নম্বর</label>${num('qe_marks',it.marks)}`;
  else if(it.kind==='creative') h=`<label class="sm-field-label">উদ্দীপক</label>${ta('qe_stem',it.stem,4)}${it.parts.map((p,i)=>`<label class="sm-field-label">${QP_LABELS[i]}) ${QP_PART_KIND[i]}</label>${ta('qe_pq'+i,p.q)}${ta('qe_pa'+i,p.a)}<div>নম্বর ${num('qe_pm'+i,p.marks)}</div>`).join('')}`;
  else h=`<label class="sm-field-label">শিরোনাম</label><input class="sm-field-input" id="qe_q" value="${E(it.q)}"><label class="sm-field-label">নোট</label>${ta('qe_ans_txt',it.answer,10)}`;
  return h+`<div class="qp-btns"><button type="button" onclick="qpEditSave('${it.id}')">💾 ঠিক আছে</button><button type="button" onclick="qpEditCancel()">বাতিল</button></div>`;
}
const qpV=id=>{ const e=document.getElementById(id); return e?e.value:''; };
function qpEdit(id){ qp.editing=id; qpRender(); }
function qpEditCancel(){ qp.editing=null; qpRender(); }
function qpEditSave(id){
  const it=qp.items.find(x=>x.id===id); if(!it) return;
  if(it.kind==='mcq'){ it.q=qpV('qe_q').trim(); it.options=[0,1,2,3].map(i=>qpV('qe_o'+i).trim()); const a=qpV('qe_ans'); it.ans=a===''?null:+a; it.explain=qpV('qe_exp').trim(); it.marks=Number(qpV('qe_marks'))||0; }
  else if(it.kind==='short'){ it.q=qpV('qe_q').trim(); it.answer=qpV('qe_ans_txt').trim(); it.marks=Number(qpV('qe_marks'))||0; }
  else if(it.kind==='creative'){ it.stem=qpV('qe_stem').trim(); it.parts=[0,1,2,3].map(i=>({q:qpV('qe_pq'+i).trim(), a:qpV('qe_pa'+i).trim(), marks:Number(qpV('qe_pm'+i))||0})); it.marks=qpMarksOf(it); }
  else { it.q=qpV('qe_q').trim(); it.answer=qpV('qe_ans_txt').trim(); }
  it.approved=false; it.unsure=false; qp.editing=null; qpRender();      // সম্পাদনার পর আবার অনুমোদন লাগে
}
function qpAdd(kind){ qp.items.push(qpNewItem(kind)); qp.editing=qp.items[qp.items.length-1].id; qpRender(); }
function qpDel(id){ const i=qp.items.findIndex(x=>x.id===id); if(i<0) return; const [rm]=qp.items.splice(i,1); qpRender(); showUndoToast('প্রশ্ন বাদ দেওয়া হয়েছে', ()=>{ qp.items.splice(Math.min(i,qp.items.length),0,rm); qpRender(); }); }
function qpApprove(id){ const it=qp.items.find(x=>x.id===id); if(!it) return; it.approved=!it.approved; qpRender(); }
function qpApproveAll(){ qp.items.forEach(i=>{ i.approved=true; }); qpRender(); showSuccessToast('সব অনুমোদিত — এবার প্রিন্ট/ডাউনলোড করা যাবে (যাচাইয়ে ভুল না থাকলে)।'); }
function qpFixFull(){ qp.full=qpSumMarks(qp.items); qpRender(); }
function qpTotalsHtml(){
  const nn=qp.items.filter(i=>i.kind!=='note'), sum=qpSumMarks(nn), ok=!nn.length||sum===(Number(qp.full)||0);
  return `<div class="qp-tot ${ok?'ok':'bad'}"><span>নম্বরের যোগফল: <b>${qpN(sum)}</b></span><span>পূর্ণমান: <input type="number" min="0" class="sm-field-input" style="width:80px;display:inline-block;padding:4px 8px;" value="${qp.full||''}" onchange="qpSetFull(this.value)"></span>${ok?'':`<button type="button" class="pct-chip" onclick="qpFixFull()">পূর্ণমান = ${qpN(sum)} করো</button>`}</div>`;
}
function qpRender(){
  const box=document.getElementById('qpBox'); if(!box) return;
  qp.issues=qpValidate(qp.items, qp.full); const rd=qpReady(qp.items, qp.full), isNote=qp.meta.type==='note';
  const lib=qpGetBank();
  box.innerHTML=`${qpSetupHtml()}
  <div class="qp-msg" id="qpMsg">${qp.busy?'<span class="spin"></span> ':''}${qpEsc(qp.msg||'')}</div>
  <div class="qp-add"><span>হাতে যোগ:</span>${['mcq','short','creative','note'].map(k=>`<button type="button" class="pct-chip" onclick="qpAdd('${k}')">+ ${QP_KIND_LABEL[k]}</button>`).join('')}</div>
  ${qp.items.length?`<input class="sm-field-input" style="margin:8px 0;" placeholder="শিরোনাম (যেমন: ৮ম শ্রেণি গণিত — মাসিক পরীক্ষা)" value="${qpEsc(qp.title)}" onchange="qpSetTitle(this.value)">${isNote?'':qpTotalsHtml()}
  <div class="qp-list">${qp.items.map((it,i)=>qpItemHtml(it,i)).join('')}</div>
  <div class="qp-gate ${rd.ok?'ok':'bad'}">${rd.ok?'✅ সব যাচাই পাস ও অনুমোদিত — প্রিন্ট করা যাবে।':`⛔ প্রিন্টের আগে: ${rd.errors?qpN(rd.errors)+'টা ভুল ঠিক করো':''}${rd.errors&&rd.unapproved?' · ':''}${rd.unapproved?qpN(rd.unapproved)+'টা আইটেম অনুমোদন করো':''}`}</div>
  <div class="qp-actions"><button type="button" class="modal-btn secondary" onclick="qpApproveAll()">✔ সব অনুমোদন</button><button type="button" class="modal-btn secondary" onclick="qpSave()">💾 সংরক্ষণ</button></div>
  <div class="qp-actions"><button type="button" class="modal-btn primary" onclick="qpPrint('paper')">🖨️ ${isNote?'নোট':'প্রশ্নপত্র'} প্রিন্ট</button>${isNote?'':'<button type="button" class="modal-btn primary" onclick="qpPrint(\'key\')">🔑 উত্তরমালা প্রিন্ট</button>'}</div>
  <div class="qp-actions"><button type="button" class="modal-btn secondary" onclick="qpDownload('paper')">⬇️ HTML ফাইল</button>${isNote?'':'<button type="button" class="modal-btn secondary" onclick="qpDownload(\'key\')">⬇️ উত্তরমালা HTML</button>'}</div>`:`<div class="ins-empty">এখনো কোনো প্রশ্ন নেই — উপরে সেটআপ করে AI-কে বলো, অথবা হাতে যোগ করো।</div>`}
  ${lib.length?`<div class="settings-section-title" style="margin-top:14px;">📚 সংরক্ষিত (${qpN(lib.length)})</div>${lib.slice().reverse().map(s=>`<div class="makeup-row"><span>${qpEsc(s.title||'নামহীন')} <small style="color:var(--muted)">· ${qpEsc((s.meta||{}).subject||'')} ${s.approved?'✔':''}</small></span><span><button class="makeup-done" onclick="qpLoad('${s.id}')">খোলো</button> <button class="makeup-done" onclick="qpDup('${s.id}')">কপি</button> <button class="makeup-done" onclick="qpRemoveSet('${s.id}')">🗑</button></span></div>`).join('')}`:''}`;
}
function qpMsg(t,busy){ qp.msg=t; qp.busy=!!busy; const el=document.getElementById('qpMsg'); if(el) el.innerHTML=(busy?'<span class="spin"></span> ':'')+qpEsc(t); }
async function qpAiBatch(kind, n){
  const existing=qp.items.filter(i=>i.kind===kind).map(i=>kind==='creative'?i.stem:i.q), p=qpPrompt(qp.meta, kind, n, existing);
  const r=await aiCall({system:p.system, messages:[{role:'user',content:p.user}], max_tokens:900});
  if(!r.ok) return {error:r.error};
  const out=aiBlocks(r.data.content).text, parsed=qpParseAi(out, kind);
  if(parsed.bad || !parsed.items.length) return {error:'bad_output'};
  qp.gen={model:'claude-haiku-5-5', at:Date.now()};
  return {items:parsed.items, dropped:parsed.dropped};
}
async function qpGenerate(){
  const m=qp.meta; if(qp.busy) return;
  if(!m.subject.trim() || !m.chapter.trim()){ showWarningToast('বিষয় আর অধ্যায়/টপিক লেখো।'); return; }
  if(!lsGet('tr_aiPass','')){ showWarningToast('AI-র পাসকোড নেই — সেটিংসে দাও, অথবা হাতে প্রশ্ন যোগ করো।'); return; }
  const plan=[]; if(m.type==='note') plan.push(['note',1]); else { if(m.mcqN>0) plan.push(['mcq',m.mcqN]); if(m.shortN>0) plan.push(['short',m.shortN]); if(m.creN>0) plan.push(['creative',m.creN]); }
  if(!plan.length){ showWarningToast('কোন ধরনের কতগুলো প্রশ্ন লাগবে তা দাও।'); return; }
  let added=0, fail=null, want=plan.reduce((s,x)=>s+x[1],0);
  for(const [kind,n] of plan){
    let have=qp.items.filter(i=>i.kind===kind).length, goal=have+n, guard=0;
    while(qp.items.filter(i=>i.kind===kind).length<goal && guard++<12){
      const need=Math.min(QP_BATCH[kind], goal-qp.items.filter(i=>i.kind===kind).length);
      qpMsg(`⏳ ${QP_KIND_LABEL[kind]} তৈরি হচ্ছে… (${qpN(added)}/${qpN(want)})`, true);
      const r=await qpAiBatch(kind, need);
      if(r.error){ fail=r.error; break; }
      r.items.slice(0,need).forEach(it=>{ qp.items.push(it); added++; });
    }
    if(fail) break;
  }
  if(qp.items.some(i=>i.kind!=='note') && !qp.full) qp.full=qpSumMarks(qp.items);
  qpMsg(fail?`⚠️ ${qpN(added)}টা তৈরি হয়েছে। থেমেছে: ${fail==='bad_output'?'AI-র উত্তর পড়া গেল না — আবার চেষ্টা করো':aiErrText(fail)}`:`✅ ${qpN(added)}টা খসড়া তৈরি — এবার প্রতিটা পড়ে সম্পাদনা/অনুমোদন করো।`, false);
  qpRender(); qpMsg(qp.msg,false);
}
async function qpRegen(id){
  const i=qp.items.findIndex(x=>x.id===id); if(i<0) return; const old=qp.items[i];
  if(!lsGet('tr_aiPass','')){ showWarningToast('AI-র পাসকোড নেই — হাতে সম্পাদনা করো।'); return; }
  qpMsg('⏳ আবার তৈরি হচ্ছে…', true);
  const r=await qpAiBatch(old.kind, 1);
  if(r.error){ qpMsg('⚠️ '+(r.error==='bad_output'?'AI-র উত্তর পড়া গেল না':aiErrText(r.error)), false); return; }
  const fresh=r.items[0]; if(old.kind==='mcq'||old.kind==='short') fresh.marks=old.marks; fresh.id=old.id; qp.items[i]=fresh; qpMsg('✅ নতুন প্রশ্ন বসেছে — আবার পড়ে অনুমোদন করো।', false); qpRender();
}
function qpCurrentSet(){ return {id:qp.setId||qpUid(), title:qp.title||'নামহীন', meta:JSON.parse(JSON.stringify(qp.meta)), items:JSON.parse(JSON.stringify(qp.items)), full:qp.full||qpSumMarks(qp.items), approved:qp.items.length>0&&qp.items.every(i=>i.approved), gen:qp.gen||null, updatedAt:Date.now()}; }
function qpSave(){
  if(!qp.items.length){ showWarningToast('সংরক্ষণ করার মতো কিছু নেই।'); return; }
  const s=qpCurrentSet(), bank=qpGetBank(), i=bank.findIndex(x=>x.id===s.id); if(i>=0) bank[i]=Object.assign(bank[i],s); else { s.createdAt=Date.now(); bank.push(s); }
  qp.setId=s.id; if(!lsSet('tr_qbank', bank)) { showWarningToast('সংরক্ষণ হয়নি — স্টোরেজ ভরা থাকতে পারে।'); return; } showSuccessToast('সংরক্ষিত হয়েছে'); qpRender();
}
function qpLoad(id){ const s=qpGetBank().find(x=>x.id===id); if(!s) return; qp.meta=Object.assign(qpFreshMeta(), s.meta); qp.items=JSON.parse(JSON.stringify(s.items)); qp.title=s.title; qp.full=s.full; qp.setId=s.id; qp.editing=null; qp.gen=s.gen||null; qpRender(); }
function qpDup(id){ qpLoad(id); qp.setId=null; qp.title=(qp.title||'')+' (কপি)'; qp.items.forEach(i=>{ i.id=qpUid(); }); qpRender(); showSuccessToast('কপি হয়েছে — পরিবর্তন করে নতুন করে সংরক্ষণ করো।'); }
function qpRemoveSet(id){ const bank=qpGetBank(), rm=bank.find(x=>x.id===id); if(!rm) return; lsSet('tr_qbank', bank.filter(x=>x.id!==id)); if(qp.setId===id) qp.setId=null; qpRender(); showUndoToast('সংরক্ষিত সেট মুছেছে', ()=>{ const b=qpGetBank(); b.push(rm); lsSet('tr_qbank', b); qpRender(); }); }
function qpGate(){ const rd=qpReady(qp.items, qp.full); if(!rd.ok){ showWarningToast(rd.errors?`${qpN(rd.errors)}টা ভুল আগে ঠিক করো`:`${qpN(rd.unapproved)}টা আইটেম অনুমোদন করা বাকি`); return false; } return true; }
function qpInner(which){ const s=qpCurrentSet(); return which==='key' ? qpKeyBody(s) : qpPaperBody(s); }
function qpPrint(which){
  if(!qpGate()) return; const host=document.createElement('div'); host.id='qpPrintHost'; host.innerHTML=`<style>${QP_CSS}</style>`+qpInner(which); document.body.appendChild(host); document.body.classList.add('qp-printing');
  const done=()=>{ document.body.classList.remove('qp-printing'); host.remove(); window.removeEventListener('afterprint',done); }; window.addEventListener('afterprint',done);
  setTimeout(()=>{ try{ window.print(); }catch(e){ done(); showWarningToast('প্রিন্ট খোলা গেল না — "HTML ফাইল" নামিয়ে ব্রাউজার থেকে প্রিন্ট করো।'); } },60);
}
function qpDownload(which){
  if(!qpGate()) return; const s=qpCurrentSet(), html=qpFullDoc(qpInner(which), (s.title||'প্রশ্নপত্র')+(which==='key'?' — উত্তরমালা':''));
  const a=document.createElement('a'); a.href=URL.createObjectURL(new Blob([html],{type:'text/html'})); a.download=(which==='key'?'uttormala-':'proshnopotro-')+dateKeyStr(todayDateOnly())+'.html'; document.body.appendChild(a); a.click(); setTimeout(()=>{ URL.revokeObjectURL(a.href); a.remove(); },1500);
}

/* ===== js/25-results.js ===== */
/* ============ V73 — পরীক্ষার ফল, দুর্বল অধ্যায় ও অভিভাবকের মাসিক ফল-রিপোর্ট ============ */
/* নিয়ম (পরিকল্পনা §৪): ফল আগে শতকরায়; একটা পরীক্ষায় স্থায়ী রায় নয় (<২ পরীক্ষা = "পর্যবেক্ষণ"); অনুপস্থিত/অসম্পূর্ণ/শূন্য নম্বর আলাদা; */
/* প্রতিটা সুপারিশের সঙ্গে কারণ; শিক্ষক যেকোনো সুপারিশ বদলাতে পারে (tr_resultPins); রিপোর্ট শেয়ারের আগে পড়ে অনুমোদন। */
/* tr_results: [{id, student, subject, chapter, exam, date:'YYYY-MM-DD', got, full, status:'taken'|'absent'|'incomplete', note}] */

const RES_STATUS = {taken:'দিয়েছে', absent:'অনুপস্থিত', incomplete:'অসম্পূর্ণ'};
const RES_BAND_LABEL = {good:'ভালো অগ্রগতি', practice:'আরও অনুশীলন', weak:'পুনরায় শেখানো', watch:'পর্যবেক্ষণ'};

/* ---------- pure (unit-tested) ---------- */
function resNf(nf){ return typeof nf==='function' ? nf : (typeof toBn==='function' ? toBn : String); }
function resCfgFrom(c){ c=c||{}; const n=(v,d)=>{ v=Number(v); return isFinite(v)&&v>0&&v<=100 ? v : d; }; let good=n(c.good,80), practice=n(c.practice,60); if(practice>=good) practice=Math.max(1,good-1); return {good, practice, last:Math.max(1,Math.min(6,parseInt(c.last,10)||3))}; }
function resCfg(){ return resCfgFrom(lsGet('tr_resultCfg',{})); }
/* শতকরা (১ দশমিক পর্যন্ত); শুধু "দিয়েছে" অবস্থার বৈধ নম্বরে। পূর্ণমান ০ হলে গণনা নয়। শূন্য নম্বর = বৈধ ০%। */
function resPct(r){
  if(!r || r.status!=='taken') return null;
  const g=Number(r.got), f=Number(r.full); if(r.got===''||r.got==null||!isFinite(g)||!(f>0)||g<0||g>f) return null;
  return Math.round(g/f*1000)/10;
}
function resValidate(r){
  if(!r.student) return 'শিক্ষার্থী বাছো।'; if(!String(r.subject||'').trim()) return 'বিষয় লেখো।';
  if(!/^\d{4}-\d{2}-\d{2}$/.test(r.date||'')) return 'তারিখ ঠিক নেই।';
  if(!RES_STATUS[r.status]) return 'অবস্থা বাছো।';
  if(r.status==='taken'){ const f=Number(r.full), g=Number(r.got); if(!(f>0)) return 'পূর্ণমান ০-এর বেশি হতে হবে।'; if(r.got===''||r.got==null||!isFinite(g)||g<0) return 'প্রাপ্ত নম্বর লেখো (শূন্য পেলে ০ লেখো)।'; if(g>f) return 'প্রাপ্ত নম্বর পূর্ণমানের চেয়ে বেশি হতে পারে না।'; }
  return '';
}
function resIsDup(list, r){ return list.some(x=>x.student===r.student && x.subject===r.subject && (x.chapter||'')===(r.chapter||'') && (x.exam||'')===(r.exam||'') && x.date===r.date && x.status===r.status && Number(x.got)===Number(r.got) && Number(x.full)===Number(r.full)); }
function resBand(avg, cfg){ return avg>=cfg.good ? 'good' : (avg>=cfg.practice ? 'practice' : 'weak'); }
function resKey(student, subject, chapter){ return student+'|'+subject+'|'+(chapter||''); }
/* এক শিক্ষার্থীর প্রতিটা বিষয়/অধ্যায়ের অবস্থা। pins: {key:'weak'|'ok'|'dismiss'} */
function resStats(results, student, cfg, pins){
  cfg=cfg||resCfgFrom({}); pins=pins||{}; const g={};
  (results||[]).filter(r=>r.student===student).forEach(r=>{ const k=resKey(student,r.subject,r.chapter); (g[k]=g[k]||{student,subject:r.subject,chapter:r.chapter||'',key:k,rows:[]}).rows.push(r); });
  return Object.keys(g).map(k=>{
    const o=g[k], rows=o.rows.slice().sort((a,b)=>a.date<b.date?-1:a.date>b.date?1:String(a.id)<String(b.id)?-1:1);
    const taken=rows.filter(r=>resPct(r)!==null), pcts=taken.map(resPct), lastK=pcts.slice(-cfg.last);
    const avg=lastK.length ? Math.round(lastK.reduce((s,x)=>s+x,0)/lastK.length*10)/10 : null;
    const st={student,subject:o.subject,chapter:o.chapter,key:k,n:taken.length,used:lastK.length,pcts:lastK,avg,
      absent:rows.filter(r=>r.status==='absent').length, incomplete:rows.filter(r=>r.status==='incomplete').length, zeros:taken.filter(r=>Number(r.got)===0).length,
      trend: pcts.length>=2 ? Math.round((pcts[pcts.length-1]-pcts[pcts.length-2])*10)/10 : null, lastDate:rows[rows.length-1].date, pinned:null, dismissed:false};
    if(avg===null){ st.band='none'; }
    else { st.band=resBand(avg,cfg); if(st.n<2 && st.band==='weak') st.band='watch'; }
    const p=pins[k]; if(p==='weak'){ st.band='weak'; st.pinned='weak'; } else if(p==='ok'){ st.band='good'; st.pinned='ok'; } else if(p==='dismiss'){ st.dismissed=true; st.pinned='dismiss'; }
    return st;
  }).sort((a,b)=>(a.avg==null?999:a.avg)-(b.avg==null?999:b.avg));
}
/* কারণসহ ব্যাখ্যা — nf = সংখ্যা-ফরম্যাটার (অ্যাপে বাংলা অঙ্ক) */
function resExplain(st, nf){
  nf=resNf(nf); const ch=st.chapter?`${st.chapter} অধ্যায়ে`:`${st.subject}-এ`, avg=st.avg==null?'':nf(st.avg)+'%';
  let t;
  if(st.band==='none') t=`${ch} এখনো কোনো পূর্ণ পরীক্ষার নম্বর নেই।`;
  else if(st.pinned==='weak') t=`${ch} শিক্ষক নিজে "দুর্বল" চিহ্নিত করেছেন (গড় ${avg})।`;
  else if(st.pinned==='ok') t=`${ch} শিক্ষক "ঠিক আছে" ধরেছেন (গড় ${avg})।`;
  else if(st.band==='watch') t=`${ch} মাত্র ${nf(st.n)}টা পরীক্ষা (${avg}) — স্থায়ী সিদ্ধান্তের আগে আরেকটা পরীক্ষা দেখা ভালো; ছোট একটা কুইজ নেওয়া যায়।`;
  else if(st.band==='weak') t=`${ch} শেষ ${nf(st.used)}টা পরীক্ষার গড় ${avg}; ১০ মিনিটের পুনরাবৃত্তি ও ছোট কুইজ প্রস্তাবিত।`;
  else if(st.band==='practice') t=`${ch} শেষ ${nf(st.used)}টা পরীক্ষার গড় ${avg}; আরও কিছু অনুশীলন করালে ভালো ফল আসবে।`;
  else t=`${ch} শেষ ${nf(st.used)}টা পরীক্ষার গড় ${avg} — ভালো অগ্রগতি।`;
  if(st.trend!=null && Math.abs(st.trend)>=10) t+=` সর্বশেষ পরীক্ষায় আগেরটার চেয়ে ${nf(Math.abs(st.trend))}% ${st.trend>0?'বেড়েছে':'কমেছে'}।`;
  const side=[]; if(st.absent) side.push(`অনুপস্থিত ${nf(st.absent)}বার`); if(st.incomplete) side.push(`অসম্পূর্ণ ${nf(st.incomplete)}বার`); if(st.zeros) side.push(`০ নম্বর ${nf(st.zeros)}বার`);
  if(side.length) t+=` (${side.join(', ')} — অনুপস্থিত/অসম্পূর্ণ গড়ে ধরা হয়নি)`;
  return t;
}
function resWeakList(results, cfg, pins, onlyStudent){
  const names=[...new Set((results||[]).map(r=>r.student))].filter(n=>!onlyStudent||n===onlyStudent), out=[];
  names.forEach(n=>resStats(results,n,cfg,pins).forEach(s=>{ if(!s.dismissed && (s.band==='weak'||s.band==='watch'||s.band==='practice')) out.push(s); }));
  const rank={weak:0,watch:1,practice:2}; return out.sort((a,b)=>(rank[a.band]-rank[b.band])||((a.avg==null?999:a.avg)-(b.avg==null?999:b.avg)));
}
function resPrevMonth(mk){ const [y,m]=mk.split('-').map(Number); const d=new Date(y,m-2,1); return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0'); }
function resAttSummary(att, name, mk){ let present=0,late=0,absent=0; Object.keys(att||{}).forEach(k=>{ const p=k.split('|'); if(p[0].slice(0,7)!==mk || p.slice(2).join('|')!==name) return; const s=att[k]; if(s==='present')present++; else if(s==='late')late++; else if(s==='absent')absent++; }); return {present,late,absent,marked:present+late+absent}; }
/* মাসের রিপোর্টের কাঁচা তথ্য: বিষয়ভিত্তিক গড় + আগের মাসের সঙ্গে পরিবর্তন */
function resMonthReport(results, student, mk, att, cfg, pins){
  cfg=cfg||resCfgFrom({}); const mine=(results||[]).filter(r=>r.student===student), prev=resPrevMonth(mk);
  const avgOf=(rows)=>{ const p=rows.map(resPct).filter(x=>x!==null); return p.length?Math.round(p.reduce((s,x)=>s+x,0)/p.length*10)/10:null; };
  const subs=[...new Set(mine.filter(r=>r.date.slice(0,7)===mk).map(r=>r.subject))].map(s=>{
    const cur=mine.filter(r=>r.subject===s&&r.date.slice(0,7)===mk), pr=mine.filter(r=>r.subject===s&&r.date.slice(0,7)===prev), a=avgOf(cur), b=avgOf(pr);
    return {subject:s, avg:a, prev:b, delta:(a!=null&&b!=null)?Math.round((a-b)*10)/10:null, n:cur.filter(r=>resPct(r)!==null).length, absent:cur.filter(r=>r.status==='absent').length, incomplete:cur.filter(r=>r.status==='incomplete').length};
  });
  const st=resStats(mine,student,cfg,pins).filter(s=>!s.dismissed && s.lastDate.slice(0,7)===mk);
  return {mk, subjects:subs, good:st.filter(s=>s.band==='good'), practice:st.filter(s=>s.band==='practice'||s.band==='weak'||s.band==='watch'), att:resAttSummary(att,student,mk), examsTaken:mine.filter(r=>r.date.slice(0,7)===mk&&resPct(r)!==null).length};
}
function resReportText(o){      // o: {display, klass, monthLabel, rep, teacher, comment, nf}
  const nf=resNf(o.nf), r=o.rep, L=[`📊 ${o.display}${o.klass?' ('+o.klass+')':''} — ${o.monthLabel}-এর পরীক্ষার ফল`,''];
  if(r.att.marked) L.push(`✅ উপস্থিতি: ${nf(r.att.marked)}টা ক্লাসের মধ্যে ${nf(r.att.present+r.att.late)}টায় উপস্থিত`,'');
  if(!r.subjects.length) L.push('এই মাসে কোনো পরীক্ষার ফল নেই।');
  r.subjects.forEach(s=>{
    let line=`• ${s.subject}: `+(s.avg==null?'পূর্ণ পরীক্ষা হয়নি':`${nf(s.avg)}%`);
    if(s.delta!=null) line+=s.delta>0?` (আগের মাসের চেয়ে ${nf(s.delta)}% বেশি ⬆️)`:s.delta<0?` (আগের মাসের চেয়ে ${nf(Math.abs(s.delta))}% কম ⬇️)`:' (আগের মাসের মতোই)';
    if(s.absent) line+=` — ${nf(s.absent)}টা পরীক্ষায় অনুপস্থিত`; if(s.incomplete) line+=` — ${nf(s.incomplete)}টা অসম্পূর্ণ`;
    L.push(line);
  });
  const nm=s=>s.chapter?`${s.subject} (${s.chapter})`:s.subject;
  if(r.good.length) L.push('','👍 ভালো করছে: '+r.good.map(nm).join(', '));
  if(r.practice.length){ L.push('','🔁 আরও অনুশীলন দরকার: '+r.practice.map(nm).join(', '),'📌 আগামী মাসের পরিকল্পনা: এই বিষয়গুলোয় ছোট পুনরাবৃত্তি ও কুইজ।'); }
  if(o.comment) L.push('','💬 শিক্ষকের মন্তব্য: '+o.comment);
  L.push('', o.teacher?`ধন্যবাদ,\n${o.teacher}`:'ধন্যবাদ।'); return L.join('\n');
}

/* ---------- screen ---------- */
let res={tab:'add', student:'', status:'taken', filter:'', mk:'', approved:false, comment:''};
function resList(){ const l=lsGet('tr_results',[]); return Array.isArray(l)?l:[]; }
function resOpen(){ if(!res.mk) res.mk=currentMonthKey(); const names=getAllKnownNames(); if(!res.student||!names.includes(res.student)) res.student=names[0]||''; showKhataModal('📊 ফল ও দুর্বলতা','<div id="resBox"></div>'); resRender(); }
function resTab(t){ res.tab=t; res.approved=false; resRender(); }
function resSetStudent(v){ res.student=v; res.approved=false; resRender(); }
function resSetStatus(s){ res.status=s; resRender(); }
function resSubjectOpts(){ const sj=getStudentSubjects(res.student)||{}; return Object.keys(sj); }
function resChapterOpts(subj){ const c=(getStudentSubjects(res.student)||{})[subj]; return Array.isArray(c)?c.map(x=>x.chapter).filter(Boolean):[]; }
function resChips(){ return `<div class="pct-chip-row">${[['add','➕ ফল যোগ'],['weak','🔎 দুর্বলতা'],['report','📨 মাসিক রিপোর্ট']].map(([k,l])=>`<button type="button" class="pct-chip${res.tab===k?' active':''}" onclick="resTab('${k}')">${l}</button>`).join('')}</div>`; }
function resStudentSel(all){ const names=getAllKnownNames(); return `<select class="sm-field-input" onchange="resSetStudent(this.value)">${all?`<option value="">সবাই</option>`:''}${names.map(n=>`<option value="${escapeHtml(n)}"${n===res.student?' selected':''}>${escapeHtml(studentDisplayName(n))}</option>`).join('')}</select>`; }
function resRender(){
  const box=document.getElementById('resBox'); if(!box) return;
  if(!getAllKnownNames().length){ box.innerHTML=emptyState({icon:'chart',title:'কোনো শিক্ষার্থী নেই',body:'আগে শিক্ষার্থী যোগ করো, তারপর পরীক্ষার ফল লিখো।'}); return; }
  box.innerHTML=resChips()+(res.tab==='add'?resAddHtml():res.tab==='weak'?resWeakHtml():resReportHtml());
}
function resAddHtml(){
  const s=res.status, subs=resSubjectOpts(), E=escapeHtml, recent=resList().filter(r=>r.student===res.student).sort((a,b)=>a.date<b.date?1:-1).slice(0,8);
  return `<label class="sm-field-label">শিক্ষার্থী</label>${resStudentSel(false)}
  <datalist id="resSubj">${subs.map(x=>`<option value="${E(x)}">`).join('')}</datalist>
  <div class="qp-grid"><div><label class="sm-field-label">বিষয়</label><input class="sm-field-input" id="rs_subj" list="resSubj" placeholder="যেমন গণিত" oninput="resChapterList()"></div>
  <div><label class="sm-field-label">অধ্যায়/টপিক</label><input class="sm-field-input" id="rs_ch" list="resCh" placeholder="যেমন অনুপাত"><datalist id="resCh"></datalist></div>
  <div><label class="sm-field-label">পরীক্ষার নাম</label><input class="sm-field-input" id="rs_exam" placeholder="যেমন মাসিক পরীক্ষা"></div>
  <div><label class="sm-field-label">তারিখ</label><input type="date" class="sm-field-input" id="rs_date" value="${dateKeyStr(todayDateOnly())}"></div></div>
  <label class="sm-field-label">অবস্থা</label><div class="pct-chip-row">${Object.keys(RES_STATUS).map(k=>`<button type="button" class="pct-chip${s===k?' active':''}" onclick="resSetStatus('${k}')">${RES_STATUS[k]}</button>`).join('')}</div>
  ${s==='taken'?`<div class="qp-grid"><div><label class="sm-field-label">প্রাপ্ত নম্বর</label><input type="number" min="0" step="any" class="sm-field-input" id="rs_got" placeholder="শূন্য পেলে ০"></div><div><label class="sm-field-label">পূর্ণমান</label><input type="number" min="1" class="sm-field-input" id="rs_full" placeholder="যেমন ২৫"></div></div>`:`<div class="qp-note-small">${s==='absent'?'অনুপস্থিত — নম্বর গড়ে ধরা হবে না (শূন্য নম্বরের সঙ্গে গুলিয়ে ফেলা হয় না)।':'অসম্পূর্ণ (শেষ করেনি) — নম্বর গড়ে ধরা হবে না।'}</div>`}
  <label class="sm-field-label">মন্তব্য (ঐচ্ছিক)</label><input class="sm-field-input" id="rs_note">
  <div class="qp-actions"><button type="button" class="modal-btn primary" onclick="resSave()">সেভ করো</button></div>
  ${recent.length?`<div class="settings-section-title" style="margin-top:14px;">সাম্প্রতিক ফল</div>${recent.map(r=>{ const p=resPct(r); return `<div class="makeup-row"><span>${E(r.subject)}${r.chapter?' · '+E(r.chapter):''} <small style="color:var(--muted)">${E(r.exam||'')} · ${bnDateLabel(new Date(r.date+'T00:00:00'))}</small></span><span class="pay-history-amt">${p!==null?toBn(r.got)+'/'+toBn(r.full)+' ('+toBn(p)+'%)':RES_STATUS[r.status]} <button class="makeup-done" onclick="resDel('${r.id}')">🗑</button></span></div>`; }).join('')}`:''}`;
}
function resChapterList(){ const sj=document.getElementById('rs_subj'), dl=document.getElementById('resCh'); if(!sj||!dl) return; dl.innerHTML=resChapterOpts(sj.value.trim()).map(c=>`<option value="${escapeHtml(c)}">`).join(''); }
function resSave(){
  const v=id=>{ const e=document.getElementById(id); return e?e.value.trim():''; };
  const r={id:Date.now()+'_'+Math.random().toString(36).slice(2,7), student:res.student, subject:v('rs_subj'), chapter:v('rs_ch'), exam:v('rs_exam'), date:v('rs_date'), status:res.status, got:res.status==='taken'?v('rs_got'):null, full:res.status==='taken'?v('rs_full'):null, note:v('rs_note')};
  const err=resValidate(r); if(err){ showWarningToast(err); return; }
  if(res.status==='taken'){ r.got=Number(r.got); r.full=Number(r.full); }
  const list=resList(); if(resIsDup(list,r)){ showWarningToast('এই ফলটা আগেই লেখা আছে — দ্বিতীয়বার যোগ হয়নি।'); return; }
  list.push(r); if(!lsSet('tr_results',list)){ showWarningToast('সেভ হয়নি — স্টোরেজ ভরা থাকতে পারে।'); return; }
  showSuccessToast('ফল সেভ হয়েছে'); res.status='taken'; resRender();
}
function resDel(id){ const list=resList(), rm=list.find(x=>x.id===id); if(!rm) return; lsSet('tr_results', list.filter(x=>x.id!==id)); if(typeof tombAdd==='function') tombAdd('res', id); resRender(); showUndoToast('ফল মুছেছে', ()=>{ const l=resList(); l.push(rm); lsSet('tr_results',l); if(typeof tombClear==='function') tombClear('res', id); resRender(); }); }
function resPin(key, val){ const p=lsGet('tr_resultPins',{}); if(val) p[key]=val; else delete p[key]; lsSet('tr_resultPins',p); resRender(); }
function resPinBtn(key,val,label){ return `<button type="button" onclick="resPin(decodeURIComponent('${encodeURIComponent(key)}'),${val?`'${val}'`:'null'})">${label}</button>`; }
function resWeakHtml(){
  const cfg=resCfg(), pins=lsGet('tr_resultPins',{}), list=resWeakList(resList(),cfg,pins,res.filter), E=escapeHtml;
  const hidden=resList().length? [...new Set(resList().map(r=>r.student))].reduce((n,s)=>n+resStats(resList(),s,cfg,pins).filter(x=>x.dismissed).length,0):0;
  const col={weak:'#ff9d8a',watch:'#9ab4ff',practice:'#f2c85e'};
  return `<label class="sm-field-label">কার জন্য</label><select class="sm-field-input" onchange="res.filter=this.value;resRender()"><option value="">সবাই</option>${getAllKnownNames().map(n=>`<option value="${E(n)}"${n===res.filter?' selected':''}>${E(studentDisplayName(n))}</option>`).join('')}</select>
  ${list.length?list.map(s=>`<div class="qp-card"><div class="qp-ch"><b>${E(studentDisplayName(s.student))} — ${E(s.subject)}${s.chapter?' · '+E(s.chapter):''}</b><span style="color:${col[s.band]}">${RES_BAND_LABEL[s.band]}${s.avg!=null?' · '+toBn(s.avg)+'%':''}</span></div>
   <div class="qp-ex">${s.pcts.length?'শেষ ফল: '+s.pcts.map(p=>toBn(p)+'%').join(' → '):''}</div><div class="qp-qt" style="margin-top:4px;">${E(resExplain(s,toBn))}</div>
   <div class="qp-btns">${resPinBtn(s.key,'weak','🚩 দুর্বল ধরো')}${resPinBtn(s.key,'ok','👍 ঠিক আছে')}${resPinBtn(s.key,'dismiss','🙈 লুকাও')}${s.pinned?resPinBtn(s.key,null,'↩ রিসেট'):''}</div></div>`).join(''):`<div class="ins-empty" style="margin-top:10px;">${resList().length?'এখন কোনো দুর্বল বা পর্যবেক্ষণযোগ্য অধ্যায় নেই 🎉':'ফল যোগ করলে এখানে বিশ্লেষণ আসবে।'}</div>`}
  ${hidden?`<div class="qp-note-small">${toBn(hidden)}টা লুকানো আছে — "রিসেট" করতে সংশ্লিষ্ট ফল খুঁজে আবার দুর্বল/ঠিক আছে চাপো।</div>`:''}
  <details style="margin-top:12px;"><summary class="settings-btn" style="text-align:left;">⚙️ সীমা বদলাও (এখন: ${toBn(cfg.good)}%+ ভালো · ${toBn(cfg.practice)}–${toBn(cfg.good-1)}% অনুশীলন · নিচে পুনরায় শেখানো)</summary>
   <div class="qp-grid"><div><label class="sm-field-label">ভালো (%-এর ওপরে)</label><input type="number" class="sm-field-input" id="rc_good" value="${cfg.good}"></div><div><label class="sm-field-label">অনুশীলন (%-এর ওপরে)</label><input type="number" class="sm-field-input" id="rc_prac" value="${cfg.practice}"></div><div><label class="sm-field-label">শেষ কয়টা পরীক্ষার গড়</label><input type="number" min="1" max="6" class="sm-field-input" id="rc_last" value="${cfg.last}"></div></div>
   <div class="qp-actions"><button type="button" class="modal-btn secondary" onclick="resSaveCfg()">সংরক্ষণ</button></div></details>`;
}
function resSaveCfg(){ const c=resCfgFrom({good:document.getElementById('rc_good').value, practice:document.getElementById('rc_prac').value, last:document.getElementById('rc_last').value}); lsSet('tr_resultCfg',c); showSuccessToast('সীমা বদলেছে'); resRender(); }
function resMonthOpts(){ const o=[]; let mk=currentMonthKey(); for(let i=0;i<6;i++){ o.push(mk); mk=resPrevMonth(mk); } return o; }
function resBuildText(){ const name=res.student, pr=getStudentProfile(name)||{}, rep=resMonthReport(resList(), name, res.mk, getAttendanceMap(), resCfg(), lsGet('tr_resultPins',{}));
  return resReportText({display:studentDisplayName(name), klass:pr.klass||'', monthLabel:monthKeyLabel(res.mk), rep, teacher:getTeacherName(false), comment:res.comment, nf:toBn}); }
function resReportHtml(){
  const E=escapeHtml, txt=resBuildText();
  return `<label class="sm-field-label">শিক্ষার্থী</label>${resStudentSel(false)}<label class="sm-field-label">মাস</label><select class="sm-field-input" onchange="res.mk=this.value;res.approved=false;resRender()">${resMonthOpts().map(m=>`<option value="${m}"${m===res.mk?' selected':''}>${E(monthKeyLabel(m))}</option>`).join('')}</select>
  <label class="sm-field-label">শিক্ষকের মন্তব্য (ঐচ্ছিক)</label><input class="sm-field-input" value="${E(res.comment)}" onchange="res.comment=this.value;res.approved=false;resRender()">
  <label class="sm-field-label">প্রিভিউ (পাঠানোর আগে পড়ে নাও — দরকারে এখানেই বদলাও)</label><textarea class="sm-field-input" id="res_txt" rows="12" oninput="res.approved=false;resSyncApprove()">${E(txt)}</textarea>
  <label style="display:flex;gap:8px;align-items:center;margin-top:10px;font-size:var(--fs-sm);"><input type="checkbox" id="res_ok" onchange="res.approved=this.checked;resSyncApprove()"> পড়ে দেখেছি, শেয়ারের জন্য ঠিক আছে</label>
  <div class="qp-actions"><button type="button" class="modal-btn primary" id="res_cp" onclick="resShare('copy')" disabled>📋 কপি</button><button type="button" class="modal-btn primary" id="res_wa" onclick="resShare('wa')" disabled>💬 WhatsApp</button></div>
  <div class="qp-note-small">রিপোর্টে কোনো ফি/বকেয়ার তথ্য যায় না — শুধু উপস্থিতি, ফল ও পরিকল্পনা।</div>`;
}
function resSyncApprove(){ const ok=document.getElementById('res_ok'), on=!!(ok&&ok.checked); ['res_cp','res_wa'].forEach(i=>{ const b=document.getElementById(i); if(b) b.disabled=!on; }); }
function resShare(how){ const t=(document.getElementById('res_txt')||{}).value||''; if(!t.trim()||!res.approved) return; if(how==='copy') copyTextSmart(t,'রিপোর্ট কপি হয়েছে — WhatsApp-এ পেস্ট করো'); else { const pr=getStudentProfile(res.student)||{}; if(!(pr.guardianPhone||'').trim()) showWarningToast('অভিভাবকের ফোন সেভ করা নেই — নিজে কন্ট্যাক্ট বেছে নাও।'); openWhatsApp(pr.guardianPhone, t); } }

/* ===== js/26-fees.js ===== */
/* ============ V74 — ফি সমন্বয়, বাতিল-যোগ্য পেমেন্ট, হিসাব-মেলানো, রুটিনের সংঘর্ষ ও অনুপস্থিতির ধারা ============ */
/* নিয়ম (পরিকল্পনা §৫): বকেয়া = নির্ধারিত ফি + অনুমোদিত অতিরিক্ত চার্জ − ছাড়/সমন্বয় − সফল পেমেন্ট। হিসাবের সূত্র একটাই (feeEffective, js/02-payments.js)। */
/* চার্জ/ছাড় আর পেমেন্ট আলাদা রেকর্ড; মোছার বদলে বাতিল (void) — ইতিহাস থাকে, ফিরিয়ে আনা যায়। tr_adjust: [{id,student,monthKey,kind:'charge'|'discount',amount,reason,date,at,voided?}] */

/* ---------- pure (unit-tested) ---------- */
function feeStatementPure(fee, adjs, paid){
  fee=Number(fee)||0; paid=Number(paid)||0; let charges=0, discounts=0;
  (adjs||[]).forEach(a=>{ if(!a||a.voided) return; const x=Number(a.amount)||0; if(a.kind==='discount') discounts+=x; else charges+=x; });
  const gross=fee+charges-discounts, eff=Math.max(0,gross);
  return {scheduled:fee, charges, discounts, effective:eff, paid, due:Math.max(0,eff-paid), overpaid:Math.max(0,paid-eff), clamped:gross<0};
}
function feeAdjValidate(a){
  if(!a.student) return 'শিক্ষার্থী বাছো।'; if(!/^\d{4}-\d{2}$/.test(a.monthKey||'')) return 'মাস ঠিক নেই।';
  if(a.kind!=='charge' && a.kind!=='discount') return 'ছাড় না অতিরিক্ত চার্জ — বাছো।';
  if(!(Number(a.amount)>0)) return 'টাকার পরিমাণ ০-এর বেশি লেখো।'; if(Number(a.amount)>1000000) return 'টাকার অংকটা অস্বাভাবিক বড়।';
  if(!String(a.reason||'').trim()) return 'কারণ লেখো (পরে হিসাব মেলাতে লাগবে)।'; return '';
}
/* পরপর কতগুলো ক্লাস অনুপস্থিত (সর্বশেষ থেকে পিছনে)। বাতিল/পিছানো/ছুটি-নেওয়া এবং বন্ধের দিন গোনা হয় না, ধারাও ভাঙে না। isOff(dateKey, slotNum) ঐচ্ছিক। */
function absenceStreakOf(att, name, isOff){
  const rows=[]; Object.keys(att||{}).forEach(k=>{ const p=k.split('|'); if(p.slice(2).join('|')!==name) return; rows.push({date:p[0], slot:Number(p[1])||0, st:att[k]}); });
  rows.sort((a,b)=> a.date<b.date?1:a.date>b.date?-1:(b.slot-a.slot));
  let n=0;
  for(const r of rows){
    if(r.st==='cancelled'||r.st==='resched'||r.st==='excused') continue;
    if(isOff && isOff(r.date, r.slot)) continue;
    if(r.st==='absent'){ n++; continue; }
    break;
  }
  return n;
}
/* সরানো/মেকআপের সময়ের সংঘর্ষ: info={name, slotLabel, here:[নাম…], slotOff, dayOff} → {level:'ok'|'warn'|'block', reasons[]} */
function routineConflictFrom(info){
  const reasons=[]; let level='ok'; const here=(info.here||[]), others=here.filter(n=>n!==info.name);
  if(here.includes(info.name)){ level='block'; reasons.push(`${info.name}-এর ওই সময়ে (${info.slotLabel||''}) আগে থেকেই ক্লাস আছে — একই ছাত্রের দুটো ক্লাস একই সময়ে রাখা যায় না।`); }
  if(info.dayOff){ if(level==='ok') level='warn'; reasons.push('ওই দিনটা পুরো বন্ধ/ছুটি হিসেবে চিহ্নিত।'); }
  else if(info.slotOff){ if(level==='ok') level='warn'; reasons.push('ওই দিনে এই সময়টা বন্ধ চিহ্নিত।'); }
  if(others.length && level!=='block'){ level='warn'; reasons.push(`ওই সময়ে আরও ${others.length} জনের ক্লাস আছে: ${others.slice(0,4).join(', ')}${others.length>4?'…':''}।`); }
  return {level, reasons};
}

/* ---------- app wrappers ---------- */
function feeAdjList(){ const l=lsGet('tr_adjust',[]); return Array.isArray(l)?l:[]; }
function feeStatement(name, mk){ return feeStatementPure(getStudentPayment(name).monthlyFee, feeAdjList().filter(a=>a.student===name&&a.monthKey===mk), getStudentPaidForMonth(name, mk)); }
function feeAdjAdd(a){
  const err=feeAdjValidate(a); if(err) return {ok:false, error:err};
  const list=feeAdjList(), rec={id:Date.now()+'_'+Math.random().toString(36).slice(2,7), student:a.student, monthKey:a.monthKey, kind:a.kind, amount:Math.round(Number(a.amount)*100)/100, reason:String(a.reason).trim(), date:dateKeyStr(todayDateOnly()), at:Date.now()};
  list.push(rec); if(!lsSet('tr_adjust',list)) return {ok:false, error:'সেভ হয়নি — স্টোরেজ ভরা থাকতে পারে।'}; return {ok:true, id:rec.id};
}
function feeAdjSetVoid(id, voided){ const list=feeAdjList(), a=list.find(x=>x.id===id); if(!a) return false; if(voided){ a.voided=true; a.voidedAt=Date.now(); } else { delete a.voided; delete a.voidedAt; } lsSet('tr_adjust',list); return true; }
function routineCheckMove(date, toSlotNum, name){
  const slot=SCHEDULE.find(s=>s.num===toSlotNum); if(!slot) return {level:'ok', reasons:[]};
  const dow=DAYS[(date.getDay()+1)%7], here=(effectiveContentForDate(slot, dow, date)||'').split(',').map(x=>x.trim()).filter(Boolean);
  return routineConflictFrom({name, slotLabel:slot.label, here, slotOff:isOffOn(date,toSlotNum), dayOff:isDayFullyOff(date)});
}
function computeAbsenceStreaks(n){
  const att=getAttendanceMap(), off=getOffMap(), isOff=(d,s)=>{ const i=off[d]; return i==='all'||(Array.isArray(i)&&i.includes(s)); }, out=[];
  getAllKnownNames().forEach(name=>{ const st=absenceStreakOf(att,name,isOff); if(st>=(n||3)) out.push({name, streak:st}); });
  return out.sort((a,b)=>b.streak-a.streak);
}
/* হিসাব মেলানো — প্রতিটা শিক্ষার্থীর হিসাব নতুন করে গুণে, আলাদা জায়গার (রিপোর্টের) মোটের সঙ্গে মেলায়। */
function feeCheck(mk){
  const names=[...new Set([...getAllKnownNames(), ...Object.keys(getPaymentsData())])], adj=feeAdjList(), issues=[], rows=[];
  const T={scheduled:0,charges:0,discounts:0,expected:0,collected:0,due:0,overpaid:0}, known=new Set(getAllKnownNames());
  names.forEach(n=>{
    const st=feeStatementPure(getStudentPayment(n).monthlyFee, adj.filter(a=>a.student===n&&a.monthKey===mk), getStudentPaidForMonth(n,mk));
    rows.push(Object.assign({name:n},st)); T.scheduled+=st.scheduled; T.charges+=st.charges; T.discounts+=st.discounts; T.expected+=st.effective; T.collected+=st.paid; T.due+=st.due; T.overpaid+=st.overpaid;
    if(st.clamped) issues.push({level:'warn', text:`"${n}"-এর ছাড় ফির চেয়ে বেশি — প্রদেয় ০ ধরা হয়েছে।`});
    if(st.overpaid>0) issues.push({level:'info', text:`"${n}" ${bnTaka(st.overpaid)} বেশি দিয়েছেন (অগ্রিম/সমন্বয়ের কথা ভাবো)।`});
    const rec=getStudentPayment(n), seen={}, refs={};
    rec.payments.forEach(p=>{
      if(!(Number(p.amount)>0)) issues.push({level:'error', text:`"${n}"-এর একটা পেমেন্টের অংক ঠিক নেই।`});
      if(p.ref){ if(refs[p.ref]) issues.push({level:'error', text:`"${n}"-এ একই ট্রানজ্যাকশন (${p.ref}) দুবার আছে।`}); refs[p.ref]=1; }
      if(p.monthKey===mk){ const k=[p.amount,p.method||'',p.date||''].join('|'); if(seen[k]) issues.push({level:'warn', text:`"${n}"-এ একই দিনে একই টাকা ও পদ্ধতির পেমেন্ট একাধিক (${bnTaka(p.amount)}) — ডুপ্লিকেট কি না দেখো।`}); seen[k]=1; }
    });
    if(!known.has(n) && rec.payments.length) issues.push({level:'info', text:`"${n}" এখন তালিকায় নেই, কিন্তু পেমেন্ট রেকর্ড আছে।`});
  });
  const stats=computeMonthlyIncomeStats(mk);
  if(Math.round(stats.totalExpected)!==Math.round(T.expected)) issues.push({level:'error', text:`প্রত্যাশিত আয় মিলছে না: রিপোর্টে ${bnTaka(stats.totalExpected)}, নতুন হিসাবে ${bnTaka(T.expected)}।`});
  if(Math.round(stats.totalPaid)!==Math.round(T.collected)) issues.push({level:'error', text:`আদায় মিলছে না: রিপোর্টে ${bnTaka(stats.totalPaid)}, নতুন হিসাবে ${bnTaka(T.collected)}।`});
  return {mk, rows, totals:T, issues, ok:!issues.some(i=>i.level==='error')};
}

/* ---------- screen ---------- */
let fee={student:'', mk:'', kind:'discount', check:null};
function feeOpen(){
  if(isFinanceHidden()){ showWarningToast('আগে আর্থিক হিসাব আনলক করো (রিপোর্ট ট্যাবের উপরে "দেখাও")।'); return; }
  if(!fee.mk) fee.mk=currentMonthKey(); const names=getAllKnownNames(); if(!fee.student||!names.includes(fee.student)) fee.student=names[0]||''; fee.check=null;
  showKhataModal('🧾 ফি ও হাজিরা','<div id="feeBox"></div>'); feeRender();
}
function feeSet(k,v){ fee[k]=v; fee.check=null; feeRender(); }
function feeRender(){
  const box=document.getElementById('feeBox'); if(!box) return; if(!fee.student){ box.innerHTML=emptyState({icon:'chart',title:'কোনো শিক্ষার্থী নেই',body:'আগে শিক্ষার্থী যোগ করো।'}); return; }
  const E=escapeHtml, n=fee.student, mk=fee.mk, st=feeStatement(n,mk), adj=feeAdjList().filter(a=>a.student===n&&a.monthKey===mk), pays=getStudentPayment(n).payments.filter(p=>p.monthKey===mk), voided=(getStudentPayment(n).voided||[]).filter(p=>p.monthKey===mk||true).slice(-6).reverse();
  const row=(l,v,cls)=>`<div class="makeup-row"><span>${l}</span><span class="pay-history-amt" ${cls?`style="color:${cls}"`:''}>${bnTaka(v)}</span></div>`;
  box.innerHTML=`<div class="qp-grid"><div><label class="sm-field-label">শিক্ষার্থী</label><select class="sm-field-input" onchange="feeSet('student',this.value)">${getAllKnownNames().map(x=>`<option value="${E(x)}"${x===n?' selected':''}>${E(studentDisplayName(x))}</option>`).join('')}</select></div>
   <div><label class="sm-field-label">মাস</label><select class="sm-field-input" onchange="feeSet('mk',this.value)">${resMonthOpts().map(m=>`<option value="${m}"${m===mk?' selected':''}>${E(monthKeyLabel(m))}</option>`).join('')}</select></div></div>
  <div class="settings-section-title" style="margin-top:12px;">হিসাব</div>
  ${row('নির্ধারিত ফি',st.scheduled)}${st.charges?row('+ অতিরিক্ত চার্জ',st.charges):''}${st.discounts?row('− ছাড়/সমন্বয়',st.discounts):''}${row('= এই মাসে প্রদেয়',st.effective)}${row('পরিশোধ',st.paid,'#5ef2c8')}${row('বকেয়া',st.due,st.due>0?'#ff9d8a':'#5ef2c8')}${st.overpaid?row('অতিরিক্ত জমা',st.overpaid):''}
  <div class="settings-section-title" style="margin-top:12px;">ছাড় / অতিরিক্ত চার্জ যোগ</div>
  <div class="pct-chip-row">${[['discount','ছাড়/সমন্বয়'],['charge','অতিরিক্ত চার্জ']].map(([k,l])=>`<button type="button" class="pct-chip${fee.kind===k?' active':''}" onclick="fee.kind='${k}';feeRender()">${l}</button>`).join('')}</div>
  <div class="qp-grid"><div><label class="sm-field-label">টাকা</label><input type="number" min="1" class="sm-field-input" id="fa_amt"></div><div><label class="sm-field-label">কারণ (বাধ্যতামূলক)</label><input class="sm-field-input" id="fa_reason" placeholder="যেমন ভাই-বোন ছাড়"></div></div>
  <div class="qp-actions"><button type="button" class="modal-btn primary" onclick="feeAddAdj()">যোগ করো</button></div>
  ${adj.length?adj.map(a=>`<div class="makeup-row" ${a.voided?'style="opacity:.55;text-decoration:line-through;"':''}><span>${a.kind==='discount'?'− ছাড়':'+ চার্জ'} · ${E(a.reason)}</span><span class="pay-history-amt">${bnTaka(a.amount)} <button class="makeup-done" onclick="feeVoidAdj('${a.id}',${a.voided?'false':'true'})">${a.voided?'↩ ফিরিয়ে আনো':'বাতিল'}</button></span></div>`).join(''):''}
  <div class="settings-section-title" style="margin-top:12px;">এই মাসের পেমেন্ট</div>
  ${pays.length?pays.map(p=>`<div class="makeup-row"><span>${p.no?'রসিদ #'+toBn(p.no)+' · ':''}${E(p.method||'নগদ')} · ${bnDateLabel(new Date((p.date||dateKeyStr(todayDateOnly()))+'T00:00:00'))}${p.ref?' · '+E(p.ref):''}</span><span class="pay-history-amt">${bnTaka(p.amount)} <button class="makeup-done" onclick="feeRevPay('${p.id}')">রিভার্স</button></span></div>`).join(''):'<div class="ins-empty">এই মাসে কোনো পেমেন্ট নেই।</div>'}
  ${voided.length?`<div class="qp-note-small">বাতিল হওয়া পেমেন্ট (হিসাবে ধরা হয় না):</div>${voided.map(p=>`<div class="makeup-row" style="opacity:.7;"><span>${E(monthKeyLabel(p.monthKey==='opening'?currentMonthKey():p.monthKey))} · ${E(p.voidReason||'কারণ লেখা নেই')}</span><span class="pay-history-amt">${bnTaka(p.amount)} <button class="makeup-done" onclick="feeRestorePay('${p.id}')">↩ ফিরিয়ে আনো</button></span></div>`).join('')}`:''}
  <div class="settings-section-title" style="margin-top:14px;">🔍 হিসাব মিলিয়ে দেখো (${E(monthKeyLabel(mk))})</div>
  <div class="qp-actions"><button type="button" class="modal-btn secondary" onclick="feeRunCheck()">সব শিক্ষার্থীর হিসাব যাচাই</button></div>${fee.check?feeCheckHtml(fee.check):''}
  <div class="settings-section-title" style="margin-top:14px;">📅 রুটিন ও হাজিরা</div>${feeRoutineHtml()}`;
}
function feeAddAdj(){
  const r=feeAdjAdd({student:fee.student, monthKey:fee.mk, kind:fee.kind, amount:document.getElementById('fa_amt').value, reason:document.getElementById('fa_reason').value});
  if(!r.ok){ showWarningToast(r.error); return; } showSuccessToast('যোগ হয়েছে'); fee.check=null; feeRender(); if(typeof refreshFinanceViews==='function') refreshFinanceViews();
}
function feeVoidAdj(id, v){ feeAdjSetVoid(id, v); fee.check=null; feeRender(); if(typeof refreshFinanceViews==='function') refreshFinanceViews(); showUndoToast(v?'বাতিল করা হয়েছে':'ফিরিয়ে আনা হয়েছে', ()=>{ feeAdjSetVoid(id, !v); feeRender(); if(typeof refreshFinanceViews==='function') refreshFinanceViews(); }); }
function feeRevPay(id){ const reason=prompt('রিভার্সের কারণ (যেমন: ভুল এন্ট্রি / ফেরত দেওয়া হয়েছে):',''); if(reason===null) return; deletePayment(fee.student, id, reason); fee.check=null; feeRender(); if(typeof refreshFinanceViews==='function') refreshFinanceViews(); showUndoToast('পেমেন্ট রিভার্স হয়েছে', ()=>{ restorePayment(fee.student,id); feeRender(); if(typeof refreshFinanceViews==='function') refreshFinanceViews(); }); }
function feeRestorePay(id){ if(restorePayment(fee.student,id)){ showSuccessToast('পেমেন্ট ফিরে এসেছে'); fee.check=null; feeRender(); if(typeof refreshFinanceViews==='function') refreshFinanceViews(); } }
function feeRunCheck(){ fee.check=feeCheck(fee.mk); feeRender(); }
function feeCheckHtml(c){
  const T=c.totals, E=escapeHtml;
  return `<div class="qp-gate ${c.ok?'ok':'bad'}">${c.ok?'✅ হিসাব মিলেছে':'⛔ অমিল পাওয়া গেছে'} — প্রত্যাশিত ${bnTaka(T.expected)} · আদায় ${bnTaka(T.collected)} · বকেয়া ${bnTaka(T.due)}${T.discounts?` · ছাড় ${bnTaka(T.discounts)}`:''}${T.charges?` · অতিরিক্ত চার্জ ${bnTaka(T.charges)}`:''}</div>`
   + c.issues.map(i=>`<div class="qp-iss ${i.level==='error'?'error':'warn'}">${i.level==='error'?'⛔':i.level==='warn'?'⚠️':'ℹ️'} ${E(i.text)}</div>`).join('');
}
function feeRoutineHtml(){
  const E=escapeHtml, st=computeAbsenceStreaks(3), pend=getMakeups(), hist=getMakeupHistory().slice(-5).reverse();
  return (st.length?st.map(x=>`<div class="makeup-row"><span>🔴 ${E(studentDisplayName(x.name))}</span><span class="pay-history-amt">পরপর ${toBn(x.streak)}টা ক্লাস অনুপস্থিত</span></div>`).join(''):'<div class="ins-empty">কেউ পরপর ৩টা ক্লাস অনুপস্থিত নয় ✅ (বাতিল/ছুটি/পিছানো গোনা হয় না)</div>')
   + `<div class="qp-note-small" style="margin-top:8px;">বাকি মেকআপ: ${toBn(pend.length)}টা · হয়ে গেছে (ইতিহাস): ${toBn(getMakeupHistory().length)}টা</div>`
   + hist.map(m=>`<div class="makeup-row" style="opacity:.75;"><span>✓ ${E(m.name)} — ${E(m.slotLabel||'')}</span><span class="pay-history-amt">${bnDateLabel(new Date(m.date+'T00:00:00'))}</span></div>`).join('');
}

/* ===== js/27-backup2.js ===== */
/* ============ V75 — নিরাপদ ব্যাকআপ: স্কিমা+চেকসাম যাচাই, রিস্টোরের আগে "কী বদলাবে" প্রিভিউ, দুই ডিভাইসের তথ্য মার্জ ============ */
/* বাস্তবতা: লাইভ ক্লাউড-সিঙ্ক (লগইন, সার্ভার-অথরাইজেশন) এখানে বানানো হয়নি — পরিকল্পনাই বলে স্থিতিশীল হওয়ার আগে নয়। */
/* বদলে আছে: অনলাইন ব্যাকআপ (রিকভারি কোড) + এই মার্জ — দুই ফোনের তথ্য রেকর্ড ধরে মেলানো, মোছা রেকর্ড (tombstone) ফিরে না আসা, দ্বন্দ্ব আলাদা দেখানো। */

const BK_MAX_BYTES = 25*1024*1024;
const BK_MAPS = {tr_attendance:['অ্যাটেন্ডেন্স','att'], tr_notes:['ক্লাস নোট','note'], tr_students:['শিক্ষার্থী প্রোফাইল',''], tr_progress:['অধ্যায়/অগ্রগতি',''], tr_offMap:['ছুটির দিন',''], tr_moves:['স্লট সরানো',''], tr_schedOverrides:['শিডিউল পরিবর্তন','']};
const BK_LISTS = {tr_expenses:['খরচ','exp'], tr_makeups:['মেকআপ ক্লাস',''], tr_todos:['করণীয়',''], tr_results:['পরীক্ষার ফল','res'], tr_adjust:['ফি সমন্বয়',''], tr_qbank:['প্রশ্নপত্র ভান্ডার','']};

/* ---------- pure (unit-tested) ---------- */
function bkHash(s){ let a=0x811c9dc5, b=0x1b873593; for(let i=0;i<s.length;i++){ const c=s.charCodeAt(i); a^=c; a=Math.imul(a,0x01000193)>>>0; b=Math.imul(b^c,0x85ebca6b)>>>0; b^=b>>>13; } return a.toString(16).padStart(8,'0')+b.toString(16).padStart(8,'0')+':'+s.length; }
function bkChecksum(data){ return bkHash(Object.keys(data||{}).sort().map(k=>k+'='+data[k]).join('\n')); }
function bkParse(s, d){ try{ return s==null?d:JSON.parse(s); }catch(e){ return d; } }
function bkCounts(data){ const o={}; Object.keys(data||{}).forEach(k=>{ const v=bkParse(data[k],null); if(Array.isArray(v)) o[k]=v.length; else if(v&&typeof v==='object') o[k]=Object.keys(v).length; }); return o; }
/* ফাইল ঢোকানোর আগে যাচাই: fatal থাকলে ঢোকানো যাবে না */
function bkProblems(payload, knownKeys, schemaMax, size){
  const fatal=[], warn=[];
  if(!payload || typeof payload!=='object' || !payload.data || typeof payload.data!=='object' || Array.isArray(payload.data)){ fatal.push('ফাইলের গঠন ঠিক নেই।'); return {fatal,warn}; }
  if(size && size>BK_MAX_BYTES) fatal.push('ফাইলটা অনেক বড় (২৫ MB-এর বেশি)।');
  if(payload.schema!=null){
    if(!(Number(payload.schema)>=1)) fatal.push('স্কিমা সংস্করণ ঠিক নেই।');
    else if(Number(payload.schema)>schemaMax) fatal.push('এই ব্যাকআপ অ্যাপের নতুন সংস্করণের — আগে অ্যাপ আপডেট করো, নইলে তথ্য নষ্ট হতে পারে।');
  } else warn.push('পুরোনো ফরম্যাটের ব্যাকআপ — ঢোকানোর পর অ্যাপ নিজে নতুন গঠনে আনবে।');
  if(payload.checksum && payload.checksum!==bkChecksum(payload.data)) fatal.push('ফাইলটা নষ্ট বা বদলানো (চেকসাম মেলেনি)।');
  const keys=Object.keys(payload.data), unknown=knownKeys?keys.filter(k=>!knownKeys.includes(k)):[];
  if(unknown.length) warn.push(`${unknown.length}টা অচেনা তথ্য-অংশ বাদ যাবে।`);
  if(!keys.length) fatal.push('ব্যাকআপ খালি।');
  keys.forEach(k=>{ if(typeof payload.data[k]!=='string') fatal.push(`"${k}"-এর মান ঠিক নেই।`); else { try{ JSON.parse(payload.data[k]); }catch(e){ fatal.push(`"${k}"-এর ভেতরের তথ্য নষ্ট।`); } } });
  // একই আইডি দুবার? (তালিকাধর্মী অংশে)
  Object.keys(BK_LISTS).forEach(k=>{ const v=bkParse(payload.data[k],null); if(Array.isArray(v)){ const ids=v.map(x=>x&&x.id).filter(x=>x!=null); if(new Set(ids).size!==ids.length) warn.push(`"${BK_LISTS[k][0]}"-এ একই আইডি একাধিকবার আছে।`); } });
  return {fatal:fatal.slice(0,6), warn};
}
const bkJ=(a,b)=>JSON.stringify(a)===JSON.stringify(b);
function bkPaymentRows(map){ const o={}; Object.keys(map||{}).forEach(n=>{ ((map[n]||{}).payments||[]).forEach(p=>{ if(p&&p.id!=null) o[n+'|'+p.id]=p; }); }); return o; }
/* রিস্টোরের আগের প্রিভিউ: cur → next-এ কী যোগ/বাদ/বদল হবে */
function bkDiff(cur, next){
  const rows=[], cmp=(label,key,A,B)=>{ let add=0,rem=0,chg=0; Object.keys(B).forEach(k=>{ if(!(k in A)) add++; else if(!bkJ(A[k],B[k])) chg++; }); Object.keys(A).forEach(k=>{ if(!(k in B)) rem++; }); if(add||rem||chg||Object.keys(A).length||Object.keys(B).length) rows.push({key,label,cur:Object.keys(A).length,next:Object.keys(B).length,added:add,removed:rem,changed:chg}); };
  Object.keys(BK_MAPS).forEach(k=>{ if(!(k in cur)&&!(k in next)) return; cmp(BK_MAPS[k][0],k,bkParse(cur[k],{})||{},bkParse(next[k],{})||{}); });
  Object.keys(BK_LISTS).forEach(k=>{ if(!(k in cur)&&!(k in next)) return; const toMap=l=>{ const o={}; (Array.isArray(l)?l:[]).forEach((x,i)=>{ o[(x&&x.id!=null)?x.id:'#'+i]=x; }); return o; }; cmp(BK_LISTS[k][0],k,toMap(bkParse(cur[k],[])),toMap(bkParse(next[k],[]))); });
  if('tr_payments' in cur || 'tr_payments' in next){ const ca=bkParse(cur.tr_payments,{})||{}, nb=bkParse(next.tr_payments,{})||{}; cmp('পেমেন্ট','tr_payments',bkPaymentRows(ca),bkPaymentRows(nb));
    let fee=0; Object.keys(nb).forEach(n=>{ if(ca[n] && (ca[n].monthlyFee!==nb[n].monthlyFee || (ca[n].openingBalance||0)!==(nb[n].openingBalance||0))) fee++; }); if(fee) rows.push({key:'tr_payments#fee',label:'ফি/পূর্ব-বকেয়া বদল',cur:fee,next:fee,added:0,removed:0,changed:fee}); }
  const handled=new Set([...Object.keys(BK_MAPS),...Object.keys(BK_LISTS),'tr_payments']); let other=0;
  new Set([...Object.keys(cur),...Object.keys(next)]).forEach(k=>{ if(!handled.has(k) && cur[k]!==next[k]) other++; });
  if(other) rows.push({key:'other',label:'খাতা ও সেটিংস',cur:other,next:other,added:0,removed:0,changed:other});
  return {rows, total:rows.reduce((s,r)=>s+r.added+r.removed+r.changed,0)};
}
/* মার্জ: কিছুই অন্ধভাবে "নতুনটা জেতে" নয়। opts.conflict = 'local' | 'theirs' (শুধু একই রেকর্ডে ভিন্ন মান হলে) */
function bkMerge(cur, next, opts){
  const pref=(opts&&opts.conflict)==='theirs'?'theirs':'local', out={}, rows=[], conflicts=[], now=(opts&&opts.now)||Date.now();
  const tc=bkParse(cur.tr_tombstones,{})||{}, tn=bkParse(next.tr_tombstones,{})||{}, tm=Object.assign({},tn,tc);
  Object.keys(tn).forEach(k=>{ if(tc[k]!=null) tm[k]=Math.max(Number(tc[k])||0,Number(tn[k])||0); });
  const lim=now-180*86400000; Object.keys(tm).forEach(k=>{ if(Number(tm[k])<lim) delete tm[k]; });
  const has=(t,kind,id)=>!!kind && Object.prototype.hasOwnProperty.call(t,kind+':'+id);
  const pick=(a,b)=>pref==='theirs'?b:a;
  const row=(key,label)=>{ const r={key,label,added:0,kept:0,dropped:0,conflicts:0}; rows.push(r); return r; };
  Object.keys(BK_MAPS).forEach(k=>{
    if(!(k in cur)&&!(k in next)) return; const C=bkParse(cur[k],{})||{}, N=bkParse(next[k],{})||{}, [label,kind]=BK_MAPS[k], r=row(k,label), M={};
    Object.keys(C).forEach(id=>{ if(!(id in N)){ if(has(tn,kind,id)){ r.dropped++; } else { M[id]=C[id]; r.kept++; } } });
    Object.keys(N).forEach(id=>{
      if(!(id in C)){ if(has(tc,kind,id)) return; M[id]=N[id]; r.added++; return; }
      if(bkJ(C[id],N[id])){ M[id]=C[id]; return; }
      if(k==='tr_students' && C[id] && N[id] && typeof C[id]==='object' && typeof N[id]==='object'){          // প্রোফাইল: খালি ঘর ভরো, ভিন্ন মান হলে দ্বন্দ্ব
        const m=Object.assign({}, C[id]); let bad=false;
        Object.keys(N[id]).forEach(f=>{ const a=C[id][f], b=N[id][f], ea=(a==null||a===''), eb=(b==null||b===''); if(ea&&!eb) m[f]=b; else if(!ea&&!eb&&!bkJ(a,b)){ bad=true; if(pref==='theirs') m[f]=b; } });
        M[id]=m; if(bad){ r.conflicts++; conflicts.push({key:k,label,id}); } return;
      }
      r.conflicts++; conflicts.push({key:k,label,id}); M[id]=pick(C[id],N[id]);
    });
    out[k]=JSON.stringify(M);
  });
  Object.keys(BK_LISTS).forEach(k=>{
    if(!(k in cur)&&!(k in next)) return; const C=bkParse(cur[k],[]), N=bkParse(next[k],[]), [label,kind]=BK_LISTS[k], r=row(k,label), M=[], idx={};
    (Array.isArray(C)?C:[]).forEach(x=>{ if(x&&x.id!=null&&has(tn,kind,x.id)&&!(Array.isArray(N)&&N.some(y=>y&&y.id===x.id))){ r.dropped++; return; } M.push(x); if(x&&x.id!=null) idx[x.id]=M.length-1; r.kept++; });
    (Array.isArray(N)?N:[]).forEach(x=>{ if(!x||x.id==null){ return; } if(!(x.id in idx)){ if(has(tc,kind,x.id)) return; M.push(x); r.added++; return; }
      const i=idx[x.id]; if(!bkJ(M[i],x)){ r.conflicts++; conflicts.push({key:k,label,id:x.id}); if(pref==='theirs') M[i]=x; } });
    out[k]=JSON.stringify(M);
  });
  if('tr_payments' in cur || 'tr_payments' in next){
    const C=bkParse(cur.tr_payments,{})||{}, N=bkParse(next.tr_payments,{})||{}, r=row('tr_payments','পেমেন্ট'), M={};
    new Set([...Object.keys(C),...Object.keys(N)]).forEach(n=>{
      const a=C[n], b=N[n]; if(!a){ M[n]=b; r.added+=((b.payments||[]).length)||0; return; } if(!b){ M[n]=a; return; }
      const voidedIds=new Set([...(a.voided||[]),...(b.voided||[])].map(p=>p.id)), pays={}, vmap={};
      (a.payments||[]).forEach(p=>{ if(!voidedIds.has(p.id)) pays[p.id]=p; });
      (b.payments||[]).forEach(p=>{ if(voidedIds.has(p.id)||p.id in pays) return; if(has(tc,'pay',p.id)) return; pays[p.id]=p; r.added++; });
      [...(a.voided||[]),...(b.voided||[])].forEach(p=>{ vmap[p.id]=vmap[p.id]||p; });
      const base=x=>(Number(x.openingBalance)||0)+(x.payments||[]).filter(p=>p.monthKey==='opening').reduce((s,p)=>s+p.amount,0), merged={};
      let fee=a.monthlyFee, bs=base(a);
      if(a.monthlyFee!==b.monthlyFee){ r.conflicts++; conflicts.push({key:'tr_payments',label:'মাসিক ফি',id:n}); if(pref==='theirs') fee=b.monthlyFee; }
      if(base(a)!==base(b)){ r.conflicts++; conflicts.push({key:'tr_payments',label:'পূর্ব-বকেয়া',id:n}); if(pref==='theirs') bs=base(b); }
      const list=Object.keys(pays).map(id=>pays[id]), openSum=list.filter(p=>p.monthKey==='opening').reduce((s,p)=>s+p.amount,0);
      Object.assign(merged,a,{monthlyFee:fee, openingBalance:Math.max(0,bs-openSum), payments:list}); const v=Object.keys(vmap).map(id=>vmap[id]); if(v.length) merged.voided=v; M[n]=merged;
    });
    out.tr_payments=JSON.stringify(M);
  }
  const handled=new Set([...Object.keys(BK_MAPS),...Object.keys(BK_LISTS),'tr_payments','tr_tombstones','tr_schemaVer','tr_receiptSeq']); let keptLocal=0, took=0;
  new Set([...Object.keys(cur),...Object.keys(next)]).forEach(k=>{ if(handled.has(k)) return; if(k in cur){ out[k]=cur[k]; if(k in next && cur[k]!==next[k]) keptLocal++; } else { out[k]=next[k]; took++; } });
  if(keptLocal||took) rows.push({key:'other',label:'খাতা ও সেটিংস (স্থানীয়টাই রাখা হয়)',added:took,kept:keptLocal,dropped:0,conflicts:0});
  if('tr_receiptSeq' in cur || 'tr_receiptSeq' in next) out.tr_receiptSeq=JSON.stringify(Math.max(Number(bkParse(cur.tr_receiptSeq,0))||0, Number(bkParse(next.tr_receiptSeq,0))||0));   // রসিদ নম্বর যেন না মেলে
  out.tr_tombstones=JSON.stringify(tm);
  out.tr_schemaVer=JSON.stringify(Math.max(Number(bkParse(cur.tr_schemaVer,0))||0, Number(bkParse(next.tr_schemaVer,0))||0)||70);
  return {data:out, rows, conflicts};
}

/* ---------- screen (প্রিভিউ-এর ভেতরে বসে) ---------- */
let bkMode='replace', bkConflict='local';
function bkSetMode(m){ bkMode=m; const n=document.getElementById('bkModeNote'); if(n) n.innerHTML=bkModeNote(); const c=document.getElementById('bkConfBox'); if(c) c.style.display=m==='merge'?'block':'none'; }
function bkModeNote(){ return bkMode==='merge' ? 'মার্জ: দুই দিকের তথ্য রেকর্ড ধরে মিলবে। কিছু মোছা হবে না (যেগুলো ইচ্ছে করে মোছা, সেগুলো ছাড়া)। একই রেকর্ডে ভিন্ন মান হলে নিচের পছন্দ অনুযায়ী।' : 'রিস্টোর: এখনকার তথ্য এই ব্যাকআপ দিয়ে বদলে যাবে।'; }
function bkPreviewHtml(payload){
  bkMode='replace'; bkConflict='local'; const E=escapeHtml; let d, pr;
  try{ d=bkDiff(collectBackupData(), payload.data); pr=bkProblems(payload, BACKUP_KEYS, SCHEMA_VERSION); }catch(e){ return ''; }
  const rows=d.rows.map(r=>`<div class="makeup-row"><span>${E(r.label)}</span><span class="pay-history-amt" style="font-size:11px;">${r.added?'+'+toBn(r.added)+' ':''}${r.removed?'−'+toBn(r.removed)+' ':''}${r.changed?'~'+toBn(r.changed):''}${(!r.added&&!r.removed&&!r.changed)?'অপরিবর্তিত':''}</span></div>`).join('');
  return `<div style="margin-top:10px;font-size:11px;color:var(--muted);">রিস্টোর করলে কী হবে (+ যোগ · − বাদ · ~ বদল):</div>${rows||'<div class="ins-empty">কোনো পার্থক্য নেই।</div>'}
  ${pr.warn.map(w=>`<div class="qp-iss warn">⚠️ ${E(w)}</div>`).join('')}
  <div class="pct-chip-row" style="margin-top:10px;"><label class="pct-chip"><input type="radio" name="bkm" checked onchange="bkSetMode('replace')"> সম্পূর্ণ রিস্টোর</label><label class="pct-chip"><input type="radio" name="bkm" onchange="bkSetMode('merge')"> 🔀 মার্জ (দুই ফোনের তথ্য মেলাও)</label></div>
  <div class="qp-note-small" id="bkModeNote">${bkModeNote()}</div>
  <div id="bkConfBox" style="display:none;"><div class="qp-note-small">একই রেকর্ডে দুই জায়গায় ভিন্ন মান থাকলে:</div><div class="pct-chip-row"><label class="pct-chip"><input type="radio" name="bkc" checked onchange="bkConflict='local'"> এই ফোনেরটা রাখো</label><label class="pct-chip"><input type="radio" name="bkc" onchange="bkConflict='theirs'"> ব্যাকআপেরটা নাও</label></div><div class="qp-note-small">খাতা ও সেটিংস মার্জ হয় না — এই ফোনেরটাই থাকে।</div></div>`;
}
/* কনফার্মের ঠিক আগে: মার্জ বাছলে payload-এর data মার্জ-করা তথ্য দিয়ে বদলে যায় */
function bkApplyMode(payload){
  if(bkMode!=='merge') return payload;
  const m=bkMerge(collectBackupData(), payload.data, {conflict:bkConflict}), keep={};
  Object.keys(m.data).filter(k=>BACKUP_KEYS.includes(k)).forEach(k=>{ keep[k]=m.data[k]; });
  return Object.assign({}, payload, {data:keep});
}
